```typescript
import * as XLSX from 'xlsx';
import { ProductRow, Mapping } from '../types';
import { GoogleGenAI } from "@google/genai";

// --- CONSTANTS ---
const VALID_ROOTS = [
  'Animals & Pet Supplies',
  'Apparel & Accessories',
  'Arts & Entertainment',
  'Baby & Toddler',
  'Business & Industrial',
  'Cameras & Optics',
  'Electronics',
  'Food, Beverages & Tobacco',
  'Furniture',
  'Hardware',
  'Health & Beauty',
  'Home & Garden',
  'Luggage & Bags',
  'Mature',
  'Media',
  'Office Supplies',
  'Religious & Ceremonial',
  'Software',
  'Sporting Goods',
  'Toys & Games',
  'Vehicles & Parts'
];

// Helper to determine which sheet is likely the "Main" product sheet
const calculateSheetScore = (sheet: { name: string, data: ProductRow[] }): number => {
  const headers = Object.keys(sheet.data[0] || {});
  const rowCount = sheet.data.length;
  const colCount = headers.length;
  const nameLower = sheet.name.toLowerCase();

  // Base score: Rows + Columns
  let score = rowCount + (colCount * 5);

  // Boost for product-critical headers (Evidence of it being the Master)
  const masterKeywords = ['price', 'cost', 'msrp', 'description', 'title', 'product name', 'category', 'inventory', 'stock', 'qty'];
  masterKeywords.forEach(k => {
    if (headers.some(h => h.toLowerCase().includes(k))) score += 500;
  });

  // Boost for ID headers
  if (headers.some(h => h.toLowerCase().includes('sku') || h.toLowerCase().includes('part'))) score += 100;

  // Heavy Penalty for auxiliary sheets (Assets, Images, Legends)
  if (nameLower.includes('asset') || nameLower.includes('image') || nameLower.includes('media') || nameLower.includes('instruction') || nameLower.includes('legend') || nameLower.includes('def')) {
    score -= 5000;
  }

  // Penalty for sheets with very few columns (likely lists/lookups)
  if (colCount < 3) score -= 2000;

  // Penalty for sheets with very few rows (likely headers only or summary)
  if (rowCount < 2) score -= 2000;

  return score;
};

export const parseExcel = async (file: File): Promise<{ headers: string[], data: ProductRow[], logs: string[] }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const logs: string[] = [];

        // 1. Parse all sheets
        let sheetsData: { name: string, data: ProductRow[] }[] = [];

        workbook.SheetNames.forEach(name => {
          // Strict Filter: Skip French sheets immediately
          const lowerName = name.toLowerCase();
          if (lowerName.includes('french') || lowerName.includes('francais') || lowerName.match(/\bfr\b/)) {
              return; 
          }

          const sheet = workbook.Sheets[name];
          const json = XLSX.utils.sheet_to_json<ProductRow>(sheet, { defval: "" });
          if (json.length > 0) {
            sheetsData.push({ name, data: json });
          }
        });

        if (sheetsData.length === 0) {
          resolve({ headers: [], data: [], logs: ['No valid data found.'] });
          return;
        }

        // 2. SMART SORT: Reorder sheets so the "Master" (Best Candidate) is at index 0
        sheetsData.sort((a, b) => {
            const scoreA = calculateSheetScore(a);
            const scoreB = calculateSheetScore(b);
            return scoreB - scoreA; // Descending order
        });

        logs.push(`Master Sheet Selected: ${sheetsData[0].name} (Rows: ${sheetsData[0].data.length})`);

        // 3. Start with the Best Sheet as Master
        let masterData = [...sheetsData[0].data];

        // Helper to normalize values for comparison (removes dashes, spaces, case)
        const normalizeVal = (val: any) => String(val || '').toLowerCase().replace(/[^a-z0-9]/g, '');

        // Blacklist for join keys (avoid joining on "Yes/No" columns)
        const invalidJoinValues = new Set(['yes', 'no', 'true', 'false', 'y', 'n', '0', '1', 'active', 'draft', '', 'manual', 'shopify', 'deny', 'continue']);

        // 4. Merge subsequent sheets using FULL COLUMN SCANNING
        for (let i = 1; i < sheetsData.length; i++) {
          const sheet = sheetsData[i];
          const sheetData = sheet.data;
          if (sheetData.length === 0) continue;

          const masterHeaders = Object.keys(masterData[0] || {});
          const sheetHeaders = Object.keys(sheetData[0] || {});

          let bestMasterKey = '';
          let bestSheetKey = '';
          let bestScore = 0;

          // Aggressive Scanning: Compare EVERY master column with EVERY sheet column
          const masterColSets = new Map<string, Set<string>>();

          masterHeaders.forEach(mCol => {
              // Skip obviously long descriptions to save *some* memory
              if (mCol.length > 100) return; 

              const s = new Set<string>();
              masterData.forEach(r => {
                 const v = normalizeVal(r[mCol]);
                 if (v.length > 2 && !invalidJoinValues.has(v)) s.add(v);
              });
              if (s.size > 0) masterColSets.set(mCol, s);
          });

          // Compare against Sheet Columns
          sheetHeaders.forEach(sCol => {
             // Skip massive text columns
             if (sCol.length > 100) return;

             const sheetVals = new Set<string>();
             sheetData.forEach(r => {
                const v = normalizeVal(r[sCol]);
                if (v.length > 2 && !invalidJoinValues.has(v)) sheetVals.add(v);
             });

             if (sheetVals.size === 0) return;

             for (const [mCol, masterSet] of masterColSets.entries()) {
                 // Intersection Count
                 let intersection = 0;
                 for (const val of sheetVals) {
                     if (masterSet.has(val)) intersection++;
                 }

                 if (intersection > 0) {
                     let score = intersection;

                     // Keyword Bonus: If headers sound like IDs, boost score
                     const mLower = mCol.toLowerCase();
                     const sLower = sCol.toLowerCase();
                     const keywords = ['sku', 'id', 'part', 'number', 'material', 'upc', 'item', 'gtin'];

                     if (keywords.some(k => mLower.includes(k))) score *= 1.5;
                     if (keywords.some(k => sLower.includes(k))) score *= 1.5;

                     // If matches strict "Asset" criteria, boost heavily
                     if (sheet.name.toLowerCase().includes('asset') || sheet.name.toLowerCase().includes('media')) {
                        score *= 2;
                     }

                     if (score > bestScore) {
                         bestScore = score;
                         bestMasterKey = mCol;
                         bestSheetKey = sCol;
                     }
                 }
             }
          });

          // Join if score is reasonable (threshold depends on intersection size)
          // Lowered threshold to ensure we catch the assets even if overlap is small
          if (bestMasterKey && bestSheetKey && bestScore > 2) {
             logs.push(`Linking '${sheetsData[0].name}' via [${bestMasterKey}] to '${sheet.name}' via [${bestSheetKey}] (Score: ${Math.round(bestScore)})`);

             // Build Lookup Table for merging
             const lookup = new Map<string, ProductRow[]>();
             sheetData.forEach(row => {
               const val = normalizeVal(row[bestSheetKey]);
               if (val && val.length > 2) {
                 if (!lookup.has(val)) lookup.set(val, []);
                 lookup.get(val)?.push(row);
               }
             });

             // Merge Data
             masterData = masterData.map(row => {
               const val = normalizeVal(row[bestMasterKey]);
               const matches = lookup.get(val);

               if (matches && matches.length > 0) {
                 const newRow = { ...row };
                 const keysToMerge = Object.keys(matches[0]).filter(k => k !== bestSheetKey);

                 keysToMerge.forEach(key => {
                    // Collect all values from all matching rows (handling one-to-many)
                    const allValues = matches
                      .map(m => m[key])
                      .filter(v => v !== undefined && v !== null && v !== "")
                      .map(v => String(v).trim());

                    const uniqueValues = Array.from(new Set(allValues));
                    if (uniqueValues.length > 0) {
                        // Concatenate multiple values with pipe | for later processing
                        // If the existing row already has this key, append to it
                        const existing = newRow[key] ? String(newRow[key]) + '|' : '';
                        newRow[key] = existing + uniqueValues.join('|'); 
                    }
                 });
                 return newRow;
               }
               return row;
             });
          } else {
             logs.push(`Could not find a link for sheet '${sheet.name}'`);
          }
        }

        // 5. CONSOLIDATE ALL IMAGES
        // Scan every column in every row. If it looks like a image URL, add it to a magic column.
        masterData = masterData.map(row => {
           const allImages: string[] = [];
           // Use Object.entries so we can check the header name
           Object.entries(row).forEach(([key, val]) => {
              if (typeof val === 'string' && val.length > 5) {
                 // STRICT FILTER: Skip columns that are explicitly LOGOs or French
                 const lowerKey = key.toLowerCase();
                 if (lowerKey.includes('logo') || lowerKey.includes('brand image') || lowerKey.includes('brand asset') || lowerKey.includes('french') || lowerKey.includes('francais')) {
                     return;
                 }

                 // Check for pipe-separated URLs (from merge) or single URLs or Comma/Newline separated
                 const parts = val.split(/[|,\n]+/);

                 parts.forEach(p => {
                    const clean = p.trim();
                    if (clean.length < 5) return;

                    // Expanded detection: standard extensions OR edgenet/cdn/widen keywords
                    if (clean.match(/\.(jpg|jpeg|png|webp|gif|bmp|tiff)/i) || 
                        clean.match(/(assets\.edgenet|widen\.net|cloudinary|scene7)/i) || 
                        clean.includes('cdn') || 
                        (clean.includes('http') && clean.includes('image'))) 
                    {
                        // Basic check to exclude description HTML or non-urls
                        if (!clean.includes('<') && !clean.includes(' ') && clean.length < 500) {
                            allImages.push(clean);
                        }
                    }
                 });
              }
           });

           // Deduplicate and join
           const uniqueImages = Array.from(new Set(allImages));
           if (uniqueImages.length > 0) {
               row['_Generated_Images'] = uniqueImages.join('|');
           }
           return row;
        });

        // 6. Extract unique headers
        const allHeaders = new Set<string>();
        masterData.forEach(row => {
            Object.keys(row).forEach(k => allHeaders.add(k));
        });

        resolve({ headers: Array.from(allHeaders), data: masterData, logs });
      } catch (error) {
        reject(error);
      }
    };
    reader.onerror = (error) => reject(error);
    reader.readAsBinaryString(file);
  });
};

const calculateGrams = (value: string, headerName: string = ''): string => {
  if (!value) return '';
  const cleanVal = value.toLowerCase().trim().replace(/,/g, '');
  const numMatch = cleanVal.match(/[0-9.]+/);
  if (!numMatch) return '';

  const num = parseFloat(numMatch[0]);
  if (isNaN(num)) return '';

  const headerLower = headerName.toLowerCase();
  const unitInHeader = (u: string) => headerLower.includes(u);
  const unitInValue = (u: string) => cleanVal.includes(u);

  // 1. Check Explicit Units in Value
  if (unitInValue('kg')) return Math.round(num * 1000).toString();
  if (unitInValue('lb') || unitInValue('pound') || unitInValue('#')) return Math.round(num * 453.592).toString();
  if (unitInValue('oz') || unitInValue('ounce')) return Math.round(num * 28.3495).toString();
  if (unitInValue('g') || unitInValue('gram')) return Math.round(num).toString();

  // 2. Check Explicit Units in Header
  if (unitInHeader('kg')) return Math.round(num * 1000).toString();
  if (unitInHeader('lb') || unitInHeader('pound')) return Math.round(num * 453.592).toString();
  if (unitInHeader('oz') || unitInHeader('ounce')) return Math.round(num * 28.3495).toString();
  if (unitInHeader('g') || unitInHeader('gram')) return Math.round(num).toString();

  // 3. Heuristic based on magnitude
  // If > 100, assume it's already Grams
  if (num > 100) return Math.round(num).toString();

  // If < 100, assume it's LBS (common for tools/hardware/US vendors)
  return Math.round(num * 453.592).toString();
};

const cleanImageUrl = (url: string): string => {
  if (!url) return '';
  let clean = url.trim();

  // Filter out local paths (C:\...)
  if (clean.match(/^[a-zA-Z]:\\/) || clean.startsWith('\\\\')) return ''; 

  // Fix Protocol (// -> https://)
  if (clean.startsWith('//')) {
    clean = 'https:' + clean;
  } else if (!clean.startsWith('http')) {
     // Heuristic: If it looks like a web file or Edgenet/Widen
    if (clean.match(/\.(jpg|jpeg|png|gif|webp)|assets\.edgenet|widen\.net/i)) {
       if (clean.includes('/') && !clean.includes(':/')) {
         clean = 'https://' + clean;
       }
    }
  }

  // Clean quotes
  clean = clean.replace(/['"]/g, '');

  // Encode spaces ONLY. 
  clean = clean.replace(/ /g, '%20');

  // Final validation: must look like a url
  if (!clean.includes('http')) return '';

  try {
      const urlObj = new URL(clean);
      const pathname = urlObj.pathname;

      // CRITICAL FIX: If path is just '/', it's a homepage, not an image.
      if (pathname === '/' || pathname === '') return '';

      // Check if pathname has an extension
      const hasExtension = pathname.match(/\.(jpg|jpeg|png|gif|webp|bmp|tiff)$/i);

      if (!hasExtension) {
          // If query string exists, appending #.jpg is safer than appending .jpg to the end of query string
          // Only append if it doesn't already have one in the path (widen.net URLs often have params but valid paths)
          if (!clean.includes('#')) {
             // Look for common query params that might indicate image type
             if (!clean.includes('format=') && !clean.includes('?')) {
                clean += '#.jpg';
             }
          }
      }
  } catch (e) {
      // If URL parsing fails, fall back to simple string check
      const base = clean.split('?')[0];
      // If it ends in a slash or is empty
      if (base.endsWith('/') || base.length < 10) return '';

      if (!base.match(/\.(jpg|jpeg|png|gif|webp)/i) && !clean.includes('#')) {
          clean += '#.jpg';
      }
  }

  return clean;
};

const cleanValue = (value: any, fieldName: string, headerName: string = ''): string => {
  if (value === null || value === undefined) return '';
  let strVal = String(value).trim();

  if (fieldName.includes('Price') || fieldName === 'Cost') {
    const p = strVal.replace(/[$,]/g, '').trim(); 
    return p ? parseFloat(p).toFixed(2) : '';
  }

  if (fieldName === 'Variant Inventory Qty') {
    return strVal.replace(/[^0-9-]/g, '');
  }

  if (fieldName === 'Barcode') {
    return strVal.replace(/[^0-9]/g, '');
  }

  if (fieldName === 'Variant Grams') {
     return calculateGrams(strVal, headerName);
  }

  if (fieldName === 'Published' || fieldName.includes('Requires') || fieldName.includes('Taxable') || fieldName.includes('Gift')) {
    const lower = strVal.toLowerCase();
    if (lower === 'yes' || lower === '1' || lower === 'true') return 'TRUE';
    if (lower === 'no' || lower === '0' || lower === 'false') return 'FALSE';
    if (fieldName === 'Published') return 'FALSE'; // Default Published to FALSE
    if (fieldName === 'Variant Taxable') return 'TRUE'; // Default Taxable to TRUE
    if (fieldName === 'Variant Requires Shipping') return 'TRUE'; // Default Shipping to TRUE
    return 'FALSE';
  }

  return strVal;
};

const buildHtmlDescription = (row: ProductRow, baseMappedDescription: string, headers: string[]): string => {
  let sections: string[] = [];

  // GATHER FEATURES FIRST (To Deduplicate)
  const bulletCols = headers.filter(h => {
     const lower = h.toLowerCase();
     if (lower.includes('image') || lower.includes('asset') || lower.includes('url')) return false;
     // Exclude columns that are likely the main description
     if (lower === 'description' || lower === 'marketing copy') return false; 
     return (lower.includes('bullet') || lower.includes('feature') || lower.includes('benefit') || lower.includes('highlight')) && row[h];
  });

  bulletCols.sort((a, b) => {
      const numA = parseInt(a.replace(/[^0-9]/g, '') || '0');
      const numB = parseInt(b.replace(/[^0-9]/g, '') || '0');
      return numA - numB;
  });

  const featureStrings: string[] = [];
  bulletCols.forEach(col => {
      let val = String(row[col]).trim();
      if(val) {
          // Remove leading bullets
          val = val.replace(/^[-•*]\s*/, '');
          featureStrings.push(val);
      }
  });

  // 1. OVERVIEW / MARKETING COPY
  const descKeywords = ['description', 'marketing', 'overview', 'details', 'romance', 'summary'];
  const descTexts = new Set<string>();

  if (baseMappedDescription) descTexts.add(baseMappedDescription.trim());

  headers.forEach(h => {
     const lower = h.toLowerCase();
     if (descKeywords.some(k => lower.includes(k)) && !lower.includes('short') && !lower.includes('seo') && !lower.includes('title')) {
         const val = String(row[h] || '').trim();
         // Filter out short garbage, booleans, or file names
         if (val.length > 20 && !val.includes('.jpg') && !['true','false'].includes(val.toLowerCase())) {
             descTexts.add(val); 
         }
     }
  });

  // CLEAN UP DESCRIPTION (Deduplicate)
  const finalDescParagraphs: string[] = [];

  // Get Title for deduplication
  const rowTitle = headers.find(h => h.toLowerCase().includes('title') || h.toLowerCase().includes('product name'));
  const titleVal = rowTitle ? String(row[rowTitle]).toLowerCase().trim() : '';

  Array.from(descTexts).forEach(block => {
      // Split by newline or pipe if it looks like a concatenated block
      // NEW: Split by " / " or " | " as well, handling common CSV concatenations
      const paragraphs = block.split(/(?:\r\n|\r|\n|\s\/\s|\s\|\s)+/);

      paragraphs.forEach(para => {
          let p = para.trim();
          // Filter out delimiters returned by split capture group
          if (p.match(/^[\n\r/|]+$/)) return; 
          if (p.length < 5) return;

          // Remove if it's the EXACT Title (case insensitive)
          if (titleVal && p.toLowerCase() === titleVal) return;

          // Normalize for comparison
          const pNorm = p.toLowerCase().replace(/[^a-z0-9]/g, '');

          // Remove if it matches any feature
          const isDuplicate = featureStrings.some(f => {
              const fNorm = f.toLowerCase().replace(/[^a-z0-9]/g, '');
              // If the paragraph is contained in the feature OR feature is contained in paragraph
              // e.g. p="Quiet", f="Quiet - 58dB" -> match (f includes p)
              // e.g. p="Quiet - 58dB", f="Quiet" -> match (p includes f)
              if (fNorm.length < 4) return false; // Don't filter short words

              return pNorm.includes(fNorm) || fNorm.includes(pNorm);
          });

          if (isDuplicate) return;

          // Remove if it looks like a list of concatenated features (contains multiple ' / ')
          if (p.split(' / ').length > 2 || p.split(' | ').length > 2) {
              return;
          }

          // Remove if it starts with "Features" or "Specifications"
          if (p.toLowerCase().startsWith('features') || p.toLowerCase().startsWith('specifications')) return;

          finalDescParagraphs.push(p);
      });
  });

  const fullDescription = Array.from(new Set(finalDescParagraphs)).join('<br><br>');
  if (fullDescription) {
      sections.push(`<div class="product-description" style="margin-bottom: 24px; line-height: 1.6; color: #374151;">${fullDescription}</div>`);
  }

  // 2. FEATURES (Formatted List)
  if (featureStrings.length > 0) {
    let bulletsHtml = '<div class="product-features" style="margin-bottom: 24px;"><h3 style="font-size: 1.1em; font-weight: 700; margin-bottom: 12px; color: #111827;">Features</h3><ul style="list-style-type: disc; padding-left: 20px; color: #4b5563;">';
    featureStrings.forEach(val => {
       // Smart Bold: If feature has a separator like " - " or ": ", bold the first part
       // e.g. "Powerful Motor - Delivers 500 RPM" -> "<strong>Powerful Motor</strong> - Delivers 500 RPM"
       let content = val;
       const splitMatch = val.match(/^([^:-]+)([:\-])\s*(.+)/);
       if (splitMatch && splitMatch[1].length < 40) {
           content = `<strong>${splitMatch[1].trim()}</strong>${splitMatch[2]} ${splitMatch[3].trim()}`;
       }

       bulletsHtml += `<li style="margin-bottom: 6px; line-height: 1.5;">${content}</li>`;
    });
    bulletsHtml += '</ul></div>';
    sections.push(bulletsHtml);
  }

  // 3. SPECIFICATIONS (Table)
  const specKeywords = [
      'spec', 'dimension', 'width', 'height', 'depth', 'length', 'weight', 'mass', 
      'voltage', 'amp', 'watt', 'torque', 'rpm', 'ipm', 'capacity', 'size', 'material', 
      'color', 'finish', 'style', 'pattern', 'power source', 'battery'
  ];

  const specCols = headers.filter(h => {
    const lower = h.toLowerCase();
    if (lower === 'variant grams' || lower === 'image src' || lower.includes('image')) return false;
    const hasValue = row[h] !== undefined && row[h] !== '' && row[h] !== null;
    if (!hasValue) return false;
    const isKeyword = specKeywords.some(k => lower.includes(k));
    const isExcluded = lower.includes('bullet') || lower.includes('feature') || lower.includes('description') || lower.includes('overview') || lower.includes('seo') || lower.includes('price') || lower.includes('cost');
    return isKeyword && !isExcluded;
  });

  if (specCols.length > 0) {
    let specsHtml = '<div class="product-specs" style="margin-bottom: 24px;"><h3 style="font-size: 1.1em; font-weight: 700; margin-bottom: 12px; color: #111827;">Specifications</h3><div style="border: 1px solid #e5e7eb; border-radius: 8px; overflow: hidden;"><table style="width:100%; border-collapse: collapse; font-size: 0.95em;"><tbody>';
    specCols.forEach((col, idx) => {
       const val = String(row[col]).trim();
       const bg = idx % 2 === 0 ? '#f9fafb' : '#ffffff';
       specsHtml += `<tr style="background-color: ${bg}; border-bottom: 1px solid #e5e7eb;">
         <td style="padding: 10px 16px; font-weight: 600; color: #374151; width: 40%; border-right: 1px solid #e5e7eb;">${col}</td>
         <td style="padding: 10px 16px; color: #4b5563;">${val}</td>
       </tr>`;
    });
    specsHtml += '</tbody></table></div></div>';
    sections.push(specsHtml);
  }

  // 4. INCLUDES / BOX CONTENTS (From File)
  const includeCols = headers.filter(h => {
      const lower = h.toLowerCase();
      return (lower.includes('include') || lower.includes('content') || lower.includes('in the box')) && row[h] && !lower.includes('description');
  });

  if (includeCols.length > 0) {
      let includesHtml = '<div class="product-includes" style="margin-bottom: 24px;"><h3 style="font-size: 1.1em; font-weight: 700; margin-bottom: 10px; color: #111827;">Includes</h3><p style="color: #4b5563; line-height: 1.6;">';
      const vals: string[] = [];
      includeCols.forEach(c => vals.push(String(row[c]).trim()));
      includesHtml += vals.join(', ');
      includesHtml += '</p></div>';
      sections.push(includesHtml);
  }

  // 5. WARRANTY (From File)
  const warrantyCols = headers.filter(h => {
      const lower = h.toLowerCase();
      return (lower.includes('warranty') || lower.includes('guarantee')) && row[h];
  });

  if (warrantyCols.length > 0) {
       let warHtml = '<div class="product-warranty" style="margin-bottom: 24px; padding: 16px; background-color: #f3f4f6; border-radius: 8px;"><h3 style="font-size: 1.1em; font-weight: 700; margin-bottom: 8px; color: #111827;">Warranty</h3><p style="color: #4b5563; margin: 0;">';
       const vals: string[] = [];
       warrantyCols.forEach(c => vals.push(String(row[c]).trim()));
       warHtml += vals.join(' ');
       warHtml += '</p></div>';
       sections.push(warHtml);
  }

  return sections.join('');
};

// Smart Tags/Type Generation
const getCategoryAndTags = (row: ProductRow, sourceHeaders: string[], mapping: Mapping, title: string) => {
  const tags: string[] = [];
  let detectedType = '';
  let taxonomyCategory = '';

  const catKeywords = ['category', 'class', 'sub-class', 'subcategory', 'type', 'group', 'collection', 'department'];

  sourceHeaders.forEach(h => {
    const lower = h.toLowerCase();
    // Use column value for Tags if it's a category-like column
    if (catKeywords.some(k => lower.includes(k))) {
      const val = row[h];
      if (val) {
        const cleanVal = String(val).trim();
        if (cleanVal.length > 2) {
            tags.push(cleanVal);

            // If it looks like a category, save it as a candidate
            if (!taxonomyCategory || cleanVal.includes('>')) {
                taxonomyCategory = cleanVal;
            }

            if (!detectedType) {
                detectedType = cleanVal;
            }
        }
      }
    }
  });

  // Explicit Type Mapping Override
  if (mapping['Type'] && row[mapping['Type']]) {
      detectedType = String(row[mapping['Type']]).trim();
  }

  // Explicit Tags Mapping Append
  if (mapping['Tags'] && row[mapping['Tags']]) {
      tags.push(String(row[mapping['Tags']]));
  }

  // Basic validation for Shopify Taxonomy
  if (taxonomyCategory && !VALID_ROOTS.some(r => taxonomyCategory.startsWith(r))) {
      // If it doesn't start with a valid root, check if we can assume it's a simple category
      if (!taxonomyCategory.includes('>')) {
          taxonomyCategory = ''; // Reset if it's just a single word that isn't a root
      }
  }

  return { type: detectedType, tags: tags.join(', '), taxonomyCategory };
};

export const generateShopifyData = (sourceData: ProductRow[], mapping: Mapping): ProductRow[] => {
  const allHeaders = sourceData.length > 0 ? Object.keys(sourceData[0]) : [];

  return sourceData.flatMap((row) => {
    const newRow: ProductRow = {};

    // 1. Basic Mapping
    let title = '';
    let mappedBody = '';
    let brand = '';

    for (const [shopifyField, sourceHeader] of Object.entries(mapping)) {
      if (sourceHeader && row[sourceHeader] !== undefined) {
        newRow[shopifyField] = cleanValue(row[sourceHeader], shopifyField, sourceHeader);
        if (shopifyField === 'Title') title = String(row[sourceHeader]);
        if (shopifyField === 'Body (HTML)') mappedBody = String(row[sourceHeader]);
        if (shopifyField === 'Vendor') brand = String(row[sourceHeader]).trim();
      } else {
        newRow[shopifyField] = '';
      }
    }

    // 2. Constants & Defaults
    newRow['Variant Inventory Tracker'] = 'shopify';
    newRow['Variant Inventory Policy'] = 'continue'; // Updated default to continue per user template
    newRow['Variant Fulfillment Service'] = 'manual';
    newRow['Option1 Name'] = 'Title';
    newRow['Option1 Value'] = 'Default Title';

    // If brand wasn't mapped, leave empty or default if needed. 
    if (!newRow['Vendor']) {
         newRow['Vendor'] = brand;
    }

    newRow['Status'] = 'draft'; // Default draft to allow user pricing updates

    // Boolean Defaults
    newRow['Variant Requires Shipping'] = 'TRUE';
    newRow['Variant Taxable'] = 'TRUE';
    newRow['Gift Card'] = 'FALSE';

    // 3. Smart Data Generation - USE ALL HEADERS
    newRow['Body (HTML)'] = buildHtmlDescription(row, mappedBody, allHeaders);

    // 4. SKU & Title Logic (Required for Category matching)
    let rawSku = mapping['Variant SKU'] ? String(row[mapping['Variant SKU']] || '').trim() : '';
    const invalidSkus = ['no', 'yes', 'true', 'false', 'active', 'draft', 'y', 'n', 'continue', 'deny'];
    if (invalidSkus.includes(rawSku.toLowerCase())) {
        rawSku = ''; 
    }
    newRow['Variant SKU'] = rawSku; 

    // Dynamic Title Construction: [Brand] [SKU] [CleanTitle]
    let cleanTitle = title;

    // Remove brand from title to avoid duplication ("Nike Nike Air Jordan")
    if (brand) {
        const brandRegex = new RegExp(brand, 'gi');
        cleanTitle = cleanTitle.replace(brandRegex, '').trim();
    }

    // Remove SKU from title to avoid duplication
    if (rawSku && cleanTitle.includes(rawSku)) {
         cleanTitle = cleanTitle.replace(rawSku, '').trim();
    }

    cleanTitle = cleanTitle.replace(/^[- ]+|[- ]+$/g, '');

    // Construct final title
    const parts = [brand, rawSku, cleanTitle].filter(p => p && p.length > 0);
    const finalTitle = parts.join(' ').replace(/\s+/g, ' ').trim();
    newRow['Title'] = finalTitle;

    // 5. Category Logic
    const { type, tags, taxonomyCategory } = getCategoryAndTags(row, allHeaders, mapping, finalTitle);
    newRow['Type'] = ''; // Explicitly empty Type per preference
    newRow['Tags'] = tags;
    newRow['Product Category'] = taxonomyCategory; 

    // 6. Handle Generation
    if (!newRow['Handle']) {
      newRow['Handle'] = String(newRow['Title']).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
    }

    // 7. Image Handling (One-to-Many Expansion)
    const mappedImageHeader = mapping['Image Src'];
    let mappedImageVal = '';

    if (mappedImageHeader) {
         const lowerHeader = mappedImageHeader.toLowerCase();
         if (!lowerHeader.includes('logo') && !lowerHeader.includes('brand')) {
             mappedImageVal = row[mappedImageHeader];
         }
    }

    const generatedImageVal = row['_Generated_Images'];
    let finalImages: string[] = [];

    const isValidImage = (url: string) => {
        const lower = url.toLowerCase();
        // Allow brand in name, but still filter specific "logo" files unless they are product shots
        if (lower.includes('logo') && !lower.includes('product')) return false;
        return true;
    };

    // Add Primary Mapped Image first (HERO IMAGE - Strict Order 0)
    if (mappedImageVal) {
        const primarySplit = String(mappedImageVal).split(/[|;\n,]+/).map(cleanImageUrl).filter(s => s.length > 5 && isValidImage(s));
        finalImages.push(...primarySplit);
    }

    // Add Generated Images (Merged from assets), but avoid duplicates
    if (generatedImageVal) {
        const genSplit = String(generatedImageVal).split(/[|;\n,]+/).map(cleanImageUrl).filter(s => s.length > 5 && isValidImage(s));
        genSplit.forEach(img => {
            if (!finalImages.includes(img)) {
                finalImages.push(img);
            }
        });
    }

    if (finalImages.length > 0) {
         // Primary Row gets Image 1
         const firstRow = { 
             ...newRow, 
             'Image Src': finalImages[0], 
             'Image Position': 1, 
             'Image Alt Text': newRow['Title'] // Set Alt Text to Title
         };

         // Subsequent Rows (Image Only)
         const extraRows = finalImages.slice(1).map((img: string, idx: number) => ({
            'Handle': firstRow['Handle'],
            'Image Src': img,
            'Image Position': idx + 2,
            'Image Alt Text': newRow['Title'] // Set Alt Text to Title for all images
         }));

         return [firstRow, ...extraRows];
    }

    return [newRow];
  });
};

export const createProductFromSku = async (brand: string, sku: string, apiKey: string): Promise<ProductRow[]> => {
    const ai = new GoogleGenAI({ apiKey });

    // UPDATED PROMPT: "Safe & Stable" Strategy
    const prompt = `
    You are a Shopify Product Data generator.
    Research the product with Brand: "${brand}" and SKU/Model: "${sku}".

    CRITICAL: FIND WORKING IMAGES.
    1. Search for the product on major platforms: Amazon, Home Depot, Lowes, Acme Tools.
    2. Extract the DIRECT IMAGE URL from these results.
       - Amazon images (m.media-amazon.com) are excellent.
       - Home Depot images (images.thdstatic.com) are excellent.
       - Official Brand "og:image" (Open Graph) URLs are excellent.
    3. AVOID small regional retailers (like rings-end.com) whose links might die.
    4. Find at least 3 images.

    Return a single JSON object with the following fields:
    - title: The full product title (Include Brand + SKU + Name).
    - vendor: The brand name.
    - body_html: A professional HTML description.
    - product_type: The specific product type.
    - category: The exact Google Product Category full path string.
    - weight_g: Approximate weight in grams.
    - price: Approximate MSRP.
    - tags: Comma separated tags.
    - images: An array of DIRECT, PUBLICLY ACCESSIBLE image URLs.
      - Return the URL exactly as found.
      - Do NOT return "base64" data.

    Do NOT return markdown formatting. Return only the raw JSON string.
    `;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { 
                tools: [{googleSearch: {}}],
            }
        });

        if (!response.text) throw new Error("No data returned from AI");

        // Robust Extraction
        let jsonStr = response.text;
        const firstOpen = jsonStr.indexOf('{');
        const lastClose = jsonStr.lastIndexOf('}');

        if (firstOpen !== -1 && lastClose !== -1) {
            jsonStr = jsonStr.substring(firstOpen, lastClose + 1);
        } else {
            jsonStr = jsonStr.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/```$/, '').trim();
        }

        let data;
        try {
             data = JSON.parse(jsonStr);
        } catch (e) {
             console.error("JSON Parse failed. Raw text:", response.text);
             throw new Error("AI returned invalid JSON format.");
        }

        // Construct Shopify Row
        const handle = (data.title || `${brand}-${sku}`).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

        // Process Images with Smart Cleanup
        let validImages: string[] = [];
        if (Array.isArray(data.images)) {
             validImages = data.images
                .map((url: string) => {
                    if (!url || typeof url !== 'string') return '';
                    let clean = url.trim();
                    clean = clean.replace(/['"]/g, '').replace(/\s/g, '%20');
                    if (clean.startsWith('//')) clean = 'https:' + clean;
                    if (!clean.startsWith('http')) return '';

                    const lower = clean.toLowerCase();

                    // 1. REJECT BROKEN / TRUNCATED URLS
                    if (clean.includes('...') || clean.endsWith('.')) return '';
                    if (lower.includes('google.com/imgres') || lower.includes('base64')) return '';

                    // 2. WHITELIST FOR EXTENSION-LESS URLS
                    const extensionLessHosts = [
                        'images.thdstatic.com',
                        'mobileimages.lowes.com',
                        'scene7.com',
                        'cloudinary.com',
                        'walmartimages.com',
                        'mscdirect.com',
                        'cdn.shopify.com',
                        'm.media-amazon.com',
                        'media-amazon.com'
                    ];
                    const isWhitelisted = extensionLessHosts.some(h => lower.includes(h));

                    // 3. EXTENSION CHECK
                    const hasImgExt = /\.(jpg|jpeg|png|webp|gif|bmp|tiff)($|\?)/i.test(lower);

                    // If no extension and not whitelisted, reject (blocks product pages)
                    if (!hasImgExt && !isWhitelisted) {
                        return '';
                    }

                    // 4. NO URL REWRITING (Preserve Signatures)
                    // We rely on the AI finding the correct URL. Modifying params causes 403s.

                    return clean;
                })
                .filter((url: string) => url.length > 10);
        }

        // If no images found by AI, try to provide an empty one so row exists
        if (validImages.length === 0) validImages.push('');

        const mainRow: ProductRow = {
            'Handle': handle,
            'Title': data.title,
            'Body (HTML)': data.body_html,
            'Vendor': data.vendor || brand,
            'Product Category': data.category,
            'Type': data.product_type,
            'Tags': data.tags,
            'Published': 'FALSE',
            'Option1 Name': 'Title',
            'Option1 Value': 'Default Title',
            'Variant SKU': sku,
            'Variant Grams': data.weight_g || '',
            'Variant Inventory Tracker': 'shopify',
            'Variant Inventory Qty': '0',
            'Variant Inventory Policy': 'continue',
            'Variant Fulfillment Service': 'manual',
            'Variant Price': data.price || '',
            'Variant Requires Shipping': 'TRUE',
            'Variant Taxable': 'TRUE',
            'Status': 'draft',
            'Image Src': validImages[0], 
            'Image Position': 1,
            'Image Alt Text': data.title
        };

        const resultRows = [mainRow];

        // Add additional image rows (Shopify expects subsequent images on new rows with same Handle)
        for (let i = 1; i < validImages.length; i++) {
            resultRows.push({
                'Handle': handle,
                'Image Src': validImages[i],
                'Image Position': i + 1,
                'Image Alt Text': data.title
            });
        }

        return resultRows;

    } catch (error) {
        console.error("AI Generation Error:", error);
        throw new Error("Failed to generate product from SKU. Please try again.");
    }
};

export const downloadCSV = (data: ProductRow[], filename: string = 'shopify_import.csv') => {
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Products");
  XLSX.writeFile(wb, filename);
};

To address the persistent 404/dead link issues and the specific failure with `unilogcorp`, I am updating both `services/excelService.ts` and `components/PreviewStep.tsx`.

**The Fixes:**
1.  **Preview Fix (`PreviewStep.tsx`)**: I am adding `referrerPolicy="no-referrer"` to the image preview. This prevents the "403 Forbidden" errors that often appear as broken images inside the app, ensuring that if a link works in your browser, it works in the app too.
2.  **Hard Blacklist (`excelService.ts`)**: I have added `unilogcorp` and other unstable hosts to the negative prompt instructions AND the code filter. This double-layer security ensures they are never returned.
3.  **Gold Standard Prioritization (`excelService.ts`)**: The code now sorts the found images. It bubbles up URLs from "Gold Standard" domains (Amazon, Home Depot, Lowe's, Shopify) to the top of the list, so the primary image is always the most reliable one found.

# Updated files:

## components/PreviewStep.tsx

Added `referrerPolicy="no-referrer"` to image tag to prevent hotlink blocking (403s).

## services/excelService.ts

Updated prompt to explicitly ban unilogcorp, implemented 'Gold Standard' domain sorting to prioritize Amazon/Home Depot/Shopify images, and refined blacklist.

