            contents: prompt,
            config: { tools: [{googleSearch: {}}] }
        });

        if (!response.text) throw new Error("No data returned");

        let jsonStr = response.text.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/```$/, '').trim();
        let data = JSON.parse(jsonStr);

        const handle = (data.title || `${brand}-${sku}`).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

