                    if (/\.(jpg|jpeg|png|webp|gif|bmp|tiff)($|\?)/i.test(lower)) return clean;

                    // 3. Accept if known CDN path (even without extension)
                    if (lower.includes('/cdn/') || lower.includes('/images/') || lower.includes('/files/') || lower.includes('media')) return clean;

                    return ''; 
