    You are a Shopify Product Data generator and SEO specialist.
    Research the product with Brand: "${brand}" and SKU/Model: "${sku}".

    TASK: Find product data and images, and generate a high-converting HTML description.

    STRATEGY FOR PRICING (STRICT PRIORITY):
    1. You MUST search for the price in Canadian Dollars (CAD).
    2. PRIORITY 1: Search specifically on Atlas Tools & Machinery (atlas-machinery.com). If found here, USE THIS PRICE.
    3. PRIORITY 2: If NOT found at Atlas, search BC Fasteners & Tools (bcfasteners.com).
    4. PRIORITY 3: If neither have it, check Home Depot Canada or KMS Tools.
    5. Return just the number (e.g. 149.99).

    STRATEGY FOR IMAGES:
    1. Search widely using Google Images logic.
    2. Try official brand sites first, but also check major retailers.
    3. Look for "File URLs" (ending in .jpg, .png) or standard CDN links.
    4. You MUST find at least 3 distinct images.
    5. Do not limit yourself to specific domains, but AVOID "unilogcorp" and "rings-end".
    6. IMPORTANT: Prioritize finding the PRODUCT PAGE URL where these images are located.

    RETURN JSON FORMAT:
    Return a single JSON object with these fields:

    - title: The full product title (Brand + SKU + Product Name).
    - vendor: The brand name.
    - product_type: The specific product type.
    - category: The exact Google Product Category full path string.
    - weight_g: Approximate weight in grams.
    - price: Approximate price in CAD (number only, no currency symbol).
    - tags: Comma separated tags (features, material, use-case).
    - images: Array of direct image URLs (no base64).
    - source_url: The single best URL where you found these images (e.g. manufacturer page).

    - body_html: A fully formatted HTML string containing:
        1. <div class="description-hero">A polished marketing paragraph (50-75 words) focusing on benefits.</div>
        2. <div class="features-section"><h3>Features</h3><ul>...5-8 bullet points...</ul></div>
        3. <div class="specs-section"><h3>Specifications</h3>...HTML table of specs...</div>
        4. <div class="extras-section">Warranty info and Box contents.</div>

    IMPORTANT: Return ONLY valid JSON. Wrap the JSON in a markdown code block like:
    \`\`\`json
    { ... }
    \`\`\`
    `;

    const safetySettings = [
        { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_NONE' },
        { category: 'HARM_CATEGORY_HARASSMENT', threshold: 'BLOCK_NONE' },
        { category: 'HARM_CATEGORY_HATE_SPEECH', threshold: 'BLOCK_NONE' },
        { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_NONE' }
    ];

    let textResponse = '';

    // ATTEMPT 1: With Google Search (Standard)
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: { 
                tools: [{googleSearch: {}}],
                safetySettings
            }
        });
        textResponse = response.text || '';
    } catch (e) {
        console.warn("Attempt 1 (Search) failed. Trying fallback.", e);
    }

    // ATTEMPT 2: Fallback without Search (if search blocked or failed)
    if (!textResponse) {
        try {
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: prompt,
                config: { safetySettings }
            });
            textResponse = response.text || '';
        } catch (e) {
            console.error("Attempt 2 (Fallback) failed.", e);
             throw new Error("AI service is currently unavailable. Please check your API key and quota.");
        }
    }

    if (!textResponse) throw new Error("No data returned from AI.");

    let data;
    try {
            let jsonStr = textResponse;
            const firstOpen = jsonStr.indexOf('{');
            const lastClose = jsonStr.lastIndexOf('}');

            if (firstOpen !== -1 && lastClose !== -1) {
                jsonStr = jsonStr.substring(firstOpen, lastClose + 1);
            } else {
                jsonStr = jsonStr.replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/```$/, '').trim();
            }

            data = JSON.parse(jsonStr);
    } catch (e) {
            console.error("JSON Parse failed. Raw text:", textResponse);
            throw new Error("AI returned invalid JSON format.");
    }

    const finalVendor = normalizeVendor(data.vendor || brand);

    // Construct Shopify Row
    const handle = (data.title || `${brand}-${sku}`).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

    // Process Images with Relaxed Validator
    let validImages: string[] = [];
    if (Array.isArray(data.images)) {
            validImages = data.images
            .map((url: string) => {
                if (!url || typeof url !== 'string') return '';
                let clean = url.trim();
                clean = clean.replace(/['"]/g, '').replace(/\s/g, '%20');
                if (clean.startsWith('//')) clean = 'https:' + clean;
                if (!clean.startsWith('http')) return '';

                const lower = clean.toLowerCase();

                // 1. REJECT KNOWN BAD LINKS
                if (clean.includes('...') || clean.endsWith('.')) return '';
                if (lower.includes('google.com/imgres') || lower.includes('base64')) return '';

                // 2. BLOCKLIST (Crucial)
                if (lower.includes('unilogcorp') || lower.includes('rings-end') || lower.includes('no-image') || lower.includes('placeholder')) return '';

                // 3. BROAD ACCEPTANCE: If it has an image extension, take it.
                const hasImgExt = /\.(jpg|jpeg|png|webp|gif|bmp|tiff)($|\?)/i.test(lower);

                if (hasImgExt) {
                    return clean;
                }

                // 4. FALLBACK: If no extension, check if it's a known CDN/Asset path
                const isAssetPath = lower.includes('/cdn/') || lower.includes('/files/') || lower.includes('/uploads/') || lower.includes('/images/') || lower.includes('/wp-content/') || lower.includes('/media/') || lower.includes('scene7') || lower.includes('thdstatic');

                if (isAssetPath) {
                    // Shopify Hack: If missing extension, try appending .jpg
                    if (!clean.includes('#') && !clean.includes('?')) {
                            return clean + '#.jpg'; 
                    }
                    return clean;
                }

                return '';
            })
            .filter((url: string) => url.length > 10)
            // SORT: Prioritize Amazon/HomeDepot/Shopify (Gold Standard) but keep others
            .sort((a, b) => {
                const goldStandard = ['media-amazon', 'thdstatic', 'shopify', 'lowes', 'scene7'];
                const aScore = goldStandard.some(g => a.toLowerCase().includes(g)) ? 1 : 0;
                const bScore = goldStandard.some(g => b.toLowerCase().includes(g)) ? 1 : 0;
                return bScore - aScore; // Descending
            });
    }

    // If no images found by AI, try to provide an empty one so row exists
    if (validImages.length === 0) validImages.push('');

    const mainRow: ProductRow = {
        'Handle': handle,
        'Title': data.title,
        'Body (HTML)': data.body_html,
        'Vendor': finalVendor,
        'Product Category': data.category,
        'Type': data.product_type,
        'Tags': data.tags,
        'Published': 'FALSE',
        'Option1 Name': 'Title',
        'Option1 Value': 'Default Title',
        'Variant SKU': sku,
        'Variant Grams': data.weight_g || '',
        'Variant Inventory Tracker': 'shopify',
        'Variant Inventory Qty': '0',
        'Variant Inventory Policy': 'continue',
        'Variant Fulfillment Service': 'manual',
        'Variant Price': data.price || '',
        'Variant Requires Shipping': 'TRUE',
        'Variant Taxable': 'TRUE',
        'Status': 'draft',
        'Image Src': validImages[0], 
        'Image Position': 1,
        'Image Alt Text': data.title,
        'Source URL': data.source_url || '',
        // Add SEO defaults from AI data
        'SEO Title': data.title ? data.title.substring(0, 70) : '',
        'SEO Description': data.body_html ? data.body_html.replace(/<[^>]+>/g, '').substring(0, 320) : ''
    };

    const resultRows = [mainRow];
    for (let i = 1; i < validImages.length; i++) {
        resultRows.push({
            'Handle': handle,
            'Image Src': validImages[i],
            'Image Position': i + 1,
            'Image Alt Text': data.title
        });
    }

    return resultRows;
};

export const downloadCSV = (data: ProductRow[], filename: string = 'shopify_import.csv') => {
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Products");
  XLSX.writeFile(wb, filename);
};

import React, { useState, useRef } from 'react';
import { ProductRow } from '../types';
import { downloadCSV } from '../services/excelService';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { GoogleGenAI } from "@google/genai";

interface PreviewStepProps {
  data: ProductRow[];
  onDataUpdate: (newData: ProductRow[]) => void;
  onReset: () => void;
}

export const PreviewStep: React.FC<PreviewStepProps> = ({ data, onDataUpdate, onReset }) => {
  const [activeTab, setActiveTab] = useState<'preview' | 'stats'>('preview');
  const [searchTerm, setSearchTerm] = useState('');
  const [enhancedDescription, setEnhancedDescription] = useState<string>('');
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [selectedRowIndex, setSelectedRowIndex] = useState(0);
  const [sources, setSources] = useState<{title: string, uri: string}[]>([]);
  const [bulkTagInput, setBulkTagInput] = useState('');
  const [isBulkTagOpen, setIsBulkTagOpen] = useState(false);

  // Bulk Processing State
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [bulkProgress, setBulkProgress] = useState({ current: 0, total: 0, successes: 0, failures: 0 });
  const [processingStatus, setProcessingStatus] = useState('');
  const stopProcessingRef = useRef(false);

  // Stats Calculation
  const totalProducts = data.length;
  const withImages = data.filter(r => r['Image Src']).length;
  const withSKU = data.filter(r => r['Variant SKU']).length;
  const withPrice = data.filter(r => r['Variant Price']).length;

  const chartData = [
    { name: 'Total', value: totalProducts },
    { name: 'Images', value: withImages },
    { name: 'SKUs', value: withSKU },
    { name: 'Prices', value: withPrice },
  ];

  const handleDownload = () => {
    downloadCSV(data);
  };

  const getApiKey = (): string | undefined => {
      try {
          // @ts-ignore
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              // @ts-ignore
              return process.env.API_KEY;
          }
      } catch (e) {
          console.error("Error accessing process.env:", e);
      }
      return undefined;
  };

  const constructPrompt = (vendor: string, title: string, currentDesc: string, tags: string, category: string, needsPrice: boolean) => {
    return `You are a professional e-commerce content strategist. Research the product '${vendor} ${title}' using Google Search.

    Context:
    - Existing Tags: ${tags}
    - Category: ${category}

    Task: Write a high-converting, SEO-optimized Shopify product description (HTML format).
    ${needsPrice ? `
    IMPORTANT: The current price is MISSING. 
    1. Search for the price in Canadian Dollars (CAD).
    2. PRIORITY 1: Search specifically on Atlas Tools & Machinery (atlas-machinery.com). If found here, USE THIS PRICE.
    3. PRIORITY 2: If NOT found at Atlas, search BC Fasteners & Tools (bcfasteners.com).
    4. PRIORITY 3: If neither have it, check Home Depot Canada or KMS Tools.
    5. Return just the number (e.g. 149.99).
    ` : ''}

    Structure Required:
    1. <div class="description-hero">
       Write ONE polished, engaging marketing paragraph (approx 50-75 words). 
       Focus on the "Why" and "Who it's for". 
       </div>

    2. <div class="features-section">
       <h3>Features</h3>
       <ul>
       [Create 5-8 distinct bullet points based on your research.]
       </ul>
       </div>

    3. <div class="specs-section">
       <h3>Specifications</h3>
       [Create a clean HTML table with key specs like dimensions, material, power, etc. if found.]
       </div>

    4. <div class="extras-section">
       <p><strong>Warranty:</strong> [Find specific warranty terms. If unknown, say "Standard Manufacturer Warranty"]</p>
       <p><strong>Includes:</strong> [List box contents. If unknown, omit this line.]</p>
       </div>

    5. METADATA SECTION (At the very end, separated by |||):
       TYPE: [Specific Product Type]
       CATEGORY: [Google Product Category Taxonomy]
       ${needsPrice ? 'PRICE: [The CAD price you found, number only]' : ''}

    Output Format:
    Return ONLY the HTML content, followed by "|||" and the Metadata.
    Do NOT use markdown code blocks. Output raw text.
    `;
  };

  const processAIResponse = (text: string): { html: string, type: string, category: string, price: string } => {
    const result = { html: '', type: '', category: '', price: '' };

    // Clean potential markdown
    let cleanText = text.replace(/^```html\s*/i, '').replace(/^```\s*/, '').replace(/```$/, '').trim();

    // Robust Parsing
    const parts = cleanText.split('|||');

    // Part 1: HTML
    if (parts.length > 0) {
        result.html = parts[0].trim();
    }

    // Part 2: Metadata
    if (parts.length > 1) {
        const metadata = parts[1];
        const typeMatch = metadata.match(/TYPE:\s*([^\n]+)/i);
        const catMatch = metadata.match(/CATEGORY:\s*([^\n]+)/i);
        const priceMatch = metadata.match(/PRICE:\s*([0-9.]+)/i);

        if (typeMatch) result.type = typeMatch[1].trim();
        if (catMatch) result.category = catMatch[1].trim();
        if (priceMatch) result.price = priceMatch[1].trim();
    }

    return result;
  };

  const handleEnhanceSingle = async () => {
    const apiKey = getApiKey();
    if (!apiKey) { alert("No API Key configured. Please check your .env file."); return; }

    setIsEnhancing(true);
    setSources([]);
    setEnhancedDescription('');

    try {
      const row = data[selectedRowIndex];
      const needsPrice = !row['Variant Price'];

      const ai = new GoogleGenAI({ apiKey });
      const prompt = constructPrompt(
          String(row['Vendor'] || ''), 
          String(row['Title'] || ''), 
          String(row['Body (HTML)'] || '').replace(/<[^>]*>?/gm, ''), 
          String(row['Tags'] || ''),
          String(row['Product Category'] || ''),
          needsPrice
      );

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { tools: [{googleSearch: {}}] }
      });

      if (!response.text) throw new Error("No text returned from AI");

      const { html, price } = processAIResponse(response.text);
      setEnhancedDescription(html);

      // If we found a price for a single item, verify with user before saving? 
      // Or just save it when they click "Save". 
      // We will store it in a temporary state or alert the user.
      if (price && needsPrice) {
          alert(`Found Price: $${price} CAD. Will be saved when you click Save.`);
          // Store it temporarily in row? No, let's just handle it in handleSaveSingle if needed.
          // For now, simpler to just auto-update the row in background or let user know.
          const newData = [...data];
          newData[selectedRowIndex]['Variant Price'] = price;
          onDataUpdate(newData);
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        setSources(chunks.map(c => c.web).filter(w => w).map(w => ({ title: w!.title || 'Source', uri: w!.uri! })));
      }

    } catch (e: any) {
      console.error(e);
      alert(`Failed to enhance: ${e.message}`);
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleBulkEnhance = async (onlyMissingPrices: boolean = false) => {
    const apiKey = getApiKey();
    if (!apiKey) { 
        alert("System Error: API_KEY is missing. Cannot perform AI enhancement."); 
        return; 
    }

    // Select rows: Either ALL parent rows, OR only those missing prices
    let targetIndices = data.map((r, i) => r['Title'] ? i : -1).filter(i => i !== -1);

    if (onlyMissingPrices) {
        targetIndices = targetIndices.filter(i => !data[i]['Variant Price']);
        if (targetIndices.length === 0) {
            alert("All items already have prices!");
            return;
        }
    }

    // 2. Start State
    setIsBulkProcessing(true);
    setProcessingStatus(onlyMissingPrices ? 'Finding missing prices...' : 'Starting AI Research Agent...');
    stopProcessingRef.current = false;
    setBulkProgress({ current: 0, total: targetIndices.length, successes: 0, failures: 0 });

    const newData = [...data];
    const ai = new GoogleGenAI({ apiKey });

    try {
        for (let i = 0; i < targetIndices.length; i++) {
            if (stopProcessingRef.current) break;

            const idx = targetIndices[i];
            const row = newData[idx];
            const titleShort = String(row['Title'] || 'Item').substring(0, 40);
            const needsPrice = !row['Variant Price'];

            setProcessingStatus(`Researching (${i + 1}/${targetIndices.length}): ${titleShort}...`);
            setBulkProgress(prev => ({ ...prev, current: i + 1 }));

            const prompt = constructPrompt(
                String(row['Vendor'] || ''), 
                String(row['Title'] || ''), 
                String(row['Body (HTML)'] || '').replace(/<[^>]*>?/gm, ''), 
                String(row['Tags'] || ''),
                String(row['Product Category'] || ''),
                needsPrice
            );

            let retryCount = 0;
            let success = false;

            while (!success && retryCount < 2) {
                try {
                    const response = await ai.models.generateContent({
                        model: 'gemini-3-flash-preview',
                        contents: prompt,
                        config: { tools: [{googleSearch: {}}] }
                    });

                    if (response.text) {
                        const { html, type, category, price } = processAIResponse(response.text);
                        // Only update HTML if we aren't just looking for prices, OR if the current HTML is very short
                        if (!onlyMissingPrices || (String(row['Body (HTML)']).length < 50)) {
                             if (html && html.length > 50) newData[idx]['Body (HTML)'] = html;
                        }

                        if (type) newData[idx]['Type'] = type;
                        if (category) newData[idx]['Product Category'] = category;

                        // Always update price if we found one and needed one
                        if (price && needsPrice) {
                             newData[idx]['Variant Price'] = price;
                        }

                        success = true;
                        setBulkProgress(prev => ({ ...prev, successes: prev.successes + 1 }));
                    } else { throw new Error("Empty response"); }

                } catch (err: any) {
                    const errorMsg = String(err);
                    if (errorMsg.includes('429')) {
                        await new Promise(r => setTimeout(r, 5000));
                        retryCount++;
                    } else {
                        break; 
                    }
                }
            }

            if (!success) setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));

            if (i > 0 && i % 5 === 0) onDataUpdate([...newData]);
            await new Promise(r => setTimeout(r, 1000));
        }

        onDataUpdate(newData);
        setProcessingStatus('Completed!');
        await new Promise(r => setTimeout(r, 1000));

    } catch (e: any) {
        alert(`Bulk Error: ${e.message}`);
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const handleSaveSingle = () => {
      if (!enhancedDescription) return;
      const newData = [...data];
      newData[selectedRowIndex]['Body (HTML)'] = enhancedDescription;
      onDataUpdate(newData);
      setEnhancedDescription('');
      alert("Row updated!");
  };

  const handleAddTag = (tag: string) => {
      if (!tag) return;
      const newData = [...data];
      const currentTags = String(newData[selectedRowIndex]['Tags'] || '');
      const tagSet = new Set(currentTags.split(',').map(t => t.trim()).filter(t => t));
      tagSet.add(tag.trim());
      newData[selectedRowIndex]['Tags'] = Array.from(tagSet).join(', ');
      onDataUpdate(newData);
  };

  const handleRemoveTag = (tag: string) => {
      const newData = [...data];
      const currentTags = String(newData[selectedRowIndex]['Tags'] || '');
      const tagSet = new Set(currentTags.split(',').map(t => t.trim()).filter(t => t));
      tagSet.delete(tag);
      newData[selectedRowIndex]['Tags'] = Array.from(tagSet).join(', ');
      onDataUpdate(newData);
  };

  const applyBulkTag = () => {
      if (!bulkTagInput) return;
      const newData = [...data];

      // Apply to all rows currently in the filtered view
      // We match filteredData IDs to actual data indices
      const filteredIndices = new Set(filteredData.map(r => newData.indexOf(r)));

      let count = 0;
      newData.forEach((row, idx) => {
          if (filteredIndices.has(idx)) {
               const currentTags = String(row['Tags'] || '');
               const tagSet = new Set(currentTags.split(',').map(t => t.trim()).filter(t => t));
               tagSet.add(bulkTagInput.trim());
               row['Tags'] = Array.from(tagSet).join(', ');
               count++;
          }
      });

      onDataUpdate(newData);
      setBulkTagInput('');
      setIsBulkTagOpen(false);
      alert(`Added tag "${bulkTagInput}" to ${count} products.`);
  };

  const apiKeyPresent = !!getApiKey();
  const missingPricesCount = data.filter(r => !r['Variant Price'] && r['Title']).length;

  // Filter for display
  const filteredData = data.filter(row => 
    Object.values(row).some(val => 
      String(val).toLowerCase().includes(searchTerm.toLowerCase())
    )
  );

  const currentTags = String(data[selectedRowIndex]?.['Tags'] || '').split(',').map(t => t.trim()).filter(t => t);

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 flex flex-col h-full relative">
      {/* PROCESSING OVERLAY */}
      {isBulkProcessing && (
        <div className="absolute inset-0 z-50 bg-white/95 flex flex-col items-center justify-center p-8 rounded-xl backdrop-blur-sm">
            <div className="w-full max-w-md bg-white p-8 rounded-2xl shadow-2xl border border-purple-100 text-center">
                <div className="mb-6 relative">
                    <div className="w-20 h-20 bg-purple-100 rounded-full mx-auto flex items-center justify-center animate-pulse">
                        <svg className="w-10 h-10 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
                    </div>
                </div>
                <h3 className="text-xl font-bold text-gray-900 mb-2 animate-pulse">{processingStatus}</h3>
                <div className="w-full bg-gray-200 rounded-full h-2.5 mb-4 overflow-hidden">
                    <div className="bg-purple-600 h-2.5 rounded-full transition-all duration-300" style={{ width: `${(bulkProgress.current / Math.max(bulkProgress.total, 1)) * 100}%` }}></div>
                </div>
                <div className="grid grid-cols-3 gap-4 text-sm mb-6">
                    <div className="bg-gray-50 p-2 rounded"><strong>{bulkProgress.current}</strong> / {bulkProgress.total}</div>
                    <div className="bg-green-50 p-2 rounded text-green-700"><strong>{bulkProgress.successes}</strong> OK</div>
                    <div className="bg-red-50 p-2 rounded text-red-700"><strong>{bulkProgress.failures}</strong> Fail</div>
                </div>
                <button onClick={() => stopProcessingRef.current = true} className="px-6 py-2 border border-gray-300 text-gray-700 font-semibold rounded-lg hover:bg-red-50 hover:text-red-600">Stop</button>
            </div>
        </div>
      )}

      <div className="p-6 border-b border-gray-200 flex flex-col md:flex-row justify-between items-start md:items-center bg-gray-50 rounded-t-xl gap-4">
         <div className="flex items-center space-x-6">
            <div>
              <h2 className="text-lg font-bold text-gray-900">Ready to Export</h2>
              <div className="flex items-center space-x-2 text-sm text-gray-500">
                  <span>{totalProducts} rows generated.</span>
                  {missingPricesCount > 0 && (
                      <span className="text-amber-600 bg-amber-50 px-2 py-0.5 rounded border border-amber-200 flex items-center">
                          <svg className="w-3 h-3 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                          {missingPricesCount} missing prices
                      </span>
                  )}
              </div>
            </div>
            <div className="flex bg-white rounded-lg border border-gray-200 p-1">
                <button onClick={() => setActiveTab('preview')} className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all ${activeTab === 'preview' ? 'bg-emerald-100 text-emerald-700' : 'text-gray-500 hover:text-gray-900'}`}>Data Preview</button>
                <button onClick={() => setActiveTab('stats')} className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all ${activeTab === 'stats' ? 'bg-emerald-100 text-emerald-700' : 'text-gray-500 hover:text-gray-900'}`}>Statistics</button>
            </div>
         </div>
         <div className="flex flex-wrap gap-2 items-center">
             <div className="relative">
                <input 
                    type="text" 
                    placeholder="Search..." 
                    className="p-2 pl-8 text-sm border border-gray-300 rounded-lg w-40"
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                />
                <svg className="w-4 h-4 absolute left-2.5 top-2.5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
             </div>

             {/* Bulk Tag Button */}
             <div className="relative">
                <button onClick={() => setIsBulkTagOpen(!isBulkTagOpen)} className="px-3 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium text-sm flex items-center">
                   <svg className="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z" /></svg>
                   Bulk Tag
                </button>
                {isBulkTagOpen && (
                    <div className="absolute top-full right-0 mt-2 w-64 bg-white rounded-lg shadow-xl border border-gray-200 p-4 z-50 animate-fade-in-down">
                        <label className="block text-xs font-semibold text-gray-500 mb-2">Add tag to {filteredData.length} visible items:</label>
                        <div className="flex gap-2">
                            <input 
                                type="text" 
                                className="flex-1 p-2 border border-gray-300 rounded text-sm" 
                                placeholder="e.g. special-order"
                                value={bulkTagInput}
                                onChange={(e) => setBulkTagInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && applyBulkTag()}
                            />
                            <button onClick={applyBulkTag} className="px-3 py-1 bg-emerald-600 text-white rounded text-sm">Add</button>
                        </div>
                    </div>
                )}
             </div>

             {missingPricesCount > 0 ? (
                 <button onClick={() => handleBulkEnhance(true)} disabled={isBulkProcessing} className="px-3 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 font-medium text-sm shadow-sm flex items-center disabled:opacity-50 animate-pulse">
                    <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg> 
                    Auto-Fill Prices
                 </button>
             ) : (
                <button onClick={() => handleBulkEnhance(false)} disabled={isBulkProcessing} className="px-3 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 font-medium text-sm shadow-sm flex items-center disabled:opacity-50">
                    <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg> 
                    Auto-Enhance All
                </button>
             )}

             <button onClick={onReset} disabled={isBulkProcessing} className="px-3 py-2 text-gray-600 hover:text-red-600 font-medium text-sm disabled:opacity-50">Start Over</button>
             <button onClick={handleDownload} disabled={isBulkProcessing} className="px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 font-bold shadow-lg shadow-emerald-200 flex items-center disabled:opacity-50">
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg> Download
             </button>
         </div>
      </div>

      <div className="flex-1 overflow-auto bg-gray-50 p-6">
        {activeTab === 'stats' ? (
           <div className="w-full h-96 bg-white p-6 rounded-xl shadow-sm">
              <h3 className="text-lg font-semibold mb-4 text-gray-800">Data Health Check</h3>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData}>
                  <XAxis dataKey="name" stroke="#9ca3af" />
                  <YAxis stroke="#9ca3af" />
                  <Tooltip cursor={{fill: '#f3f4f6'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)'}} />
