import React, { useRef, useState } from 'react';

interface FileUploadProps {
  onFileSelect: (file: File) => void;
  onManualEntry: (brand: string, sku: string) => void;
  isProcessing: boolean;
  progressMessage?: string;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect, onManualEntry, isProcessing, progressMessage }) => {
  const [activeTab, setActiveTab] = useState<'upload' | 'manual'>('upload');
  const [brand, setBrand] = useState('');
  const [sku, setSku] = useState('');

  const inputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (activeTab === 'upload' && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      onFileSelect(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      onFileSelect(e.target.files[0]);
    }
  };

  const handleSubmitManual = (e: React.FormEvent) => {
      e.preventDefault();
      if(brand && sku) {
          onManualEntry(brand, sku);
      }
  };

  return (
    <div className="flex flex-col items-center justify-center bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
      {/* TABS */}
      <div className="flex w-full border-b border-gray-200">
          <button 
             onClick={() => setActiveTab('upload')}
             className={`flex-1 py-4 text-sm font-semibold text-center transition-colors ${activeTab === 'upload' ? 'bg-emerald-50 text-emerald-700 border-b-2 border-emerald-500' : 'text-gray-500 hover:text-gray-700'}`}
          >
             Upload Spreadsheet
          </button>
          <button 
             onClick={() => setActiveTab('manual')}
             className={`flex-1 py-4 text-sm font-semibold text-center transition-colors ${activeTab === 'manual' ? 'bg-purple-50 text-purple-700 border-b-2 border-purple-500' : 'text-gray-500 hover:text-gray-700'}`}
          >
             AI Quick Generator (Multi-SKU)
          </button>
      </div>

      <div className="p-12 w-full max-w-2xl min-h-[400px] flex items-center justify-center">
          {activeTab === 'upload' ? (
              <div 
                className={`w-full h-full border-2 border-dashed rounded-xl flex flex-col items-center justify-center text-center transition-colors cursor-pointer p-8 ${
                  isProcessing ? 'bg-gray-50 border-gray-300 cursor-wait' : 'border-emerald-300 hover:bg-emerald-50 hover:border-emerald-500'
                }`}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                onClick={() => !isProcessing && inputRef.current?.click()}
              >
                <input 
                  type="file" 
                  ref={inputRef} 
                  className="hidden" 
                  accept=".xlsx,.xls,.csv" 
                  onChange={handleChange}
                  disabled={isProcessing}
                />

                {isProcessing ? (
                  <div className="flex flex-col items-center animate-pulse">
                    <div className="w-12 h-12 mb-4 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                    <p className="text-lg font-semibold text-gray-700">Analyzing Sheets...</p>
                    <p className="text-sm text-gray-500 mt-2">Merging cross-referenced data</p>
                  </div>
                ) : (
                  <>
                    <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-4">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m3.75 9v6m3-3H9m1.5-12H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
                      </svg>
                    </div>
                    <h3 className="text-xl font-bold text-gray-900 mb-2">Upload Excel or CSV</h3>
                    <p className="text-gray-500 mb-6">Drag and drop your vendor price list here.</p>
                    <button className="px-6 py-2.5 bg-emerald-600 text-white font-medium rounded-lg shadow hover:bg-emerald-700 transition-colors">
                      Select File
                    </button>
                    <p className="mt-4 text-xs text-gray-400">Supports .xlsx, .xls</p>
                  </>
                )}
              </div>
          ) : (
              <form onSubmit={handleSubmitManual} className="w-full max-w-md space-y-6">
                   <div className="text-center mb-8">
                      <div className="w-16 h-16 bg-purple-100 text-purple-600 rounded-full flex items-center justify-center mb-4 mx-auto">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
                      </div>
                      <h3 className="text-xl font-bold text-gray-900">AI Quick Generator</h3>
                      <p className="text-gray-500 text-sm">Enter Brand and SKUs to research multiple items at once.</p>
                   </div>

                   {isProcessing ? (
                        <div className="flex flex-col items-center animate-pulse py-8">
                            <div className="w-12 h-12 mb-4 border-4 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
                            <p className="text-lg font-semibold text-gray-700">AI is working...</p>
                            <p className="text-sm text-gray-500 mt-2 text-center max-w-xs">{progressMessage || "Checking vendor sites for specs & descriptions"}</p>
                        </div>
                   ) : (
                       <>
                           <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Brand / Vendor</label>
                                <input 
                                    type="text" 
                                    required
                                    className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500"
                                    placeholder="e.g. Milwaukee, DeWalt, Nike"
                                    value={brand}
                                    onChange={(e) => setBrand(e.target.value)}
                                />
                           </div>
                           <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">SKUs / Model Numbers <span className="text-xs text-gray-400 font-normal">(One per line or comma separated)</span></label>
                                <textarea 
                                    required
                                    rows={5}
                                    className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 font-mono text-sm"
                                    placeholder="2801-20&#10;2902-20&#10;48-22-8424"
                                    value={sku}
                                    onChange={(e) => setSku(e.target.value)}
                                />
                           </div>
                           <button 
                                type="submit" 
                                disabled={!brand || !sku}
                                className="w-full py-3 bg-purple-600 text-white font-bold rounded-lg hover:bg-purple-700 transition-colors shadow-lg shadow-purple-200 disabled:opacity-50 disabled:shadow-none"
                           >
                                Generate Product Data
                           </button>
                       </>
                   )}
              </form>
          )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { FileUpload } from './components/FileUpload';
import { MappingStep } from './components/MappingStep';
import { PreviewStep } from './components/PreviewStep';
import { parseExcel, generateShopifyData, createProductFromSku } from './services/excelService';
import { AppState, Mapping, ProductRow } from './types';

const App: React.FC = () => {
  const [step, setStep] = useState<AppState>(AppState.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progressMessage, setProgressMessage] = useState('');
  const [sourceHeaders, setSourceHeaders] = useState<string[]>([]);
  const [sourceData, setSourceData] = useState<ProductRow[]>([]);
  const [processedData, setProcessedData] = useState<ProductRow[]>([]);
  const [logs, setLogs] = useState<string[]>([]);

  const getApiKey = (): string | undefined => {
      try {
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              return process.env.API_KEY;
          }
      } catch (e) { console.error(e); }
      return undefined;
  };

  const handleFileSelect = async (file: File) => {
    setIsProcessing(true);
    setProgressMessage('Analyzing file...');
    // Slight delay to allow UI to update to "Processing" state before blocking thread
    setTimeout(async () => {
        try {
            const { headers, data, logs: processingLogs } = await parseExcel(file);
            setSourceHeaders(headers);
            setSourceData(data);
            setLogs(processingLogs);
            setStep(AppState.MAPPING);
        } catch (error) {
            console.error(error);
            alert("Error parsing file. Please check the format.");
        } finally {
            setIsProcessing(false);
            setProgressMessage('');
        }
    }, 100);
  };

  const handleManualEntry = async (brand: string, skuInput: string) => {
      const apiKey = getApiKey();
      if (!apiKey) {
          alert("API Key is missing. Cannot use AI Quick Add.");
          return;
      }

      setIsProcessing(true);
      setProgressMessage('Initializing AI...');

      const skus = skuInput.split(/[\n,]+/).map(s => s.trim()).filter(s => s);

      if (skus.length === 0) {
          alert("Please enter at least one SKU.");
          setIsProcessing(false);
          return;
      }

      const allData: ProductRow[] = [];

      try {
          for (let i = 0; i < skus.length; i++) {
              const currentSku = skus[i];
              setProgressMessage(`Researching item ${i + 1} of ${skus.length}: ${brand} ${currentSku}...`);

              // Rate limit protection: pause slightly between requests
              if (i > 0) await new Promise(r => setTimeout(r, 1000));

              try {
                  const rows = await createProductFromSku(brand, currentSku, apiKey);
                  allData.push(...rows);
              } catch (err: any) {
                  console.error(`Failed to generate ${currentSku}:`, err);
                  // Retry logic for rate limits (429)
                  if (String(err).includes('429')) {
                      await new Promise(r => setTimeout(r, 5000));
                      try {
                          const rows = await createProductFromSku(brand, currentSku, apiKey);
                          allData.push(...rows);
                      } catch (retryErr) {
                          console.error(`Retry failed for ${currentSku}`);
                      }
                  }
              }
          }

          if (allData.length === 0) {
              throw new Error("Could not generate data for any of the provided SKUs. Please check the Brand/SKUs and try again.");
          }

          setProcessedData(allData);
          setStep(AppState.PREVIEW);
      } catch (error: any) {
          console.error(error);
          alert(error.message || "Failed to generate products.");
      } finally {
          setIsProcessing(false);
          setProgressMessage('');
      }
  };

  const handleMappingConfirm = (mapping: Mapping) => {
    // Generate Final Data
    const result = generateShopifyData(sourceData, mapping);
    setProcessedData(result);
    setStep(AppState.PREVIEW);
  };

  const handleReset = () => {
      setStep(AppState.UPLOAD);
      setSourceData([]);
      setProcessedData([]);
      setLogs([]);
  };

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col text-gray-900 font-sans">
      <header className="bg-emerald-800 text-white shadow-md z-10">
        <div className="max-w-7xl mx-auto px-4 py-4 flex items-center justify-between">
            <div className="flex items-center space-x-3">
                <div className="bg-white/10 p-2 rounded-lg">
                    <svg className="w-6 h-6 text-emerald-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                </div>
                <h1 className="text-xl font-bold tracking-tight">Shopify Transformer</h1>
            </div>
            <div className="text-xs font-medium text-emerald-200 bg-emerald-900/50 px-3 py-1 rounded-full border border-emerald-700">
               v2.4 • Multi-SKU AI
            </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-4 lg:p-8">
        <div className="w-full h-[calc(100vh-140px)]">
            {step === AppState.UPLOAD && (
                <div className="h-full flex flex-col items-center justify-center animate-fade-in-up">
                    <div className="text-center mb-8 max-w-lg">
                        <h2 className="text-3xl font-extrabold text-gray-900 mb-4">Turn Supplier Data into Shopify Gold</h2>
                        <p className="text-gray-600 text-lg">
                            Upload a spreadsheet OR use AI to generate products from just a Brand & SKU.
                        </p>
                    </div>
                    <div className="w-full max-w-2xl">
                        <FileUpload 
                            onFileSelect={handleFileSelect} 
                            onManualEntry={handleManualEntry}
                            isProcessing={isProcessing} 
                            progressMessage={progressMessage}
                        />
                    </div>
                    <div className="mt-12 grid grid-cols-1 md:grid-cols-3 gap-6 text-center max-w-4xl">
                        <div className="p-4 bg-white rounded-lg shadow-sm border border-gray-100">
                            <div className="font-bold text-gray-900 mb-1">Smart Merge</div>
                            <div className="text-xs text-gray-500">Auto-links disparate sheets via SKU/ID</div>
                        </div>
                        <div className="p-4 bg-white rounded-lg shadow-sm border border-gray-100">
                            <div className="font-bold text-gray-900 mb-1">HTML Builder</div>
                            <div className="text-xs text-gray-500">Converts features & specs to clean HTML</div>
                        </div>
                         <div className="p-4 bg-white rounded-lg shadow-sm border border-gray-100">
                            <div className="font-bold text-gray-900 mb-1">AI Research</div>
                            <div className="text-xs text-gray-500">Finds specs & images from the web</div>
                        </div>
                    </div>
                </div>
            )}

            {step === AppState.MAPPING && (
                <MappingStep 
                    sourceHeaders={sourceHeaders} 
                    sourceData={sourceData}
                    onConfirm={handleMappingConfirm}
                    logs={logs}
                    onBack={handleReset}
                />
            )}

            {step === AppState.PREVIEW && (
                <PreviewStep 
                    data={processedData} 
                    onDataUpdate={setProcessedData}
                    onReset={handleReset} 
                />
            )}
        </div>
      </main>
    </div>
  );
};

