import React, { useState, useEffect } from 'react';
import { Mapping, SHOPIFY_FIELDS, ProductRow } from '../types';
import { SUGGESTED_MAPPINGS } from '../constants';

interface MappingStepProps {
  sourceHeaders: string[];
  sourceData: ProductRow[];
  onConfirm: (mapping: Mapping) => void;
  logs: string[];
  onBack: () => void;
}

export const MappingStep: React.FC<MappingStepProps> = ({ sourceHeaders, sourceData, onConfirm, logs, onBack }) => {
  const [mapping, setMapping] = useState<Mapping>({});

  // Smart Auto-map on mount
  useEffect(() => {
    const newMapping: Mapping = {};

    // Explicit exclusions to prevent bad matches (e.g., 'Brand Name' mapping to 'Title')
    const EXCLUSIONS: Record<string, string[]> = {
        'Title': ['brand name', 'vendor name', 'file name', 'image name', 'campaign name', 'project name', 'sheet name'],
        // Prevent 'MFG Part Number' mapping to Vendor - ADDED 'mfg part' explicitly
        'Vendor': ['part', 'sku', 'id', 'number', '#', 'code', 'qty', 'quantity', 'contact', 'mfg part', 'model'], 
        // Prevent 'UPC' mapping to SKU
        'Variant SKU': ['manufacturer', 'brand', 'vendor', 'upc', 'ean', 'gtin', 'barcode', 'price', 'cost'],
        'Image Src': ['brand logo', 'vendor logo']
    };

    const findBestMatch = (field: string, headers: string[]): string | undefined => {
        const suggestions = SUGGESTED_MAPPINGS[field] || [field.toLowerCase()];
        const exclusions = EXCLUSIONS[field] || [];

        let bestMatch: string | undefined = undefined;
        let bestScore = 0; // 3 = Exact, 2 = StartsWith, 1 = Includes

        headers.forEach(header => {
            const hLower = header.toLowerCase().trim();

            // Critical: Check exclusions
            if (exclusions.some(ex => hLower.includes(ex))) return;

            // Check against all suggestions
            for (const suggestion of suggestions) {
                const sLower = suggestion.toLowerCase();

                // Score 3: Exact Match
                if (hLower === sLower) {
                    if (bestScore < 3) { bestMatch = header; bestScore = 3; }
                }
                // Score 2: Starts With (high confidence)
                else if (hLower.startsWith(sLower)) {
                    if (bestScore < 2) { bestMatch = header; bestScore = 2; }
                }
                // Score 1: Contains (fallback)
                else if (hLower.includes(sLower)) {
                    // Penalize very short matches in long headers (e.g. "id" in "width")
                    if (sLower.length < 3 && hLower.length > 10) continue; 
                    if (bestScore < 1) { bestMatch = header; bestScore = 1; }
                }
            }
        });
        return bestMatch;
    };

    SHOPIFY_FIELDS.forEach(field => {
      // Don't override if user has manually set (though on mount this is empty)
      const match = findBestMatch(field, sourceHeaders);
      if (match) {
        newMapping[field] = match;
      }
    });

    setMapping(newMapping);
  }, [sourceHeaders]);

  const handleSelectChange = (field: string, header: string) => {
    setMapping(prev => ({
      ...prev,
      [field]: header
    }));
  };

  const getSampleValue = (header: string) => {
      if (!header) return null;
      // Try to find first non-empty value
      for(let i=0; i<Math.min(5, sourceData.length); i++) {
          const val = sourceData[i][header];
          if(val !== undefined && val !== null && String(val).trim() !== '') {
              return String(val).substring(0, 35) + (String(val).length > 35 ? '...' : '');
          }
      }
      return <span className="text-slate-400 italic">Empty</span>;
  };

  return (
    <div className="bg-white rounded-2xl shadow-xl shadow-slate-200/50 border border-white flex flex-col h-full overflow-hidden">
      {/* HEADER ACTION BAR */}
      <div className="px-6 py-5 border-b border-slate-100 flex justify-between items-center bg-white sticky top-0 z-10">
        <div>
           <h2 className="text-lg font-bold text-slate-900">Map Columns</h2>
           <p className="text-sm text-slate-500">Match your Excel headers to standard Shopify fields.</p>
        </div>
        <div className="flex space-x-3">
            <button onClick={onBack} className="px-5 py-2.5 text-slate-600 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 font-medium transition-colors">
                Back
            </button>
            <button 
                onClick={() => onConfirm(mapping)}
                className="px-5 py-2.5 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 font-bold shadow-lg shadow-emerald-200 transition-all flex items-center"
            >
                Generate Data
                <svg className="w-4 h-4 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-hidden flex">
          {/* Main Mapping Area */}
          <div className="flex-1 overflow-y-auto p-6 lg:p-8 bg-slate-50/50">
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {SHOPIFY_FIELDS.map(field => {
                    const mappedHeader = mapping[field];
                    return (
                        <div key={field} className="flex flex-col bg-white p-5 rounded-xl border border-slate-200 hover:border-emerald-300 hover:shadow-md transition-all duration-200 group">
                            <div className="flex items-center justify-between mb-3">
                                <label className="text-xs font-bold uppercase tracking-wider text-slate-500 group-hover:text-emerald-600 transition-colors">
                                    {field}
                                </label>
                                {mappedHeader ? (
                                    <div className="flex items-center text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-100">
                                        <svg className="w-3 h-3 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                                        <span className="text-[10px] font-bold uppercase">Mapped</span>
                                    </div>
                                ) : (
                                    <div className="w-2 h-2 rounded-full bg-slate-200"></div>
                                )}
                            </div>

                            <div className="relative">
                                <select 
                                    className={`w-full p-3 text-sm border rounded-lg appearance-none focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-colors ${mappedHeader ? 'bg-white border-emerald-200 text-slate-900 font-medium' : 'bg-slate-50 border-slate-200 text-slate-400'}`}
                                    value={mappedHeader || ''}
                                    onChange={(e) => handleSelectChange(field, e.target.value)}
                                >
                                    <option value="">Select Column...</option>
                                    {sourceHeaders.map(h => (
                                        <option key={h} value={h}>{h}</option>
                                    ))}
                                </select>
                                <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none text-slate-400">
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                                </div>
                            </div>

                            <div className="mt-3 min-h-[20px] text-xs">
                                {mappedHeader ? (
                                    <div className="flex items-start text-slate-500">
                                        <span className="font-semibold text-slate-400 mr-2 uppercase text-[10px] mt-0.5">Example:</span>
                                        <span className="bg-slate-100 px-2 py-0.5 rounded text-slate-700 font-mono truncate w-full block border border-slate-200">
                                            {getSampleValue(mappedHeader)}
                                        </span>
                                    </div>
                                ) : (
                                    <p className="text-slate-300 italic pl-1">Not mapped</p>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
          </div>

          {/* Logs Sidebar */}
          <div className="w-80 bg-slate-900 text-slate-400 p-0 overflow-hidden flex flex-col border-l border-slate-800 hidden lg:flex">
            <div className="p-4 bg-slate-900 border-b border-slate-800">
                <h3 className="text-white font-bold text-xs uppercase tracking-wider flex items-center">
                    <svg className="w-4 h-4 mr-2 text-emerald-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                    Processing Logs
                </h3>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-3 font-mono text-[11px] leading-relaxed">
                {logs.map((log, i) => (
                    <div key={i} className="break-words border-l-2 border-emerald-500/30 pl-3 py-1 hover:bg-white/5 transition-colors rounded-r">
                        <span className="text-emerald-500 mr-2 opacity-50">[{i+1}]</span>
                        {log}
                    </div>
                ))}
            </div>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { ProductRow } from '../types';
import { downloadCSV } from '../services/excelService';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { GoogleGenAI } from "@google/genai";

interface PreviewStepProps {
  data: ProductRow[];
  onDataUpdate: (newData: ProductRow[]) => void;
  onReset: () => void;
}

export const PreviewStep: React.FC<PreviewStepProps> = ({ data, onDataUpdate, onReset }) => {
  const [activeTab, setActiveTab] = useState<'preview' | 'stats'>('preview');
  const [searchTerm, setSearchTerm] = useState('');
  const [enhancedDescription, setEnhancedDescription] = useState<string>('');
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [selectedRowIndex, setSelectedRowIndex] = useState(0);
  const [sources, setSources] = useState<{title: string, uri: string}[]>([]);
  const [bulkTagInput, setBulkTagInput] = useState('');
  const [isBulkTagOpen, setIsBulkTagOpen] = useState(false);

  // Bulk Processing State
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [bulkProgress, setBulkProgress] = useState({ current: 0, total: 0, successes: 0, failures: 0 });
  const [processingStatus, setProcessingStatus] = useState('');
  const stopProcessingRef = useRef(false);

  // Stats Calculation
  const totalProducts = data.length;
  const withImages = data.filter(r => r['Image Src']).length;
  const withSKU = data.filter(r => r['Variant SKU']).length;
  const withPrice = data.filter(r => r['Variant Price']).length;

  const chartData = [
    { name: 'Total', value: totalProducts },
    { name: 'Images', value: withImages },
    { name: 'SKUs', value: withSKU },
    { name: 'Prices', value: withPrice },
  ];

  const handleDownload = () => {
    downloadCSV(data);
  };

  const getApiKey = (): string | undefined => {
      try {
          // @ts-ignore
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              // @ts-ignore
              return process.env.API_KEY;
          }
      } catch (e) {
          console.error("Error accessing process.env:", e);
      }
      return undefined;
  };

  const constructPrompt = (vendor: string, title: string, currentDesc: string, tags: string, category: string, needsPrice: boolean) => {
    return `You are a professional e-commerce content strategist. Research the product '${vendor} ${title}' using Google Search.

    Context:
    - Existing Tags: ${tags}
    - Category: ${category}

    Task: Write a high-converting, SEO-optimized Shopify product description (HTML format).
    ${needsPrice ? `
    IMPORTANT: The current price is MISSING. 
    1. Search for the price in Canadian Dollars (CAD).
    2. PRIORITY 1: Search specifically on Atlas Tools & Machinery (atlas-machinery.com). If found here, USE THIS PRICE.
    3. PRIORITY 2: If NOT found at Atlas, search BC Fasteners & Tools (bcfasteners.com).
    4. PRIORITY 3: If neither have it, check Home Depot Canada or KMS Tools.
    5. Return just the number (e.g. 149.99).
    ` : ''}

    Structure Required:
    1. <div class="description-hero">
       Write ONE polished, engaging marketing paragraph (approx 50-75 words). 
       Focus on the "Why" and "Who it's for". 
       </div>

    2. <div class="features-section">
       <h3>Features</h3>
       <ul>
       [Create 5-8 distinct bullet points based on your research.]
       </ul>
       </div>

    3. <div class="specs-section">
       <h3>Specifications</h3>
       [Create a clean HTML table with key specs like dimensions, material, power, etc. if found.]
       </div>

    4. <div class="extras-section">
       <p><strong>Warranty:</strong> [Find specific warranty terms. If unknown, say "Standard Manufacturer Warranty"]</p>
       <p><strong>Includes:</strong> [List box contents. If unknown, omit this line.]</p>
       </div>

    5. METADATA SECTION (At the very end, separated by |||):
       TYPE: [Specific Product Type]
       CATEGORY: [Google Product Category Taxonomy]
       ${needsPrice ? 'PRICE: [The CAD price you found, number only]' : ''}

    Output Format:
    Return ONLY the HTML content, followed by "|||" and the Metadata.
    Do NOT use markdown code blocks. Output raw text.
    `;
  };

  const processAIResponse = (text: string): { html: string, type: string, category: string, price: string } => {
    const result = { html: '', type: '', category: '', price: '' };

    // Clean potential markdown
    let cleanText = text.replace(/^```html\s*/i, '').replace(/^```\s*/, '').replace(/```$/, '').trim();

    // Robust Parsing
    const parts = cleanText.split('|||');

    // Part 1: HTML
    if (parts.length > 0) {
        result.html = parts[0].trim();
    }

    // Part 2: Metadata
    if (parts.length > 1) {
        const metadata = parts[1];
        const typeMatch = metadata.match(/TYPE:\s*([^\n]+)/i);
        const catMatch = metadata.match(/CATEGORY:\s*([^\n]+)/i);
        const priceMatch = metadata.match(/PRICE:\s*([0-9.]+)/i);

        if (typeMatch) result.type = typeMatch[1].trim();
        if (catMatch) result.category = catMatch[1].trim();
        if (priceMatch) result.price = priceMatch[1].trim();
    }

    return result;
  };

  const handleEnhanceSingle = async () => {
    const apiKey = getApiKey();
    if (!apiKey) { alert("No API Key configured. Please check your .env file."); return; }

    setIsEnhancing(true);
    setSources([]);
    setEnhancedDescription('');

    try {
      const row = data[selectedRowIndex];
      const needsPrice = !row['Variant Price'];

      const ai = new GoogleGenAI({ apiKey });
      const prompt = constructPrompt(
          String(row['Vendor'] || ''), 
          String(row['Title'] || ''), 
          String(row['Body (HTML)'] || '').replace(/<[^>]*>?/gm, ''), 
          String(row['Tags'] || ''),
          String(row['Product Category'] || ''),
          needsPrice
      );

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { tools: [{googleSearch: {}}] }
      });

      if (!response.text) throw new Error("No text returned from AI");

      const { html, price } = processAIResponse(response.text);
      setEnhancedDescription(html);

      // If we found a price for a single item, verify with user before saving? 
      // Or just save it when they click "Save". 
      // We will store it in a temporary state or alert the user.
      if (price && needsPrice) {
          alert(`Found Price: $${price} CAD. Will be saved when you click Save.`);
          // Store it temporarily in row? No, let's just handle it in handleSaveSingle if needed.
          // For now, simpler to just auto-update the row in background or let user know.
          const newData = [...data];
          newData[selectedRowIndex]['Variant Price'] = price;
          onDataUpdate(newData);
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        setSources(chunks.map(c => c.web).filter(w => w).map(w => ({ title: w!.title || 'Source', uri: w!.uri! })));
      }

    } catch (e: any) {
      console.error(e);
      alert(`Failed to enhance: ${e.message}`);
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleBulkEnhance = async (onlyMissingPrices: boolean = false) => {
    const apiKey = getApiKey();
    if (!apiKey) { 
        alert("System Error: API_KEY is missing. Cannot perform AI enhancement."); 
        return; 
    }

    // Select rows: Either ALL parent rows, OR only those missing prices
    let targetIndices = data.map((r, i) => r['Title'] ? i : -1).filter(i => i !== -1);

    if (onlyMissingPrices) {
        targetIndices = targetIndices.filter(i => !data[i]['Variant Price']);
        if (targetIndices.length === 0) {
            alert("All items already have prices!");
            return;
        }
    }

    // 2. Start State
    setIsBulkProcessing(true);
    setProcessingStatus(onlyMissingPrices ? 'Finding missing prices...' : 'Starting AI Research Agent...');
    stopProcessingRef.current = false;
    setBulkProgress({ current: 0, total: targetIndices.length, successes: 0, failures: 0 });

    const newData = [...data];
    const ai = new GoogleGenAI({ apiKey });

    try {
        for (let i = 0; i < targetIndices.length; i++) {
            if (stopProcessingRef.current) break;

            const idx = targetIndices[i];
            const row = newData[idx];
            const titleShort = String(row['Title'] || 'Item').substring(0, 40);
            const needsPrice = !row['Variant Price'];

            setProcessingStatus(`Researching (${i + 1}/${targetIndices.length}): ${titleShort}...`);
            setBulkProgress(prev => ({ ...prev, current: i + 1 }));

            const prompt = constructPrompt(
                String(row['Vendor'] || ''), 
                String(row['Title'] || ''), 
                String(row['Body (HTML)'] || '').replace(/<[^>]*>?/gm, ''), 
                String(row['Tags'] || ''),
                String(row['Product Category'] || ''),
                needsPrice
            );

            let retryCount = 0;
            let success = false;

            while (!success && retryCount < 2) {
                try {
                    const response = await ai.models.generateContent({
                        model: 'gemini-3-flash-preview',
                        contents: prompt,
                        config: { tools: [{googleSearch: {}}] }
                    });

                    if (response.text) {
                        const { html, type, category, price } = processAIResponse(response.text);
                        // Only update HTML if we aren't just looking for prices, OR if the current HTML is very short
                        if (!onlyMissingPrices || (String(row['Body (HTML)']).length < 50)) {
                             if (html && html.length > 50) newData[idx]['Body (HTML)'] = html;
                        }

                        if (type) newData[idx]['Type'] = type;
                        if (category) newData[idx]['Product Category'] = category;

                        // Always update price if we found one and needed one
                        if (price && needsPrice) {
                             newData[idx]['Variant Price'] = price;
                        }

                        success = true;
                        setBulkProgress(prev => ({ ...prev, successes: prev.successes + 1 }));
                    } else { throw new Error("Empty response"); }

                } catch (err: any) {
                    const errorMsg = String(err);
                    if (errorMsg.includes('429')) {
                        await new Promise(r => setTimeout(r, 5000));
                        retryCount++;
                    } else {
                        break; 
                    }
                }
            }

            if (!success) setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));

            if (i > 0 && i % 5 === 0) onDataUpdate([...newData]);
            await new Promise(r => setTimeout(r, 1000));
        }

        onDataUpdate(newData);
        setProcessingStatus('Completed!');
        await new Promise(r => setTimeout(r, 1000));

    } catch (e: any) {
        alert(`Bulk Error: ${e.message}`);
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const handleSaveSingle = () => {
      if (!enhancedDescription) return;
      const newData = [...data];
      newData[selectedRowIndex]['Body (HTML)'] = enhancedDescription;
      onDataUpdate(newData);
      setEnhancedDescription('');
      alert("Row updated!");
  };

  const handleAddTag = (tag: string) => {
      if (!tag) return;
      const newData = [...data];
      const currentTags = String(newData[selectedRowIndex]['Tags'] || '');
      const tagSet = new Set(currentTags.split(',').map(t => t.trim()).filter(t => t));
      tagSet.add(tag.trim());
      newData[selectedRowIndex]['Tags'] = Array.from(tagSet).join(', ');
      onDataUpdate(newData);
  };

  const handleRemoveTag = (tag: string) => {
      const newData = [...data];
      const currentTags = String(newData[selectedRowIndex]['Tags'] || '');
      const tagSet = new Set(currentTags.split(',').map(t => t.trim()).filter(t => t));
      tagSet.delete(tag);
      newData[selectedRowIndex]['Tags'] = Array.from(tagSet).join(', ');
      onDataUpdate(newData);
  };

  const applyBulkTag = () => {
      if (!bulkTagInput) return;
      const newData = [...data];

      // Apply to all rows currently in the filtered view
      // We match filteredData IDs to actual data indices
      const filteredIndices = new Set(filteredData.map(r => newData.indexOf(r)));

      let count = 0;
      newData.forEach((row, idx) => {
          if (filteredIndices.has(idx)) {
               const currentTags = String(row['Tags'] || '');
               const tagSet = new Set(currentTags.split(',').map(t => t.trim()).filter(t => t));
               tagSet.add(bulkTagInput.trim());
               row['Tags'] = Array.from(tagSet).join(', ');
               count++;
          }
      });

      onDataUpdate(newData);
      setBulkTagInput('');
      setIsBulkTagOpen(false);
      alert(`Added tag "${bulkTagInput}" to ${count} products.`);
  };

  const apiKeyPresent = !!getApiKey();
  const missingPricesCount = data.filter(r => !r['Variant Price'] && r['Title']).length;

  // Filter for display
  const filteredData = data.filter(row => 
    Object.values(row).some(val => 
      String(val).toLowerCase().includes(searchTerm.toLowerCase())
    )
  );

  const currentTags = String(data[selectedRowIndex]?.['Tags'] || '').split(',').map(t => t.trim()).filter(t => t);

  return (
    <div className="bg-white rounded-2xl shadow-xl shadow-slate-200/50 border border-white flex flex-col h-full overflow-hidden relative">
      {/* PROCESSING OVERLAY */}
      {isBulkProcessing && (
        <div className="absolute inset-0 z-50 bg-slate-900/10 flex flex-col items-center justify-center p-8 rounded-2xl backdrop-blur-sm">
            <div className="w-full max-w-md bg-white p-8 rounded-2xl shadow-2xl border border-white/50 text-center transform transition-all scale-100">
                <div className="mb-6 relative">
                    <div className="w-20 h-20 bg-purple-100 rounded-full mx-auto flex items-center justify-center animate-pulse">
                        <svg className="w-10 h-10 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
                    </div>
                </div>
                <h3 className="text-xl font-bold text-slate-900 mb-2">{processingStatus}</h3>
                <div className="w-full bg-slate-100 rounded-full h-2.5 mb-4 overflow-hidden">
                    <div className="bg-gradient-to-r from-purple-500 to-indigo-600 h-2.5 rounded-full transition-all duration-300" style={{ width: `${(bulkProgress.current / Math.max(bulkProgress.total, 1)) * 100}%` }}></div>
                </div>
                <div className="grid grid-cols-3 gap-4 text-sm mb-6">
                    <div className="bg-slate-50 p-2 rounded font-medium text-slate-600"><strong>{bulkProgress.current}</strong> / {bulkProgress.total}</div>
                    <div className="bg-emerald-50 p-2 rounded text-emerald-700 font-bold"><strong>{bulkProgress.successes}</strong> OK</div>
                    <div className="bg-rose-50 p-2 rounded text-rose-700 font-bold"><strong>{bulkProgress.failures}</strong> Fail</div>
                </div>
                <button onClick={() => stopProcessingRef.current = true} className="px-6 py-2 border border-slate-300 text-slate-700 font-semibold rounded-lg hover:bg-rose-50 hover:text-rose-600 hover:border-rose-200 transition-colors">Stop Processing</button>
            </div>
        </div>
      )}

      {/* HEADER TOOLBAR */}
      <div className="p-4 border-b border-slate-100 flex flex-col xl:flex-row justify-between items-start xl:items-center bg-white rounded-t-2xl gap-4 sticky top-0 z-20 shadow-sm">
         <div className="flex items-center space-x-6 flex-1">
            <div>
              <h2 className="text-lg font-bold text-slate-900">Workspace</h2>
              <div className="flex items-center space-x-2 text-xs text-slate-500 font-medium mt-0.5">
                  <span>{totalProducts} products ready</span>
                  {missingPricesCount > 0 && (
                      <span className="text-amber-600 bg-amber-50 px-2 py-0.5 rounded border border-amber-200 flex items-center">
                          <svg className="w-3 h-3 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                          {missingPricesCount} missing prices
                      </span>
                  )}
              </div>
            </div>

            <div className="hidden md:flex bg-slate-100/50 p-1 rounded-lg border border-slate-200">
                <button onClick={() => setActiveTab('preview')} className={`px-4 py-1.5 text-xs font-semibold rounded-md transition-all ${activeTab === 'preview' ? 'bg-white text-slate-800 shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-slate-700'}`}>Table View</button>
                <button onClick={() => setActiveTab('stats')} className={`px-4 py-1.5 text-xs font-semibold rounded-md transition-all ${activeTab === 'stats' ? 'bg-white text-slate-800 shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-slate-700'}`}>Analytics</button>
            </div>
         </div>

         <div className="flex flex-wrap gap-2 items-center justify-end w-full xl:w-auto">
             <div className="relative group">
                <input 
                    type="text" 
                    placeholder="Search products..." 
                    className="p-2 pl-9 text-sm border border-slate-300 rounded-lg w-full md:w-56 focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition-all outline-none bg-slate-50 focus:bg-white"
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                />
                <svg className="w-4 h-4 absolute left-3 top-2.5 text-slate-400 group-focus-within:text-emerald-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
             </div>

             {/* Action Buttons Group */}
             <div className="flex items-center bg-slate-50 rounded-lg p-1 border border-slate-200">
                 {/* Bulk Tag Button */}
                 <div className="relative">
                    <button onClick={() => setIsBulkTagOpen(!isBulkTagOpen)} className="px-3 py-1.5 text-slate-700 hover:bg-white hover:shadow-sm rounded-md font-medium text-xs flex items-center transition-all border border-transparent hover:border-slate-200">
                       <svg className="w-3.5 h-3.5 mr-1.5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z" /></svg>
                       Tag All
                    </button>
                    {isBulkTagOpen && (
                        <div className="absolute top-full right-0 mt-2 w-72 bg-white rounded-xl shadow-xl border border-slate-100 p-4 z-50 animate-fade-in-down ring-1 ring-black/5">
                            <label className="block text-xs font-bold text-slate-500 mb-2 uppercase tracking-wide">Add tag to {filteredData.length} items</label>
                            <div className="flex gap-2">
                                <input 
                                    type="text" 
                                    className="flex-1 p-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-emerald-500 outline-none" 
                                    placeholder="e.g. Clearance"
                                    value={bulkTagInput}
                                    onChange={(e) => setBulkTagInput(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && applyBulkTag()}
                                />
                                <button onClick={applyBulkTag} className="px-4 py-2 bg-slate-900 text-white rounded-lg text-sm font-medium hover:bg-slate-800">Add</button>
                            </div>
                        </div>
                    )}
                 </div>

                 <div className="w-px h-4 bg-slate-300 mx-1"></div>

                 {missingPricesCount > 0 ? (
                     <button onClick={() => handleBulkEnhance(true)} disabled={isBulkProcessing} className="px-3 py-1.5 text-amber-700 hover:bg-white hover:shadow-sm rounded-md font-medium text-xs flex items-center transition-all border border-transparent hover:border-amber-200 disabled:opacity-50">
                        <svg className="w-3.5 h-3.5 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg> 
                        Fix Prices
                     </button>
                 ) : (
                    <button onClick={() => handleBulkEnhance(false)} disabled={isBulkProcessing} className="px-3 py-1.5 text-purple-700 hover:bg-white hover:shadow-sm rounded-md font-medium text-xs flex items-center transition-all border border-transparent hover:border-purple-200 disabled:opacity-50">
                        <svg className="w-3.5 h-3.5 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg> 
                        AI Enhance
                    </button>
                 )}
             </div>

             <button onClick={handleDownload} disabled={isBulkProcessing} className="ml-2 px-5 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 font-bold shadow-lg shadow-emerald-200 flex items-center disabled:opacity-50 transition-all active:scale-95">
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg> 
                Export CSV
             </button>
         </div>
      </div>

      <div className="flex-1 overflow-hidden flex bg-slate-50/50">
        {activeTab === 'stats' ? (
           <div className="w-full h-full p-8 overflow-y-auto">
               <div className="w-full h-96 bg-white p-8 rounded-2xl shadow-sm border border-slate-100">
                  <h3 className="text-lg font-bold mb-6 text-slate-800">Dataset Health Overview</h3>
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData}>
                      <XAxis dataKey="name" stroke="#94a3b8" tick={{fill: '#64748b', fontSize: 12}} />
                      <YAxis stroke="#94a3b8" tick={{fill: '#64748b', fontSize: 12}} />
                      <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', padding: '12px'}} />
                      <Bar dataKey="value" radius={[6, 6, 0, 0]}>
                        {chartData.map((entry, index) => <Cell key={`cell-${index}`} fill={['#10b981', '#3b82f6', '#8b5cf6', '#f59e0b'][index % 4]} />)}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
               </div>
           </div>
        ) : (
          <div className="flex-1 flex overflow-hidden">
            {/* Table Preview */}
            <div className="flex-1 flex flex-col overflow-hidden border-r border-slate-200">
               <div className="flex-1 overflow-auto bg-white">
                 <table className="min-w-full divide-y divide-slate-100">
                   <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                     <tr>
                       <th className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider whitespace-nowrap bg-slate-50 border-b border-slate-200">Image</th>
                       {Object.keys(data[0] || {}).slice(0, 8).filter(k => k !== 'Image Src' && k !== 'Image Alt Text').map(h => (
                         <th key={h} className="px-6 py-4 text-left text-xs font-bold text-slate-500 uppercase tracking-wider whitespace-nowrap bg-slate-50 border-b border-slate-200">{h}</th>
                       ))}
