import React, { useState } from 'react';
import { FileUpload } from './components/FileUpload';
import { MappingStep } from './components/MappingStep';
import { PreviewStep } from './components/PreviewStep';
import { parseExcel, generateShopifyData, createProductFromSku } from './services/excelService';
import { AppState, Mapping, ProductRow } from './types';

const App: React.FC = () => {
  const [step, setStep] = useState<AppState>(AppState.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progressMessage, setProgressMessage] = useState('');
  const [sourceHeaders, setSourceHeaders] = useState<string[]>([]);
  const [sourceData, setSourceData] = useState<ProductRow[]>([]);
  const [processedData, setProcessedData] = useState<ProductRow[]>([]);
  const [logs, setLogs] = useState<string[]>([]);

  const getApiKey = (): string | undefined => {
      try {
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              return process.env.API_KEY;
          }
      } catch (e) { console.error(e); }
      return undefined;
  };

  const handleFileSelect = async (file: File) => {
    setIsProcessing(true);
    setProgressMessage('Analyzing file...');
    setTimeout(async () => {
        try {
            const { headers, data, logs: processingLogs } = await parseExcel(file);
            setSourceHeaders(headers);
            setSourceData(data);
            setLogs(processingLogs);
            setStep(AppState.MAPPING);
        } catch (error) {
            console.error(error);
            alert("Error parsing file. Please check the format.");
        } finally {
            setIsProcessing(false);
            setProgressMessage('');
        }
    }, 100);
  };

  const handleManualEntry = async (brand: string, skuInput: string) => {
      const apiKey = getApiKey();
      if (!apiKey) {
          alert("API Key is missing. Cannot use AI Quick Add.");
          return;
      }

      setIsProcessing(true);
      setProgressMessage('Initializing AI...');

      const skus = skuInput.split(/[\n,]+/).map(s => s.trim()).filter(s => s);

      if (skus.length === 0) {
          alert("Please enter at least one SKU.");
          setIsProcessing(false);
          return;
      }

      const allData: ProductRow[] = [];

      try {
          for (let i = 0; i < skus.length; i++) {
              const currentSku = skus[i];
              setProgressMessage(`Researching item ${i + 1} of ${skus.length}: ${brand} ${currentSku}...`);

              if (i > 0) await new Promise(r => setTimeout(r, 1000));

              try {
                  const rows = await createProductFromSku(brand, currentSku, apiKey);
                  allData.push(...rows);
              } catch (err: any) {
                  console.error(`Failed to generate ${currentSku}:`, err);
                  if (String(err).includes('429')) {
                      await new Promise(r => setTimeout(r, 5000));
                      try {
                          const rows = await createProductFromSku(brand, currentSku, apiKey);
                          allData.push(...rows);
                      } catch (retryErr) {
                          console.error(`Retry failed for ${currentSku}`);
                      }
                  }
              }
          }

          if (allData.length === 0) {
              throw new Error("Could not generate data for any of the provided SKUs.");
          }

          setProcessedData(allData);
          setStep(AppState.PREVIEW);
      } catch (error: any) {
          console.error(error);
          alert(error.message || "Failed to generate products.");
      } finally {
          setIsProcessing(false);
          setProgressMessage('');
      }
  };

  const handleMappingConfirm = (mapping: Mapping) => {
    const result = generateShopifyData(sourceData, mapping);
    setProcessedData(result);
    setStep(AppState.PREVIEW);
  };

  const handleReset = () => {
      setStep(AppState.UPLOAD);
      setSourceData([]);
      setProcessedData([]);
      setLogs([]);
  };

  return (
    <div className="h-full flex flex-col bg-slate-50 text-slate-900 font-sans selection:bg-emerald-100 selection:text-emerald-900">
      {/* HEADER - GLASS STYLE */}
      <header className="bg-slate-900/95 backdrop-blur-md text-white shadow-2xl z-50 flex-none sticky top-0 border-b border-white/5">
        <div className="max-w-screen-2xl mx-auto px-6 py-4 flex items-center justify-between">
            <div className="flex items-center space-x-4">
                <div className="bg-gradient-to-br from-emerald-400 to-emerald-600 p-2.5 rounded-xl shadow-lg shadow-emerald-500/20">
                    <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                </div>
                <div>
                    <h1 className="text-lg font-extrabold tracking-tight text-white leading-tight uppercase">Shopify Transformer</h1>
                    <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest block">Intelligent Data Studio</span>
                </div>
            </div>

            <div className="flex items-center space-x-6">
                 {step !== AppState.UPLOAD && (
                     <button onClick={handleReset} className="text-xs font-bold text-slate-400 hover:text-white transition-all uppercase tracking-wide">
                        ← New Import
                     </button>
                 )}
                <div className="flex items-center space-x-2 bg-slate-800/80 px-4 py-2 rounded-full border border-slate-700 shadow-inner">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">Gemini 3 Flash • Active</span>
                </div>
            </div>
        </div>
      </header>

      {/* MAIN VIEWPORT */}
      <main className="flex-1 flex flex-col min-h-0 relative">
            {step === AppState.UPLOAD && (
                <div className="flex-1 overflow-y-auto">
                     <div className="min-h-full flex flex-col items-center justify-center py-20 px-6">
                        <div className="text-center mb-12 max-w-2xl animate-fade-in-up">
                            <h2 className="text-5xl font-black text-slate-900 mb-6 tracking-tight leading-[1.1]">
                                Modern Data <br/> 
                                <span className="text-emerald-600">Power Tools.</span>
                            </h2>
                            <p className="text-slate-500 text-xl font-medium leading-relaxed">
                                Professional-grade Shopify conversion. Research prices, generate HTML descriptions, and organize assets with AI.
                            </p>
                        </div>

                        <div className="w-full max-w-3xl animate-fade-in-up shadow-2xl rounded-3xl" style={{animationDelay: '0.1s'}}>
                            <FileUpload 
                                onFileSelect={handleFileSelect} 
                                onManualEntry={handleManualEntry}
                                isProcessing={isProcessing} 
                                progressMessage={progressMessage}
                            />
                        </div>

                        <div className="mt-20 grid grid-cols-1 md:grid-cols-3 gap-8 max-w-6xl w-full animate-fade-in-up" style={{animationDelay: '0.2s'}}>
                            <div className="group p-8 bg-white rounded-3xl shadow-sm border border-slate-100 hover:shadow-xl hover:border-emerald-100 transition-all duration-300">
                                <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
                                </div>
                                <div className="font-black text-slate-900 text-lg mb-3">Live Price Fetching</div>
                                <div className="text-sm text-slate-500 leading-relaxed font-medium">Prioritizes Atlas & BC Fasteners to ensure your Canadian pricing is accurate and competitive.</div>
                            </div>
                            <div className="group p-8 bg-white rounded-3xl shadow-sm border border-slate-100 hover:shadow-xl hover:border-emerald-100 transition-all duration-300">
                                <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                     <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" /></svg>
                                </div>
                                <div className="font-black text-slate-900 text-lg mb-3">Smart Taxonomy</div>
                                <div className="text-sm text-slate-500 leading-relaxed font-medium">Automatically maps products to standard Google/Shopify categories using deep semantic analysis.</div>
                            </div>
                             <div className="group p-8 bg-white rounded-3xl shadow-sm border border-slate-100 hover:shadow-xl hover:border-emerald-100 transition-all duration-300">
                                <div className="w-12 h-12 bg-purple-50 text-purple-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                </div>
                                <div className="font-black text-slate-900 text-lg mb-3">Asset Consolidation</div>
                                <div className="text-sm text-slate-500 leading-relaxed font-medium">Scans all columns for high-res images and organizes them into a perfect Shopify gallery.</div>
                            </div>
                        </div>
                     </div>
                </div>
            )}

            {step === AppState.MAPPING && (
                 <div className="flex-1 overflow-hidden p-6 bg-slate-50">
                    <div className="h-full max-w-screen-2xl mx-auto shadow-2xl rounded-3xl overflow-hidden border border-white">
                        <MappingStep 
                            sourceHeaders={sourceHeaders} 
                            sourceData={sourceData}
                            onConfirm={handleMappingConfirm}
                            logs={logs}
                            onBack={handleReset}
                        />
                    </div>
                </div>
            )}

            {step === AppState.PREVIEW && (
                <div className="flex-1 overflow-hidden p-6 bg-slate-50">
                    <div className="h-full max-w-screen-2xl mx-auto shadow-2xl rounded-3xl overflow-hidden border border-white">
                        <PreviewStep 
                            data={processedData} 
                            onDataUpdate={setProcessedData}
                            onReset={handleReset} 
                        />
                    </div>
                </div>
            )}
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState } from 'react';

interface FileUploadProps {
  onFileSelect: (file: File) => void;
  onManualEntry: (brand: string, sku: string) => void;
  isProcessing: boolean;
  progressMessage?: string;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect, onManualEntry, isProcessing, progressMessage }) => {
  const [activeTab, setActiveTab] = useState<'upload' | 'manual'>('upload');
  const [brand, setBrand] = useState('');
  const [sku, setSku] = useState('');

  const inputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (activeTab === 'upload' && e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      onFileSelect(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      onFileSelect(e.target.files[0]);
    }
  };

  const handleSubmitManual = (e: React.FormEvent) => {
      e.preventDefault();
      if(brand && sku) {
          onManualEntry(brand, sku);
      }
  };

  return (
    <div className="bg-white rounded-3xl border border-slate-100 flex flex-col h-auto min-h-[550px] overflow-hidden">
      {/* SEGMENTED TABS */}
      <div className="px-10 pt-10 pb-6 bg-white">
          <div className="flex p-1.5 bg-slate-100 rounded-2xl w-full">
              <button 
                 onClick={() => setActiveTab('upload')}
                 className={`flex-1 py-3 text-sm font-bold rounded-[14px] transition-all duration-300 ${
                     activeTab === 'upload' 
                     ? 'bg-white text-slate-900 shadow-lg shadow-slate-200 ring-1 ring-slate-900/5' 
                     : 'text-slate-500 hover:text-slate-800'
                 }`}
              >
                 Spreadsheet Import
              </button>
              <button 
                 onClick={() => setActiveTab('manual')}
                 className={`flex-1 py-3 text-sm font-bold rounded-[14px] transition-all duration-300 ${
                     activeTab === 'manual' 
                     ? 'bg-white text-slate-900 shadow-lg shadow-slate-200 ring-1 ring-slate-900/5' 
                     : 'text-slate-500 hover:text-slate-800'
                 }`}
              >
                 AI Research Agent
              </button>
          </div>
      </div>

      <div className="flex-1 px-10 pb-10 flex items-center justify-center bg-white relative">
          {activeTab === 'upload' ? (
              <div 
                className={`w-full h-80 border-2 border-dashed rounded-3xl flex flex-col items-center justify-center text-center transition-all duration-500 group relative overflow-hidden ${
                  isProcessing ? 'bg-slate-50 border-slate-200 cursor-wait' : 'border-slate-200 hover:border-emerald-500 hover:bg-emerald-50/20'
                }`}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                onClick={() => !isProcessing && inputRef.current?.click()}
              >
                <input 
                  type="file" 
                  ref={inputRef} 
                  className="hidden" 
                  accept=".xlsx,.xls,.csv" 
                  onChange={handleChange}
                  disabled={isProcessing}
                />

                {isProcessing ? (
                  <div className="flex flex-col items-center z-10">
                    <div className="w-16 h-16 mb-6 border-[5px] border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                    <p className="text-2xl font-black text-slate-900">Processing Data</p>
                    <p className="text-slate-500 mt-2 font-medium">Extracting products & analyzing sheets...</p>
                  </div>
                ) : (
                  <>
                    <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-3xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-500 shadow-inner">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-12 h-12">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m3.75 9v6m3-3H9m1.5-12H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
                      </svg>
                    </div>
                    <h3 className="text-2xl font-black text-slate-900 mb-2">Drag your catalog here</h3>
                    <p className="text-slate-500 mb-8 max-w-sm font-medium">Works with Excel and CSV files from any supplier.</p>
                    <span className="px-8 py-4 bg-emerald-600 text-white font-bold rounded-2xl shadow-xl shadow-emerald-200 group-hover:bg-emerald-700 transition-all hover:scale-105">
                      Choose File
                    </span>
                  </>
                )}
              </div>
          ) : (
              <form onSubmit={handleSubmitManual} className="w-full max-w-lg space-y-8">
