  'Toys & Games', 'Vehicles & Parts'
];

const escapeRegExp = (string: string) => {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const normalizeVendor = (raw: string): string => {
    if (!raw) return '';
    let v = String(raw).trim().toUpperCase();
    if (v.startsWith('MILWAUKEE')) return 'MILWAUKEE';
    return v;
};

const calculateSheetScore = (sheet: { name: string, data: ProductRow[] }): number => {
  const headers = Object.keys(sheet.data[0] || {});
  const rowCount = sheet.data.length;
  const colCount = headers.length;
  const nameLower = sheet.name.toLowerCase();

  let score = rowCount + (colCount * 5);
  const masterKeywords = ['price', 'cost', 'msrp', 'description', 'title', 'product name', 'category', 'inventory', 'stock', 'qty'];
  masterKeywords.forEach(k => {
    if (headers.some(h => h.toLowerCase().includes(k))) score += 500;
  });

  if (headers.some(h => h.toLowerCase().includes('sku') || h.toLowerCase().includes('part'))) score += 100;
  if (nameLower.includes('master') || nameLower.includes('product') || nameLower.includes('data') || nameLower.includes('item')) score += 500;
  if (nameLower.includes('asset') || nameLower.includes('image') || nameLower.includes('media')) score -= 5000;
  if (colCount < 3 || rowCount < 2) score -= 2000;

  return score;
};

export const parseExcel = async (file: File): Promise<{ headers: string[], data: ProductRow[], logs: string[] }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const logs: string[] = [];
        let sheetsData: { name: string, data: ProductRow[] }[] = [];

        workbook.SheetNames.forEach(name => {
          const lowerName = name.toLowerCase();
          if (lowerName.includes('french') || lowerName.includes('francais') || lowerName.match(/\bfr\b/)) return; 

          const sheet = workbook.Sheets[name];
          const json = XLSX.utils.sheet_to_json<ProductRow>(sheet, { defval: "" });
          if (json.length > 0) sheetsData.push({ name, data: json });
        });

        if (sheetsData.length === 0) {
          resolve({ headers: [], data: [], logs: ['No valid data found.'] });
          return;
        }

        sheetsData.sort((a, b) => calculateSheetScore(b) - calculateSheetScore(a));
        logs.push(`Master Sheet Selected: ${sheetsData[0].name}`);

        let masterData = [...sheetsData[0].data];
        const normalizeVal = (val: any) => String(val || '').toLowerCase().replace(/[^a-z0-9]/g, '');
        const invalidJoinValues = new Set(['yes', 'no', 'true', 'false', 'y', 'n', '0', '1', 'active', 'draft', '', 'manual', 'shopify', 'deny', 'continue', 'null', 'nan', 'undefined', 'n/a']);

        for (let i = 1; i < sheetsData.length; i++) {
          const sheet = sheetsData[i];
          const sheetData = sheet.data;
          const masterHeaders = Object.keys(masterData[0] || {});
          const sheetHeaders = Object.keys(sheetData[0] || {});

          let bestMasterKey = '';
          let bestSheetKey = '';
          let bestScore = 0;

          const masterColSets = new Map<string, Set<string>>();
          masterHeaders.forEach(mCol => {
              if (mCol.length > 100) return; 
              const s = new Set<string>();
              masterData.forEach(r => {
                 const v = normalizeVal(r[mCol]);
                 if (v.length > 2 && !invalidJoinValues.has(v)) s.add(v);
              });
              if (s.size > 0) masterColSets.set(mCol, s);
          });

          sheetHeaders.forEach(sCol => {
             if (sCol.length > 100) return;
             const sheetVals = new Set<string>();
             sheetData.forEach(r => {
                const v = normalizeVal(r[sCol]);
                if (v.length > 2 && !invalidJoinValues.has(v)) sheetVals.add(v);
             });
             if (sheetVals.size === 0) return;

             for (const [mCol, masterSet] of masterColSets.entries()) {
                 let intersection = 0;
                 for (const val of sheetVals) if (masterSet.has(val)) intersection++;
                 if (intersection > 0) {
                     let score = intersection;
                     if (score > bestScore) {
                         bestScore = score;
                         bestMasterKey = mCol;
                         bestSheetKey = sCol;
                     }
                 }
             }
          });

          if (bestMasterKey && bestSheetKey && bestScore > 2) {
             const lookup = new Map<string, ProductRow[]>();
             sheetData.forEach(row => {
               const val = normalizeVal(row[bestSheetKey]);
               if (val && val.length > 2) {
                 if (!lookup.has(val)) lookup.set(val, []);
                 lookup.get(val)?.push(row);
               }
             });

             masterData = masterData.map(row => {
               const val = normalizeVal(row[bestMasterKey]);
               const matches = lookup.get(val);
               if (matches && matches.length > 0) {
                 const newRow = { ...row };
                 Object.keys(matches[0]).filter(k => k !== bestSheetKey).forEach(key => {
                    let targetKey = newRow.hasOwnProperty(key) ? `${key} [${sheet.name}]` : key;
                    const uniqueValues = Array.from(new Set(matches.map(m => String(m[key] || '').trim()).filter(v => v)));
                    if (uniqueValues.length > 0) newRow[targetKey] = uniqueValues.join('|'); 
                 });
                 return newRow;
               }
               return row;
             });
          }
        }

        // Auto-extract images from all columns
        masterData = masterData.map(row => {
           const allImages: string[] = [];
           Object.entries(row).forEach(([key, val]) => {
              if (typeof val === 'string' && val.length > 5) {
                 const lowerKey = key.toLowerCase();
                 if (lowerKey.includes('logo') || lowerKey.includes('french')) return;
                 val.split(/[|,\n]+/).forEach(p => {
                    const clean = p.trim();
                    if (clean.length < 5) return;
                    if (clean.match(/\.(jpg|jpeg|png|webp|gif|bmp)/i) || clean.match(/(edgenet|widen|cloudinary|scene7|cdn|azureedge|cloudfront)/i)) {
                        if (!clean.includes('<') && !clean.includes(' ') && clean.length < 500) allImages.push(clean);
                    }
                 });
              }
           });
           const uniqueImages = Array.from(new Set(allImages));
           if (uniqueImages.length > 0) row['_Generated_Images'] = uniqueImages.join('|');
           return row;
        });

        const allHeaders = new Set<string>();
        masterData.forEach(row => Object.keys(row).forEach(k => allHeaders.add(k)));
        resolve({ headers: Array.from(allHeaders), data: masterData, logs });
      } catch (error) { reject(error); }
    };
    reader.onerror = (error) => reject(error);
    reader.readAsBinaryString(file);
  });
};

const cleanImageUrl = (url: string): string => {
  if (!url) return '';
  let clean = url.trim().replace(/['"]/g, '').replace(/ /g, '%20');

  // Handle protocol-relative URLs
  if (clean.startsWith('//')) clean = 'https:' + clean;

  // Basic validation - must look like a URL
  if (!clean.startsWith('http')) {
     if (clean.match(/\.(jpg|jpeg|png|gif|webp)|edgenet|widen|cloudinary|scene7/i) && clean.includes('/')) {
        clean = 'https://' + clean;
     } else {
        return '';
     }
  }

  // Filter known placeholders and icons
  const lower = clean.toLowerCase();
  const placeholders = ['placeholder', 'no-image', 'noimage', 'icon', 'logo', 'spacer', 'loading', 'pixel', 'missing', 'thumb', 'swatch', 'badge'];
  if (placeholders.some(p => lower.includes(p))) return '';

  // Ensure it has an image-like extension or is from a known CDN
  const isCdn = lower.match(/(edgenet|widen|cloudinary|scene7|cdn|azureedge|cloudfront|amazon|shopify|bigcommerce)/i);
  const hasExt = lower.match(/\.(jpg|jpeg|png|gif|webp|bmp|tiff)$/i);

  if (!isCdn && !hasExt) return '';

  return clean;
};

const cleanValue = (value: any, fieldName: string): string => {
  if (value === null || value === undefined) return '';
  let strVal = String(value).trim();

  if (fieldName.includes('Price') || fieldName === 'Cost' || fieldName === 'MSRP') {
    const p = strVal.replace(/[^0-9.]/g, '');
    const num = parseFloat(p);
    return isNaN(num) ? '' : num.toFixed(2);
  }

  if (fieldName === 'Vendor') return normalizeVendor(strVal);
  return strVal;
};

export const generateShopifyData = (sourceData: ProductRow[], mapping: Mapping): ProductRow[] => {
  return sourceData.flatMap((row) => {
    const newRow: ProductRow = {};
    let title = '', brand = '', sku = '';

    for (const [shopifyField, sourceHeader] of Object.entries(mapping)) {
      if (sourceHeader && row[sourceHeader] !== undefined) {
        let rawVal = String(row[sourceHeader] || '');
        if (rawVal.includes('|') && shopifyField !== 'Image Src') {
            const parts = rawVal.split('|').map(s => s.trim()).filter(s => s && s.toLowerCase() !== 'nan');
            rawVal = shopifyField === 'Tags' ? Array.from(new Set(parts)).join(', ') : parts[0];
        }
        newRow[shopifyField] = cleanValue(rawVal, shopifyField);
        if (shopifyField === 'Title') title = rawVal;
        if (shopifyField === 'Vendor') brand = newRow[shopifyField];
        if (shopifyField === 'Variant SKU') sku = newRow[shopifyField];
      } else newRow[shopifyField] = '';
    }

    // Standard Shopify Defaults
    newRow['Variant Inventory Tracker'] = 'shopify';
    newRow['Variant Inventory Policy'] = 'continue'; 
    newRow['Variant Fulfillment Service'] = 'manual';
    newRow['Option1 Name'] = 'Title';
    newRow['Option1 Value'] = 'Default Title';
    newRow['Status'] = 'draft'; 

    // Handle Title Formatting
    let cleanTitle = title;
    if (brand) cleanTitle = cleanTitle.replace(new RegExp(escapeRegExp(brand), 'gi'), '').trim();
    if (sku) cleanTitle = cleanTitle.replace(new RegExp(escapeRegExp(sku), 'gi'), '').trim();
    newRow['Title'] = [brand, sku, cleanTitle].filter(p => p).join(' ').replace(/\s+/g, ' ').trim();

    // Image logic - Gather all potential images
    const mappedImg = mapping['Image Src'] ? row[mapping['Image Src']] : '';
    const genImg = row['_Generated_Images'] || '';

    const rawImagePool = [
        ...String(mappedImg).split(/[|;\n,]+/),
        ...String(genImg).split(/[|;\n,]+/)
    ];

    const finalImages = Array.from(new Set(rawImagePool.map(cleanImageUrl).filter(u => u))).slice(0, 10);

    if (finalImages.length > 0) {
         // Shopify Import handles multiple images by repeating rows with only Handle and Image info
         const firstRow = { ...newRow, 'Image Src': finalImages[0], 'Image Position': 1, 'Image Alt Text': newRow['Title'] };
         const extraRows = finalImages.slice(1).map((img, idx) => ({
             'Handle': firstRow['Handle'],
             'Image Src': img,
             'Image Position': idx + 2,
             'Image Alt Text': firstRow['Title']
         }));
         return [firstRow, ...extraRows];
    }

    return [newRow];
  });
};

export const createProductFromSku = async (brand: string, sku: string, apiKey: string): Promise<ProductRow[]> => {
    const ai = new GoogleGenAI({ apiKey });

    // EXTREMELY AGGRESSIVE IMAGE PROMPT
    const prompt = `Research product: ${brand} ${sku}. 
    Goal: Find detailed specs, CAD price, and EXPLICITLY identify up to 10 DIRECT High-Resolution Image URLs.

    Search targets:
    1. Manufacturer's official website product page.
    2. Retail sites like Amazon, Home Depot, or specialized tools sites (atlas-machinery.com, bcfasteners.com).

    RULES:
    - You MUST find at least 3-5 images.
    - Image URLs must be DIRECT (end in .jpg, .png, .webp) or from reliable CDNs.
    - Prioritize 1000x1000px or larger.
    - IGNORE logos, tiny thumbnails, and icons.

    Return JSON ONLY:
    {
      "title": "Full product title",
      "vendor": "${brand}",
      "product_type": "Specific tool type",
      "category": "Full Google Product Category path",
      "price": "CAD price number only",
      "tags": "comma, separated, tags",
      "body_html": "Rich HTML description with features and specs table",
      "images": ["url1", "url2", "url3", "url4", "url5", "url6", "url7", "url8", "url9", "url10"]
    }`;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { tools: [{googleSearch: {}}] }
    });

    try {
        const jsonStr = response.text.match(/\{[\s\S]*\}/)?.[0] || '{}';
        const data = JSON.parse(jsonStr);

        const validImages = (data.images || []).map(cleanImageUrl).filter(u => u);
        const handle = (data.title || `${brand}-${sku}`).toLowerCase().replace(/[^a-z0-9]+/g, '-');

        const mainRow: ProductRow = {
            'Handle': handle,
            'Title': data.title || `${brand} ${sku}`,
            'Body (HTML)': data.body_html || '',
            'Vendor': normalizeVendor(data.vendor || brand),
            'Product Category': data.category || '',
            'Type': data.product_type || '',
            'Tags': data.tags || '',
            'Option1 Name': 'Title',
            'Option1 Value': 'Default Title',
            'Variant SKU': sku,
            'Variant Price': data.price || '',
            'Image Src': validImages[0] || '',
            'Image Position': 1,
            'Status': 'draft'
        };

        const extraRows = validImages.slice(1).map((img: string, i: number) => ({
            'Handle': handle,
            'Image Src': img,
            'Image Position': i + 2
        }));

        return [mainRow, ...extraRows];
    } catch (e) {
        console.error("AI Generation Error:", e);
        return [{
            'Handle': `${brand}-${sku}`.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
            'Title': `${brand} ${sku}`,
            'Vendor': normalizeVendor(brand),
            'Variant SKU': sku,
            'Status': 'draft'
        }];
    }
};

export const downloadCSV = (data: ProductRow[]) => {
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Products");
  XLSX.writeFile(wb, 'shopify_import.csv');
};

import React, { useState, useRef } from 'react';
