interface PreviewStepProps {
  data: ProductRow[];
  onDataUpdate: (newData: ProductRow[]) => void;
  onReset: () => void;
}

export const PreviewStep: React.FC<PreviewStepProps> = ({ data, onDataUpdate, onReset }) => {
  const [activeTab, setActiveTab] = useState<'preview' | 'stats'>('preview');
  const [searchTerm, setSearchTerm] = useState('');
  const [enhancedDescription, setEnhancedDescription] = useState<string>('');
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [selectedRowIndex, setSelectedRowIndex] = useState(0);
  const [bulkTagInput, setBulkTagInput] = useState('');
  const [isBulkTagOpen, setIsBulkTagOpen] = useState(false);

  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [bulkProgress, setBulkProgress] = useState({ current: 0, total: 0, successes: 0, failures: 0 });
  const [processingStatus, setProcessingStatus] = useState('');
  const stopProcessingRef = useRef(false);

  const totalProducts = Array.from(new Set(data.map(r => r['Handle']))).length;
  const withImages = data.filter(r => r['Image Src']).length;
  const withPrice = data.filter(r => r['Variant Price']).length;

  const chartData = [
    { name: 'Total Products', value: totalProducts },
    { name: 'Assets/Images', value: withImages },
    { name: 'Prices Set', value: withPrice },
  ];

  const handleDownload = () => {
    downloadCSV(data);
  };

  const getApiKey = (): string | undefined => {
      try {
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              return process.env.API_KEY;
          }
      } catch (e) { console.error(e); }
      return undefined;
  };

  const handleEnhanceSingle = async () => {
    const apiKey = getApiKey();
    if (!apiKey) return;

    setIsEnhancing(true);
    setEnhancedDescription('');

    try {
      const row = data[selectedRowIndex];
      const brand = String(row['Vendor'] || '');
      const sku = String(row['Variant SKU'] || '');

      const ai = new GoogleGenAI({ apiKey });
      const prompt = `Research product: ${brand} ${sku}. 
      Find 3-10 High-Resolution direct image URLs (MUST end in .jpg/.png) and rich HTML description. 
      Return JSON: { "title", "images": [], "body_html", "price" }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { tools: [{googleSearch: {}}] }
      });

      const jsonStr = response.text.match(/\{[\s\S]*\}/)?.[0] || '{}';
      const result = JSON.parse(jsonStr);

      if (result.body_html) setEnhancedDescription(result.body_html);

      const newData = [...data];
      const handle = row['Handle'];

      // Update price if found
      if (result.price) {
          newData.forEach(r => { if (r['Handle'] === handle) r['Variant Price'] = result.price; });
      }

      // Handle new images - remove old image rows for this handle and add new ones
      if (result.images && result.images.length > 0) {
          const baseData = newData.find(r => r['Handle'] === handle && r['Title']);
          if (baseData) {
              const cleanedImages = result.images.filter((url: string) => url.match(/\.(jpg|jpeg|png|webp)/i));
              if (cleanedImages.length > 0) {
                  // Keep only the rows for OTHER products
                  const filtered = newData.filter(r => r['Handle'] !== handle);

                  // Add the updated rows back
                  const mainRow = { ...baseData, 'Image Src': cleanedImages[0], 'Image Position': 1 };
                  const extraRows = cleanedImages.slice(1).map((img: string, i: number) => ({
                      'Handle': handle,
                      'Image Src': img,
                      'Image Position': i + 2,
                      'Image Alt Text': mainRow['Title']
                  }));

                  onDataUpdate([...filtered, mainRow, ...extraRows]);
              }
          }
      } else {
          onDataUpdate(newData);
      }

      alert("Product updated with AI research!");
    } catch (e: any) {
      console.error(e);
      alert(`Failed to enhance: ${e.message}`);
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleBulkEnhance = async (onlyMissingPrices: boolean = false) => {
    const apiKey = getApiKey();
    if (!apiKey) return;

    // Logic for handles
    const uniqueHandles = Array.from(new Set(data.map(r => r['Handle'])));
    setIsBulkProcessing(true);
    setProcessingStatus('Researching products & hunting for images...');
    stopProcessingRef.current = false;
    setBulkProgress({ current: 0, total: uniqueHandles.length, successes: 0, failures: 0 });

    const ai = new GoogleGenAI({ apiKey });
    let workingData = [...data];

    try {
        for (let i = 0; i < uniqueHandles.length; i++) {
            if (stopProcessingRef.current) break;
            const handle = uniqueHandles[i];
            const row = workingData.find(r => r['Handle'] === handle && r['Title']);
            if (!row) continue;

            setProcessingStatus(`Researching item ${i + 1}: ${row['Title']}...`);
            setBulkProgress(prev => ({ ...prev, current: i + 1 }));

            const prompt = `Research product: ${row['Vendor']} ${row['Variant SKU']}. 
            Find 5-10 High-Resolution direct image URLs and rich HTML description. 
            Return JSON: { "title", "images": [], "body_html", "price" }`;

            try {
                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: prompt,
                    config: { tools: [{googleSearch: {}}] }
                });

                const jsonStr = response.text.match(/\{[\s\S]*\}/)?.[0] || '{}';
                const result = JSON.parse(jsonStr);

                if (result.images && result.images.length > 0) {
                    const cleanedImages = result.images.filter((url: string) => url.match(/\.(jpg|jpeg|png|webp)/i));
                    if (cleanedImages.length > 0) {
                        const others = workingData.filter(r => r['Handle'] !== handle);
                        const mainRow = { ...row, 'Image Src': cleanedImages[0], 'Image Position': 1 };
                        if (result.body_html) mainRow['Body (HTML)'] = result.body_html;
                        if (result.price) mainRow['Variant Price'] = result.price;

                        const extraRows = cleanedImages.slice(1).map((img: string, idx: number) => ({
                            'Handle': handle,
                            'Image Src': img,
                            'Image Position': idx + 2,
                            'Image Alt Text': mainRow['Title']
                        }));
                        workingData = [...others, mainRow, ...extraRows];
                    }
                }
                setBulkProgress(prev => ({ ...prev, successes: prev.successes + 1 }));
            } catch (err) {
                setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
            }

            if (i % 3 === 0) onDataUpdate([...workingData]);
            await new Promise(r => setTimeout(r, 1000));
        }
        onDataUpdate(workingData);
    } catch (e: any) {
        alert(e.message);
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const handleAddTag = (tag: string) => {
      if (!tag) return;
      const newData = [...data];
      const handle = data[selectedRowIndex]['Handle'];
      newData.forEach(r => {
          if (r['Handle'] === handle) {
              const currentTags = String(r['Tags'] || '');
              const tagSet = new Set(currentTags.split(',').map(t => t.trim()).filter(t => t));
              tagSet.add(tag.trim());
              r['Tags'] = Array.from(tagSet).join(', ');
          }
      });
      onDataUpdate(newData);
  };

  const handleRemoveTag = (tag: string) => {
      const newData = [...data];
      const handle = data[selectedRowIndex]['Handle'];
      newData.forEach(r => {
          if (r['Handle'] === handle) {
              const currentTags = String(r['Tags'] || '');
              const tagSet = new Set(currentTags.split(',').map(t => t.trim()).filter(t => t));
              tagSet.delete(tag);
              r['Tags'] = Array.from(tagSet).join(', ');
          }
      });
      onDataUpdate(newData);
  };

  const applyBulkTag = () => {
      if (!bulkTagInput) return;
      const newData = [...data];
      newData.forEach(row => {
          const currentTags = String(row['Tags'] || '');
          const tagSet = new Set(currentTags.split(',').map(t => t.trim()).filter(t => t));
          tagSet.add(bulkTagInput.trim());
          row['Tags'] = Array.from(tagSet).join(', ');
      });
      onDataUpdate(newData);
      setBulkTagInput('');
      setIsBulkTagOpen(false);
  };

  const filteredData = data.filter(row => row['Title'] || row['Image Src']).filter(row => 
    Object.values(row).some(val => String(val).toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const currentTags = String(data[selectedRowIndex]?.['Tags'] || '').split(',').map(t => t.trim()).filter(t => t);

  return (
    <div className="bg-white flex flex-col h-full overflow-hidden relative">
      {/* PROCESSING OVERLAY */}
      {isBulkProcessing && (
        <div className="absolute inset-0 z-[100] bg-slate-900/40 backdrop-blur-sm flex flex-col items-center justify-center p-8">
