      "images": ["url1", "url2", "url3", "url4", "url5", "url6", "url7", "url8", "url9", "url10"]
    }`;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
            tools: [{googleSearch: {}}],
            thinkingConfig: { thinkingBudget: 0 } // Flash is better without high budget for this specific extraction
        }
    });

    try {
        const text = response.text || '';
        const jsonStr = text.match(/\{[\s\S]*\}/)?.[0] || '{}';
        const data = JSON.parse(jsonStr);

        const validImages = (data.images || []).map(cleanImageUrl).filter(u => u);

        // Secondary safety: check grounding chunks if no images found in JSON
        if (validImages.length === 0) {
            const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
            if (chunks) {
                chunks.forEach(c => {
                    if (c.web?.uri && (c.web.uri.match(/\.(jpg|jpeg|png|webp)/i) || c.web.uri.includes('cdn'))) {
                        const clean = cleanImageUrl(c.web.uri);
                        if (clean) validImages.push(clean);
                    }
                });
            }
        }

        const handle = (data.title || `${brand}-${sku}`).toLowerCase().replace(/[^a-z0-9]+/g, '-');

        const mainRow: ProductRow = {
            'Handle': handle,
            'Title': data.title || `${brand} ${sku}`,
            'Body (HTML)': data.body_html || '',
            'Vendor': normalizeVendor(brand),
            'Product Category': '',
            'Type': '',
            'Tags': '',
            'Option1 Name': 'Title',
            'Option1 Value': 'Default Title',
            'Variant SKU': sku,
            'Variant Price': data.price || '',
            'Image Src': validImages[0] || '',
            'Image Position': 1,
            'Status': 'draft'
        };

        const extraRows = Array.from(new Set(validImages.slice(1))).map((img: string, i: number) => ({
            'Handle': handle,
            'Image Src': img,
            'Image Position': i + 2,
            'Image Alt Text': mainRow['Title']
        }));

        return [mainRow, ...extraRows];
    } catch (e) {
        console.error("AI Generation Error:", e);
        return [{
            'Handle': `${brand}-${sku}`.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
            'Title': `${brand} ${sku}`,
            'Vendor': normalizeVendor(brand),
            'Variant SKU': sku,
            'Status': 'draft'
        }];
    }
};

export const downloadCSV = (data: ProductRow[]) => {
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Products");
  XLSX.writeFile(wb, 'shopify_import.csv');
};

import React, { useState, useRef } from 'react';
import { ProductRow } from '../types';
