  const handleDownload = () => {
    downloadCSV(data);
  };

  const getApiKey = (): string | undefined => {
      try {
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              return process.env.API_KEY;
          }
      } catch (e) { console.error(e); }
      return undefined;
  };

  const handleEnhanceSingle = async () => {
    const apiKey = getApiKey();
    if (!apiKey) return;

    setIsEnhancing(true);
    setEnhancedDescription('');

    try {
      const row = data[selectedRowIndex];
      const brand = String(row['Vendor'] || '');
      const sku = String(row['Variant SKU'] || '');
      const title = String(row['Title'] || '');

      const ai = new GoogleGenAI({ apiKey });
      const prompt = `Deep Research product: "${brand} ${sku} ${title}". 
      FIND:
      1. Up to 10 DIRECT High-Resolution product image URLs (links ending in .jpg, .png).
      2. Comprehensive HTML description with feature bullets and a specs table.
      3. Current Canadian retail price (CAD).

      Output ONLY a JSON object: { "title", "images": ["url1", "..."], "body_html", "price" }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { tools: [{googleSearch: {}}] }
      });

      const text = response.text || '';
      const jsonStr = text.match(/\{[\s\S]*\}/)?.[0] || '{}';
      const result = JSON.parse(jsonStr);

      const handle = row['Handle'];
      let workingData = [...data];

      if (result.images && result.images.length > 0) {
          const cleanedImages = Array.from(new Set(result.images.filter((url: string) => url.match(/\.(jpg|jpeg|png|webp)/i) || url.includes('cdn')))).slice(0, 10);

          if (cleanedImages.length > 0) {
              const others = workingData.filter(r => r['Handle'] !== handle);
              const baseProduct = workingData.find(r => r['Handle'] === handle && r['Title']) || row;

              const updatedMainRow = { 
                  ...baseProduct, 
                  'Image Src': cleanedImages[0], 
                  'Image Position': 1,
                  'Body (HTML)': result.body_html || baseProduct['Body (HTML)'],
                  'Variant Price': result.price || baseProduct['Variant Price']
              };

              const extraImageRows = cleanedImages.slice(1).map((img, i) => ({
                  'Handle': handle,
                  'Image Src': img,
                  'Image Position': i + 2,
                  'Image Alt Text': updatedMainRow['Title']
              }));

              workingData = [...others, updatedMainRow, ...extraImageRows];
          }
      }

      onDataUpdate(workingData);
      alert("Research complete! Images and data updated.");
    } catch (e: any) {
      console.error(e);
      alert(`Research failed: ${e.message}`);
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleBulkEnhance = async () => {
    const apiKey = getApiKey();
    if (!apiKey) return;

    setIsBulkProcessing(true);
    setProcessingStatus('AI Agents hunting for high-res images...');
    stopProcessingRef.current = false;

    const handlesToProcess = Array.from(new Set(data.map(r => r['Handle'])));
    setBulkProgress({ current: 0, total: handlesToProcess.length, successes: 0, failures: 0 });

    const ai = new GoogleGenAI({ apiKey });
