                        setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
                    }
                } else {
                    setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
                }
            } catch (err) {
                setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
            }

            // Periodic update to UI
            if (i % 2 === 0) onDataUpdate([...workingData]);
            await new Promise(r => setTimeout(r, 800)); // Rate limiting safety
        }
        onDataUpdate(workingData);
    } catch (e: any) {
        alert("Bulk research stopped: " + e.message);
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const filteredData = data.filter(row => row['Title'] || row['Image Src']).filter(row => 
    Object.values(row).some(val => String(val).toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const currentTags = String(data[selectedRowIndex]?.['Tags'] || '').split(',').map(t => t.trim()).filter(t => t);

  return (
    <div className="bg-white flex flex-col h-full overflow-hidden relative">
      {/* PROCESSING OVERLAY */}
      {isBulkProcessing && (
        <div className="absolute inset-0 z-[100] bg-slate-900/60 backdrop-blur-sm flex flex-col items-center justify-center p-8">
            <div className="w-full max-w-md bg-white p-12 rounded-[2.5rem] shadow-2xl text-center">
                <div className="w-24 h-24 bg-emerald-100 rounded-full mx-auto flex items-center justify-center mb-8">
                    <svg className="w-12 h-12 text-emerald-600 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                <h3 className="text-2xl font-black text-slate-900 mb-2">Researching Catalog</h3>
                <p className="text-slate-500 mb-8 font-medium">{processingStatus}</p>
                <div className="w-full bg-slate-100 rounded-full h-3 mb-8 overflow-hidden">
                    <div className="bg-emerald-500 h-full transition-all duration-300" style={{ width: `${(bulkProgress.current / Math.max(bulkProgress.total, 1)) * 100}%` }}></div>
                </div>
                <div className="flex justify-center space-x-6 mb-10">
                    <div className="flex flex-col"><span className="text-2xl font-black text-emerald-600">{bulkProgress.successes}</span><span className="text-[10px] font-bold text-slate-400 uppercase">Found</span></div>
