                <button onClick={() => stopProcessingRef.current = true} className="w-full py-4 border-2 border-slate-100 text-slate-400 font-bold rounded-2xl hover:bg-rose-50 hover:text-rose-500 hover:border-rose-100 transition-all uppercase tracking-widest text-xs">Stop AI Agent</button>
