               <div className="space-y-4">
                   <div className="flex justify-between items-end">
                       <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Verified Assets</label>
                       <span className="text-[10px] font-black text-emerald-600 uppercase bg-emerald-50 px-2 py-0.5 rounded">{data.filter(r => r['Handle'] === data[selectedRowIndex]?.['Handle'] && r['Image Src']).length} Images</span>
                   </div>
                   <div className="grid grid-cols-2 gap-6">
                       {data.filter(r => r['Handle'] === data[selectedRowIndex]?.['Handle'] && r['Image Src']).map((imgRow, idx) => (
