interface PreviewStepProps {
  data: ProductRow[];
  onDataUpdate: (newData: ProductRow[]) => void;
  onReset: () => void;
}

export const PreviewStep: React.FC<PreviewStepProps> = ({ data, onDataUpdate, onReset }) => {
  const [activeTab, setActiveTab] = useState<'preview' | 'stats'>('preview');
  const [searchTerm, setSearchTerm] = useState('');
  const [enhancedDescription, setEnhancedDescription] = useState<string>('');
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [selectedRowIndex, setSelectedRowIndex] = useState(0);

  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [bulkProgress, setBulkProgress] = useState({ current: 0, total: 0, successes: 0, failures: 0 });
  const [processingStatus, setProcessingStatus] = useState('');
  const stopProcessingRef = useRef(false);

  // Group by handle for stats
  const uniqueHandles = Array.from(new Set(data.map(r => r['Handle'])));
  const totalProductsCount = uniqueHandles.length;
  const withImagesCount = uniqueHandles.filter(h => data.some(r => r['Handle'] === h && r['Image Src'])).length;
  const withPriceCount = uniqueHandles.filter(h => data.some(r => r['Handle'] === h && r['Variant Price'])).length;

  const chartData = [
    { name: 'Total Products', value: totalProductsCount },
    { name: 'With Images', value: withImagesCount },
    { name: 'With Prices', value: withPriceCount },
  ];

  const handleDownload = () => {
    downloadCSV(data);
  };

  const getApiKey = (): string | undefined => {
      try {
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              return process.env.API_KEY;
          }
      } catch (e) { console.error(e); }
      return undefined;
  };

  const cleanImageUrl = (url: string): string => {
    if (!url) return '';
    const u = url.trim().toLowerCase();
    // Aggressive filter for thumbnails and logos
    if (u.includes('gstatic.com') || u.includes('encrypted-tbn') || u.includes('googleusercontent') || u.includes('logo') || u.includes('icon')) {
      return '';
    }
    return url;
  };

  const handleEnhanceSingle = async () => {
    const apiKey = getApiKey();
    if (!apiKey) return;

    setIsEnhancing(true);
    setEnhancedDescription('');

    try {
      const row = data[selectedRowIndex];
      const brand = String(row['Vendor'] || '');
      const sku = String(row['Variant SKU'] || '');
      const title = String(row['Title'] || '');

      const ai = new GoogleGenAI({ apiKey });
      const prompt = `Hunt for High-Res Assets for product: "${brand} ${sku} ${title}".

      CRITICAL: Find at least 5-10 direct image links to the PHYSICAL PRODUCT.
      - DO NOT include site logos (Home Depot logo, etc).
      - DO NOT include Google thumbnails (gstatic).
      - DO include direct brand/retailer JPG/PNG links.

      Return JSON: { "images": ["url1", "..."], "body_html", "price" }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { tools: [{googleSearch: {}}] }
      });

      const text = response.text || '';
      const jsonStr = text.match(/\{[\s\S]*\}/)?.[0] || '{}';
      const result = JSON.parse(jsonStr);

      const handle = row['Handle'];
      let workingData = [...data];

      if (result.images && result.images.length > 0) {
          const cleanedImages = Array.from(new Set(result.images.filter((url: string) => 
            url.startsWith('http') && 
            !url.includes('gstatic.com') && 
            !url.toLowerCase().includes('logo') &&
            !url.toLowerCase().includes('icon') &&
            (url.match(/\.(jpg|jpeg|png|webp)/i) || url.includes('cdn'))
          ))).slice(0, 10);

          if (cleanedImages.length > 0) {
              const others = workingData.filter(r => r['Handle'] !== handle);
              const baseProduct = workingData.find(r => r['Handle'] === handle && r['Title']) || row;

              const updatedMainRow = { 
                  ...baseProduct, 
                  'Image Src': cleanedImages[0], 
                  'Image Position': 1,
                  'Body (HTML)': result.body_html || baseProduct['Body (HTML)'],
                  'Variant Price': result.price || baseProduct['Variant Price']
              };

              const extraImageRows = cleanedImages.slice(1).map((img, i) => ({
                  'Handle': handle,
                  'Image Src': img,
                  'Image Position': i + 2,
                  'Image Alt Text': updatedMainRow['Title']
              }));

              workingData = [...others, updatedMainRow, ...extraImageRows];
              onDataUpdate(workingData);
          }
      }
    } catch (e: any) {
      console.error(e);
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleBulkEnhance = async () => {
