    try {
      const row = data[selectedRowIndex];
      const brand = String(row['Vendor'] || '');
      const sku = String(row['Variant SKU'] || '');
      const title = String(row['Title'] || '');

      const ai = new GoogleGenAI({ apiKey });
      const prompt = `Deep Scrape High-Res Assets for: "${brand} ${sku} ${title}".

      CRITICAL: Find 10 direct image links to the PHYSICAL product.
      - DO NOT include store logos.
      - DO NOT include broken Google thumbnails (gstatic.com).
      - ONLY include high-res JPG/PNG from manufacturer or reputable industrial CDNs.

      Return JSON: { "images": ["url1", "..."], "body_html", "price" }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { tools: [{googleSearch: {}}] }
      });

      const text = response.text || '';
      const jsonStr = text.match(/\{[\s\S]*\}/)?.[0] || '{}';
