                const text = response.text || '';
                const jsonStr = text.match(/\{[\s\S]*\}/)?.[0] || '{}';
                const result = JSON.parse(jsonStr);

                if (result.images && result.images.length > 0) {
                    const cleaned = Array.from(new Set(result.images.filter((url: string) => 
                        url.startsWith('http') && 
                        !url.includes('gstatic.com') && 
                        !url.toLowerCase().includes('logo') &&
                        (url.match(/\.(jpg|jpeg|png|webp)/i) || url.includes('cdn'))
                    ))).slice(0, 10);

                    if (cleaned.length > 0) {
                        const others = workingData.filter(r => r['Handle'] !== handle);
                        const mainRow = { 
                            ...baseRow, 
                            'Image Src': cleaned[0], 
                            'Image Position': 1,
                            'Variant Price': result.price || baseRow['Variant Price']
                        };
                        const extras = cleaned.slice(1).map((img, idx) => ({
                            'Handle': handle,
                            'Image Src': img,
                            'Image Position': idx + 2,
                            'Image Alt Text': mainRow['Title']
                        }));
                        workingData = [...others, mainRow, ...extras];
                        setBulkProgress(prev => ({ ...prev, successes: prev.successes + 1 }));
                    } else {
                        setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
                    }
                } else {
                    setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
                }
            } catch (err) {
                setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
            }

            if (i % 2 === 0) onDataUpdate([...workingData]);
            await new Promise(r => setTimeout(r, 800));
        }
        onDataUpdate(workingData);
    } catch (e: any) {
        console.error(e);
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const filteredData = data.filter(row => row['Title'] || row['Image Src']).filter(row => 
