  };

  const handleManualEntry = async (brand: string, skuInput: string) => {
      const apiKey = getApiKey();
      if (!apiKey) { alert("API Key missing."); return; }
      setIsProcessing(true);
      const skus = skuInput.split(/[\n,]+/).map(s => s.trim()).filter(s => s);
      if (skus.length === 0) { setIsProcessing(false); return; }
      const allData: ProductRow[] = [];
      try {
          for (let i = 0; i < skus.length; i++) {
              setProgressMessage(`Researching ${i + 1}/${skus.length}: ${brand} ${skus[i]}...`);
              if (i > 0) await new Promise(r => setTimeout(r, 1000));
              try {
                  const rows = await createProductFromSku(brand, skus[i], apiKey);
                  allData.push(...rows);
              } catch (err) { console.error(err); }
          }
          if (allData.length === 0) throw new Error("No data generated.");
          setProcessedData(allData);
          setStep(AppState.PREVIEW);
      } catch (error: any) { alert(error.message); } finally { setIsProcessing(false); }
  };

  const handleMappingConfirm = async (mapping: Mapping) => {
    const rawShopifyData = generateShopifyData(sourceData, mapping);
    const apiKey = getApiKey();

    // Automatically Enrichment Phase: If no images are found, try to research them in background
    if (apiKey) {
        setIsProcessing(true);
        setStep(AppState.UPLOAD); // Temporary visual back to processing

        const handlesWithNoImages = Array.from(new Set(rawShopifyData.filter(r => !r['Image Src'] || r['Image Src'].includes('placehold.co')).map(r => r['Handle'])));
        let workingData = [...rawShopifyData];

        if (handlesWithNoImages.length > 0) {
            const ai = new GoogleGenAI({ apiKey });
            for (let i = 0; i < handlesWithNoImages.length; i++) {
                const handle = handlesWithNoImages[i];
                const baseRow = workingData.find(r => r['Handle'] === handle && r['Title']);
                if (!baseRow) continue;

                setProgressMessage(`Auto-Enriching Asset ${i + 1}/${handlesWithNoImages.length}: ${baseRow['Title']}...`);

                try {
                    const prompt = `Find 5 direct product photo JPG/PNG URLs for: "${baseRow['Vendor']} ${baseRow['Variant SKU']}". 
                    - PRIORITIZE amazon, shopify, or manufacturer CDNs. 
                    - STRICTLY NO LOGOS. NO GSTATIC.
                    - Return JSON: { "images": ["url1", "..."] }`;

                    const response = await ai.models.generateContent({
                        model: 'gemini-3-flash-preview',
                        contents: prompt,
                        config: { tools: [{googleSearch: {}}] }
                    });

                    const jsonStr = response.text.match(/\{[\s\S]*\}/)?.[0] || '{}';
                    const result = JSON.parse(jsonStr);

                    if (result.images && result.images.length > 0) {
                        const cleaned = result.images.map(cleanImageUrl).filter((u: string) => u);
                        if (cleaned.length > 0) {
                            const others = workingData.filter(r => r['Handle'] !== handle);
                            const updatedRow = { ...baseRow, 'Image Src': cleaned[0], 'Image Position': 1 };
                            const extraRows = cleaned.slice(1).map((img: string, idx: number) => ({
                                'Handle': handle,
                                'Image Src': img,
                                'Image Position': idx + 2,
                                'Image Alt Text': updatedRow['Title']
                            }));
                            workingData = [...others, updatedRow, ...extraRows];
                        }
                    }
                } catch (err) { console.error("Enrichment failed for " + handle, err); }

                if (i > 0 && i % 3 === 0) await new Promise(r => setTimeout(r, 1000));
            }
        }
        setProcessedData(workingData);
        setIsProcessing(false);
    } else {
        setProcessedData(rawShopifyData);
    }

    setStep(AppState.PREVIEW);
  };

  const handleReset = () => {
      setStep(AppState.UPLOAD);
      setSourceData([]);
      setProcessedData([]);
  };

  return (
    <div className="h-full flex flex-col bg-slate-50 text-slate-900 overflow-hidden font-sans">
      <header className="bg-slate-900 text-white shadow-2xl z-50 sticky top-0 border-b border-white/5 flex-none">
        <div className="max-w-screen-2xl mx-auto px-8 py-5 flex items-center justify-between">
            <div className="flex items-center space-x-5">
                <div className="bg-emerald-500 p-2.5 rounded-xl shadow-lg shadow-emerald-500/20">
                    <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012-2v2M7 7h10" /></svg>
                </div>
                <div>
                    <h1 className="text-xl font-black tracking-tight text-white uppercase leading-none">Shopify Transformer</h1>
                    <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 block">Advanced Data Engine</span>
                </div>
            </div>

            <div className="flex items-center space-x-6">
                 {step !== AppState.UPLOAD && (
                     <button onClick={handleReset} className="text-xs font-bold text-slate-400 hover:text-white transition-all uppercase tracking-widest">
                        ← Restart
                     </button>
                 )}
                <div className="flex items-center space-x-2 bg-slate-800 px-4 py-2 rounded-full border border-slate-700">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Gemini 3 Flash • Online</span>
                </div>
            </div>
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative flex flex-col min-h-0">
            {step === AppState.UPLOAD && (
                <div className="flex-1 overflow-y-auto px-8 py-12">
                     <div className="max-w-4xl mx-auto flex flex-col items-center">
                        <div className="text-center mb-16">
                            <h2 className="text-5xl font-black text-slate-900 mb-6 tracking-tight">Catalogs to <span className="text-emerald-600">Conversions.</span></h2>
                            <p className="text-slate-500 text-xl font-medium max-w-2xl mx-auto">Research and transform messy supplier data into professional Shopify product listings instantly.</p>
                        </div>
                        <div className="w-full shadow-2xl rounded-[2.5rem] bg-white border border-slate-100 p-2">
                            <FileUpload 
                                onFileSelect={handleFileSelect} 
                                onManualEntry={handleManualEntry}
                                isProcessing={isProcessing} 
                                progressMessage={progressMessage}
                            />
                        </div>
                     </div>
                </div>
            )}

            {step === AppState.MAPPING && (
                 <div className="flex-1 p-8 overflow-hidden bg-slate-50">
                    <div className="h-full max-w-screen-2xl mx-auto shadow-2xl rounded-3xl overflow-hidden bg-white border border-slate-100">
                        <MappingStep 
                            sourceHeaders={sourceHeaders} 
                            sourceData={sourceData}
                            onConfirm={handleMappingConfirm}
                            logs={logs}
                            onBack={handleReset}
                        />
                    </div>
                </div>
            )}

            {step === AppState.PREVIEW && (
                <div className="flex-1 p-8 overflow-hidden bg-slate-50">
                    <div className="h-full max-w-screen-2xl mx-auto shadow-2xl rounded-3xl overflow-hidden bg-white border border-slate-100">
                        <PreviewStep data={processedData} onDataUpdate={setProcessedData} onReset={handleReset} />
                    </div>
                </div>
            )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { ProductRow } from '../types';
import { downloadCSV, cleanImageUrl } from '../services/excelService';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { GoogleGenAI } from "@google/genai";

interface PreviewStepProps {
  data: ProductRow[];
  onDataUpdate: (newData: ProductRow[]) => void;
  onReset: () => void;
}

export const PreviewStep: React.FC<PreviewStepProps> = ({ data, onDataUpdate, onReset }) => {
  const [activeTab, setActiveTab] = useState<'preview' | 'stats'>('preview');
  const [searchTerm, setSearchTerm] = useState('');
  const [enhancedDescription, setEnhancedDescription] = useState<string>('');
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [selectedRowIndex, setSelectedRowIndex] = useState(0);

  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [bulkProgress, setBulkProgress] = useState({ current: 0, total: 0, successes: 0, failures: 0 });
  const [processingStatus, setProcessingStatus] = useState('');
  const stopProcessingRef = useRef(false);

  // Group by handle for stats
  const uniqueHandles = Array.from(new Set(data.map(r => r['Handle'])));
  const totalProductsCount = uniqueHandles.length;
  const withImagesCount = uniqueHandles.filter(h => data.some(r => r['Handle'] === h && r['Image Src'] && !r['Image Src'].includes('placehold.co'))).length;
  const withPriceCount = uniqueHandles.filter(h => data.some(r => r['Handle'] === h && r['Variant Price'])).length;

  const chartData = [
    { name: 'Total Products', value: totalProductsCount },
    { name: 'Verified Images', value: withImagesCount },
    { name: 'Prices Found', value: withPriceCount },
  ];

  const handleDownload = () => {
    downloadCSV(data);
  };

  const getApiKey = (): string | undefined => {
      try {
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              return process.env.API_KEY;
          }
      } catch (e) { console.error(e); }
      return undefined;
  };

  // Uses a public proxy to bypass common hotlink protection on retailer sites
  const getProxiedUrl = (url: string) => {
      if (!url || url.includes('placehold.co') || url.includes('weserv.nl')) return url;
      return `https://images.weserv.nl/?url=${encodeURIComponent(url)}&default=https://placehold.co/400x400?text=Asset+Pending`;
  };

  const handleEnhanceSingle = async () => {
    const apiKey = getApiKey();
    if (!apiKey) return;

    setIsEnhancing(true);
    setEnhancedDescription('');

    try {
      const row = data[selectedRowIndex];
      const brand = String(row['Vendor'] || '');
      const sku = String(row['Variant SKU'] || '');
      const title = String(row['Title'] || '');

      const ai = new GoogleGenAI({ apiKey });
      const prompt = `Research high-resolution direct product JPG/PNG links for: "${brand} ${sku} ${title}".

      - PRIORITIZE Amazon, Shopify, or manufacturer CDNs. 
      - STRICTLY NO GSTATIC, ENCRYPTED-TBN, OR LOGOS.
      - Return JSON: { "images": ["url1", "..."], "body_html", "price" }`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { tools: [{googleSearch: {}}] }
      });

      const result = JSON.parse(response.text.match(/\{[\s\S]*\}/)?.[0] || '{}');
      const handle = row['Handle'];
      let workingData = [...data];

      if (result.images && result.images.length > 0) {
          const cleanedImages = Array.from(new Set(result.images.map(cleanImageUrl).filter((u: string) => u))).slice(0, 10);

          if (cleanedImages.length > 0) {
              const others = workingData.filter(r => r['Handle'] !== handle);
              const baseProduct = workingData.find(r => r['Handle'] === handle && r['Title']) || row;

              const updatedMainRow = { 
                  ...baseProduct, 
                  'Image Src': cleanedImages[0], 
                  'Image Position': 1,
                  'Body (HTML)': result.body_html || baseProduct['Body (HTML)'],
                  'Variant Price': result.price || baseProduct['Variant Price']
              };

              const extraImageRows = cleanedImages.slice(1).map((img: string, i: number) => ({
                  'Handle': handle,
                  'Image Src': img,
                  'Image Position': i + 2,
                  'Image Alt Text': updatedMainRow['Title']
              }));

              workingData = [...others, updatedMainRow, ...extraImageRows];
              onDataUpdate(workingData);
          }
      }
    } catch (e: any) {
      console.error(e);
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleBulkEnhance = async () => {
    const apiKey = getApiKey();
    if (!apiKey) return;

    setIsBulkProcessing(true);
    setProcessingStatus('AI Agents conducting deep visual research...');
    stopProcessingRef.current = false;

    const handlesToProcess = Array.from(new Set(data.map(r => r['Handle'])));
    setBulkProgress({ current: 0, total: handlesToProcess.length, successes: 0, failures: 0 });

    const ai = new GoogleGenAI({ apiKey });
    let workingData = [...data];

    try {
        for (let i = 0; i < handlesToProcess.length; i++) {
            if (stopProcessingRef.current) break;
            const handle = handlesToProcess[i];
            const baseRow = workingData.find(r => r['Handle'] === handle && r['Title']);
            if (!baseRow) continue;

            setProcessingStatus(`Researching Assets (${i + 1}/${handlesToProcess.length}): ${baseRow['Title']}...`);
            setBulkProgress(prev => ({ ...prev, current: i + 1 }));

            const prompt = `Find 10 direct high-res JPG URLs for: "${baseRow['Vendor']} ${baseRow['Variant SKU']}". 
            - PREFER amazon, shopify, or manufacturer CDNs. 
            - NO gstatic. NO LOGOS.
            - Return JSON: { "images": ["url1", "..."], "price" }`;

            try {
                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: prompt,
                    config: { tools: [{googleSearch: {}}] }
                });

                const result = JSON.parse(response.text.match(/\{[\s\S]*\}/)?.[0] || '{}');

                if (result.images && result.images.length > 0) {
                    const cleaned = Array.from(new Set(result.images.map(cleanImageUrl).filter((u: string) => u))).slice(0, 10);

                    if (cleaned.length > 0) {
                        const others = workingData.filter(r => r['Handle'] !== handle);
                        const mainRow = { 
                            ...baseRow, 
                            'Image Src': cleaned[0], 
                            'Image Position': 1,
                            'Variant Price': result.price || baseRow['Variant Price']
                        };
                        const extras = cleaned.slice(1).map((img: string, idx: number) => ({
                            'Handle': handle,
                            'Image Src': img,
                            'Image Position': idx + 2,
                            'Image Alt Text': mainRow['Title']
                        }));
                        workingData = [...others, mainRow, ...extras];
                        setBulkProgress(prev => ({ ...prev, successes: prev.successes + 1 }));
                    } else {
                        setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
                    }
                } else {
                    setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
                }
            } catch (err) {
                setBulkProgress(prev => ({ ...prev, failures: prev.failures + 1 }));
            }

            if (i % 2 === 0) onDataUpdate([...workingData]);
            await new Promise(r => setTimeout(r, 1000));
        }
        onDataUpdate(workingData);
    } catch (e: any) {
        console.error(e);
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const filteredData = data.filter(row => row['Title'] || row['Image Src']).filter(row => 
    Object.values(row).some(val => String(val).toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <div className="bg-white flex flex-col h-full overflow-hidden relative">
      {/* PROCESSING OVERLAY */}
      {isBulkProcessing && (
        <div className="absolute inset-0 z-[100] bg-slate-900/60 backdrop-blur-sm flex flex-col items-center justify-center p-8">
            <div className="w-full max-w-md bg-white p-12 rounded-[2.5rem] shadow-2xl text-center">
                <div className="w-24 h-24 bg-emerald-100 rounded-full mx-auto flex items-center justify-center mb-8 shadow-inner">
                    <svg className="w-12 h-12 text-emerald-600 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                <h3 className="text-2xl font-black text-slate-900 mb-2">Mining Assets</h3>
                <p className="text-slate-500 mb-8 font-medium">{processingStatus}</p>
                <div className="w-full bg-slate-100 rounded-full h-3 mb-8 overflow-hidden">
                    <div className="bg-emerald-500 h-full transition-all duration-300" style={{ width: `${(bulkProgress.current / Math.max(bulkProgress.total, 1)) * 100}%` }}></div>
                </div>
                <div className="flex justify-center space-x-6 mb-10">
                    <div className="flex flex-col"><span className="text-2xl font-black text-emerald-600">{bulkProgress.successes}</span><span className="text-[10px] font-bold text-slate-400 uppercase">Found</span></div>
                    <div className="flex flex-col"><span className="text-2xl font-black text-slate-300">{bulkProgress.failures}</span><span className="text-[10px] font-bold text-slate-400 uppercase">Missing</span></div>
                </div>
                <button onClick={() => stopProcessingRef.current = true} className="w-full py-4 border-2 border-slate-100 text-slate-400 font-bold rounded-2xl hover:bg-rose-50 hover:text-rose-500 hover:border-rose-100 transition-all uppercase tracking-widest text-xs">Stop AI Agent</button>
            </div>
        </div>
      )}

      {/* TOOLBAR */}
      <div className="px-10 py-6 border-b border-slate-100 flex flex-col lg:flex-row justify-between items-center bg-white z-20 gap-6">
         <div className="flex items-center space-x-10 w-full lg:w-auto">
            <div className="flex-none">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase leading-none">Dataset View</h2>
