            <div className="flex bg-slate-100 p-1.5 rounded-2xl">
                <button onClick={() => setActiveTab('preview')} className={`px-6 py-2 text-xs font-black rounded-[14px] transition-all ${activeTab === 'preview' ? 'bg-white text-slate-900 shadow-xl shadow-slate-200' : 'text-slate-500'}`}>DATA TABLE</button>
                <button onClick={() => setActiveTab('stats')} className={`px-6 py-2 text-xs font-black rounded-[14px] transition-all ${activeTab === 'stats' ? 'bg-white text-slate-900 shadow-xl shadow-slate-200' : 'text-slate-500'}`}>ANALYTICS</button>
            </div>
         </div>

         <div className="flex flex-wrap gap-4 items-center w-full lg:w-auto">
             <div className="relative flex-1 lg:flex-none lg:w-80">
