             <button onClick={() => handleBulkEnhance()} className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-emerald-600 shadow-2xl shadow-slate-200 transition-all flex items-center group">
