             <button onClick={handleDownload} className="px-8 py-4 bg-emerald-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-emerald-700 shadow-2xl shadow-emerald-200 transition-all">
                Export CSV
             </button>
         </div>
      </div>

      <div className="flex-1 overflow-hidden flex bg-slate-50">
        {activeTab === 'stats' ? (
           <div className="flex-1 p-16 overflow-y-auto">
               <div className="max-w-5xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-10">
                   <div className="lg:col-span-2 bg-white p-12 rounded-[3rem] shadow-sm border border-slate-100 h-[500px]">
                      <h3 className="text-xl font-black mb-10 text-slate-900 uppercase tracking-widest">Dataset Readiness</h3>
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={chartData}>
