                          <YAxis axisLine={false} tickLine={false} tick={{fill: '#cbd5e1', fontWeight: 'bold', fontSize: 10}} />
                          <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{borderRadius: '24px', border: 'none', boxShadow: '0 30px 40px -10px rgba(0, 0, 0, 0.15)', padding: '24px'}} />
                          <Bar dataKey="value" barSize={80} radius={[20, 20, 20, 20]}>
                            {chartData.map((entry, index) => <Cell key={`cell-${index}`} fill={['#10b981', '#3b82f6', '#8b5cf6'][index % 3]} />)}
                          </Bar>
                        </BarChart>
                      </ResponsiveContainer>
                   </div>
                   <div className="space-y-8">
                       <div className="bg-emerald-600 p-8 rounded-[2.5rem] text-white shadow-xl shadow-emerald-100">
                           <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60 mb-1">Asset Health</p>
                           <p className="text-5xl font-black">{totalProductsCount > 0 ? Math.round((withImagesCount/totalProductsCount)*100) : 0}%</p>
                           <p className="text-xs mt-4 font-medium leading-relaxed opacity-80">Percentage of unique handles containing at least one verified high-resolution asset link.</p>
                       </div>
                       <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                           <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-1">Asset Bank</p>
                           <p className="text-5xl font-black text-slate-900">{withImagesCount}</p>
                           <p className="text-xs mt-4 text-slate-500 font-medium">Valid high-res image groups discovered across current collection.</p>
