import React, { useState } from 'react';
import { FileUpload } from './components/FileUpload';
import { MappingStep } from './components/MappingStep';
import { PreviewStep } from './components/PreviewStep';
import { parseExcel, generateShopifyData, createProductFromSku, cleanImageUrl } from './services/excelService';
import { AppState, Mapping, ProductRow } from './types';

const App: React.FC = () => {
  const [step, setStep] = useState<AppState>(AppState.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progressMessage, setProgressMessage] = useState('');
  const [sourceHeaders, setSourceHeaders] = useState<string[]>([]);
  const [sourceData, setSourceData] = useState<ProductRow[]>([]);
  const [processedData, setProcessedData] = useState<ProductRow[]>([]);
  const [logs, setLogs] = useState<string[]>([]);

  const getApiKey = (): string | undefined => {
      try {
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              return process.env.API_KEY;
          }
      } catch (e) { console.error(e); }
      return undefined;
  };

  const handleFileSelect = async (file: File) => {
    setIsProcessing(true);
    setProgressMessage('Analyzing catalog architecture...');
    setTimeout(async () => {
        try {
            const { headers, data, logs: processingLogs } = await parseExcel(file);
            setSourceHeaders(headers);
            setSourceData(data);
            setLogs(processingLogs);
            setStep(AppState.MAPPING);
        } catch (error) {
            console.error(error);
            alert("Error parsing file.");
        } finally {
            setIsProcessing(false);
            setProgressMessage('');
        }
    }, 100);
  };

  const handleManualEntry = async (brand: string, skuInput: string) => {
      const apiKey = getApiKey();
      if (!apiKey) { alert("API Key missing."); return; }
      setIsProcessing(true);
      const skus = skuInput.split(/[\n,]+/).map(s => s.trim()).filter(s => s);
      if (skus.length === 0) { setIsProcessing(false); return; }
      const allData: ProductRow[] = [];
      try {
          for (let i = 0; i < skus.length; i++) {
              setProgressMessage(`Deep Research Synthesis (${i + 1}/${skus.length}): ${brand} ${skus[i]}...`);
              if (i > 0) await new Promise(r => setTimeout(r, 1500)); 
              try {
                  const rows = await createProductFromSku(brand, skus[i], apiKey);
                  allData.push(...rows);
              } catch (err) { console.error(err); }
          }
          if (allData.length === 0) throw new Error("Could not synthesize product data.");
          setProcessedData(allData);
          setStep(AppState.PREVIEW);
      } catch (error: any) { alert(error.message); } finally { setIsProcessing(false); }
  };

  const handleMappingConfirm = async (mapping: Mapping) => {
    const rawShopifyData = generateShopifyData(sourceData, mapping);
    const apiKey = getApiKey();

    if (apiKey) {
        setIsProcessing(true);
        setProgressMessage('Initiating Automated Asset Recovery...');

        const handlesToEnrich = Array.from(new Set(rawShopifyData.filter(r => !r['Image Src'] || r['Image Src'].includes('placehold.co')).map(r => r['Handle'])));
        let workingData = [...rawShopifyData];

        if (handlesToEnrich.length > 0) {
            for (let i = 0; i < handlesToEnrich.length; i++) {
                const handle = handlesToEnrich[i];
                const baseRow = workingData.find(r => r['Handle'] === handle && r['Title']);
                if (!baseRow) continue;

                setProgressMessage(`Mined Assets for ${baseRow['Title']} (${i + 1}/${handlesToEnrich.length})...`);

                try {
                    const brand = baseRow['Vendor'] || '';
                    const sku = baseRow['Variant SKU'] || '';
                    const rows = await createProductFromSku(brand, sku, apiKey);

                    if (rows.length > 0) {
                        const others = workingData.filter(r => r['Handle'] !== handle);
                        const enrichedMain = { 
                            ...baseRow, 
                            'Image Src': rows[0]['Image Src'] || baseRow['Image Src'],
                            'Body (HTML)': rows[0]['Body (HTML)'] || baseRow['Body (HTML)'],
                            'Variant Price': rows[0]['Variant Price'] || baseRow['Variant Price'],
                            'Title': rows[0]['Title'] || baseRow['Title']
                        };
                        const enrichedExtras = rows.slice(1);
                        workingData = [...others, enrichedMain, ...enrichedExtras];
                    }
                } catch (err) { console.error("Asset recovery failed for " + handle, err); }

                await new Promise(r => setTimeout(r, 1200)); 
            }
        }
        setProcessedData(workingData);
        setIsProcessing(false);
    } else {
        setProcessedData(rawShopifyData);
    }

    setStep(AppState.PREVIEW);
  };

  const handleReset = () => {
      setStep(AppState.UPLOAD);
      setSourceData([]);
      setProcessedData([]);
  };

  return (
