    let cleanTitle = title;
    if (brand) cleanTitle = cleanTitle.replace(new RegExp(escapeRegExp(brand), 'gi'), '').trim();
    if (sku) cleanTitle = cleanTitle.replace(new RegExp(escapeRegExp(sku), 'gi'), '').trim();
    newRow['Title'] = [brand, sku, cleanTitle].filter(p => p).join(' ').replace(/\s+/g, ' ').trim();
    newRow['Handle'] = newRow['Title'].toLowerCase().replace(/[^a-z0-9]+/g, '-');

    const mappedImg = mapping['Image Src'] ? row[mapping['Image Src']] : '';
    const genImg = row['_Generated_Images'] || '';

    const rawImagePool = [
        ...String(mappedImg).split(/[|;\n,]+/),
        ...String(genImg).split(/[|;\n,]+/)
    ];

    const finalImages = Array.from(new Set(rawImagePool.map(cleanImageUrl).filter(u => u))).slice(0, 10);

    if (finalImages.length > 0) {
         const firstRow = { ...newRow, 'Image Src': finalImages[0], 'Image Position': 1, 'Image Alt Text': newRow['Title'] };
         const extraRows = finalImages.slice(1).map((img, idx) => ({
             'Handle': firstRow['Handle'],
             'Image Src': img,
             'Image Position': idx + 2,
             'Image Alt Text': firstRow['Title']
         }));
         return [firstRow, ...extraRows];
    }

    return [newRow];
  });
};

export const createProductFromSku = async (brand: string, sku: string, apiKey: string): Promise<ProductRow[]> => {
    const ai = new GoogleGenAI({ apiKey });

    // THE "ULTIMATE CATALOG RESEARCHER" PROMPT
    const prompt = `Act as an elite world-class industrial product specialist. Your goal is to create the absolute best, most comprehensive, and high-converting product page on the entire internet for the following item:

    Target Item: "${brand} ${sku}"

    STEP 1: MULTI-SOURCE SYNTHESIS
    - Research official brand sites, top-tier industrial retailers (Grainger, McMaster-Carr, Fastenal), and major marketplaces (Amazon, Home Depot).
    - Aggregate the best features, most accurate technical specifications, dimensions, and included component lists from all sources.
    - Synthesize this into a cohesive, professional, and high-end presentation.

    STEP 2: AESTHETIC HTML DESIGN
    - Generate a premium HTML-formatted description for a Shopify storefront.
    - Use clean structure with high-contrast <h3> headers.
    - Styling requirement: Use <h3 style="color:#0f172a; font-size:1.1rem; font-weight:800; border-bottom:1px solid #f1f5f9; padding-bottom:0.5rem; margin-top:1.5rem;"> for all section headers.
    - Formatting: Use <ul> with <li> for features. Use <strong> for highlights.
    - Sections MUST include: 'Product Overview', 'Key Performance Features', 'Technical Specifications', and 'Included Accessories'.

    STEP 3: IMAGE SCRAPING (VITAL)
    - Identify 10 high-resolution, PERMANENT direct image URLs.
    - PRIORITY: Official ${brand} media portals, Amazon S3 buckets (media-amazon.com), or established industrial CDNs.
    - FORBIDDEN: DO NOT return gstatic.com, encrypted-tbn, or links containing 'logo'. URLs must lead directly to permanent image files (.jpg, .png).
    - Ensure images are clear and suitable for a professional storefront.

    STEP 4: MARKET PRICING
    - Identify the current Retail MSRP in CAD.

    Output format: STRICT VALID JSON ONLY
    {
      "title": "Clean Authoritative Product Title (Brand + SKU + Product Name)",
      "price": "249.99",
      "body_html": "<div class='premium-listing'>...Structured HTML Content...</div>",
      "images": ["direct_url_1", "direct_url_2", ..., "direct_url_10"]
    }`;

    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview', 
        contents: prompt,
        config: { 
            tools: [{googleSearch: {}}],
            thinkingConfig: { thinkingBudget: 0 }
        }
    });

    try {
        const text = response.text || '';
        const jsonStr = text.match(/\{[\s\S]*\}/)?.[0] || '{}';
        const data = JSON.parse(jsonStr);

        const validImages = (data.images || []).map(cleanImageUrl).filter((u: string) => u);
        const handle = (data.title || `${brand}-${sku}`).toLowerCase().replace(/[^a-z0-9]+/g, '-');

        const mainRow: ProductRow = {
            'Handle': handle,
            'Title': data.title || `${brand} ${sku}`,
            'Body (HTML)': data.body_html || '',
            'Vendor': normalizeVendor(brand),
            'Option1 Name': 'Title',
            'Option1 Value': 'Default Title',
            'Variant SKU': sku,
            'Variant Price': data.price || '',
            'Image Src': validImages[0] || '',
            'Image Position': 1,
            'Status': 'draft'
        };

        const extraRows = Array.from(new Set(validImages.slice(1))).map((img: string, i: number) => ({
            'Handle': handle,
            'Image Src': img,
            'Image Position': i + 2,
            'Image Alt Text': mainRow['Title']
        }));

        return [mainRow, ...extraRows];
    } catch (e) {
        return [{
            'Handle': `${brand}-${sku}`.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
            'Title': `${brand} ${sku}`,
            'Vendor': normalizeVendor(brand),
            'Variant SKU': sku,
            'Status': 'draft'
        }];
    }
};

export const downloadCSV = (data: ProductRow[]) => {
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Products");
  XLSX.writeFile(wb, 'shopify_import.csv');
};

import React, { useState } from 'react';
import { FileUpload } from './components/FileUpload';
import { MappingStep } from './components/MappingStep';
import { PreviewStep } from './components/PreviewStep';
import { parseExcel, generateShopifyData, createProductFromSku, cleanImageUrl } from './services/excelService';
import { AppState, Mapping, ProductRow } from './types';

const App: React.FC = () => {
  const [step, setStep] = useState<AppState>(AppState.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progressMessage, setProgressMessage] = useState('');
  const [sourceHeaders, setSourceHeaders] = useState<string[]>([]);
  const [sourceData, setSourceData] = useState<ProductRow[]>([]);
  const [processedData, setProcessedData] = useState<ProductRow[]>([]);
  const [logs, setLogs] = useState<string[]>([]);

  const getApiKey = (): string | undefined => {
      try {
          if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
              return process.env.API_KEY;
          }
      } catch (e) { console.error(e); }
      return undefined;
  };

  const handleFileSelect = async (file: File) => {
    setIsProcessing(true);
    setProgressMessage('Analyzing catalog architecture...');
    setTimeout(async () => {
        try {
            const { headers, data, logs: processingLogs } = await parseExcel(file);
            setSourceHeaders(headers);
            setSourceData(data);
            setLogs(processingLogs);
            setStep(AppState.MAPPING);
        } catch (error) {
            console.error(error);
            alert("Error parsing file.");
        } finally {
            setIsProcessing(false);
            setProgressMessage('');
        }
    }, 100);
  };

  const handleManualEntry = async (brand: string, skuInput: string) => {
      const apiKey = getApiKey();
      if (!apiKey) { alert("API Key missing."); return; }
      setIsProcessing(true);
      const skus = skuInput.split(/[\n,]+/).map(s => s.trim()).filter(s => s);
      if (skus.length === 0) { setIsProcessing(false); return; }
      const allData: ProductRow[] = [];
      try {
          for (let i = 0; i < skus.length; i++) {
              setProgressMessage(`Internet-Wide Synthesis (${i + 1}/${skus.length}): ${brand} ${skus[i]}...`);
              if (i > 0) await new Promise(r => setTimeout(r, 1200)); 
              try {
                  const rows = await createProductFromSku(brand, skus[i], apiKey);
                  allData.push(...rows);
              } catch (err) { console.error(err); }
          }
          if (allData.length === 0) throw new Error("Could not synthesize product data.");
          setProcessedData(allData);
          setStep(AppState.PREVIEW);
      } catch (error: any) { alert(error.message); } finally { setIsProcessing(false); }
  };

  const handleMappingConfirm = async (mapping: Mapping) => {
    const rawShopifyData = generateShopifyData(sourceData, mapping);
    const apiKey = getApiKey();

    if (apiKey) {
        setIsProcessing(true);
        setProgressMessage('Initiating Automated Deep Research...');

        // Target rows that are likely to benefit from enrichment (missing descriptions or assets)
        const handlesToEnrich = Array.from(new Set(rawShopifyData.filter(r => !r['Image Src'] || r['Image Src'].includes('placehold.co') || !r['Body (HTML)']).map(r => r['Handle'])));
        let workingData = [...rawShopifyData];

        if (handlesToEnrich.length > 0) {
            // Limit automated enrichment to a reasonable set to manage API latency
            const enrichmentBatch = handlesToEnrich.slice(0, 50); 
            for (let i = 0; i < enrichmentBatch.length; i++) {
                const handle = enrichmentBatch[i];
                const baseRow = workingData.find(r => r['Handle'] === handle && r['Title']);
                if (!baseRow) continue;

                setProgressMessage(`Mining Best-in-Class Assets: ${baseRow['Title']} (${i + 1}/${enrichmentBatch.length})...`);

                try {
                    const brand = baseRow['Vendor'] || '';
                    const sku = baseRow['Variant SKU'] || '';
                    const rows = await createProductFromSku(brand, sku, apiKey);

                    if (rows.length > 0) {
                        const others = workingData.filter(r => r['Handle'] !== handle);
                        const enrichedMain = { 
                            ...baseRow, 
                            'Image Src': rows[0]['Image Src'] || baseRow['Image Src'],
                            'Body (HTML)': rows[0]['Body (HTML)'] || baseRow['Body (HTML)'],
                            'Variant Price': rows[0]['Variant Price'] || baseRow['Variant Price'],
                            'Title': rows[0]['Title'] || baseRow['Title']
                        };
                        const enrichedExtras = rows.slice(1);
                        workingData = [...others, enrichedMain, ...enrichedExtras];
                    }
                } catch (err) { console.error("Asset synthesis failed for " + handle, err); }

                await new Promise(r => setTimeout(r, 1000)); 
            }
        }
        setProcessedData(workingData);
        setIsProcessing(false);
    } else {
        setProcessedData(rawShopifyData);
    }

    setStep(AppState.PREVIEW);
  };

  const handleReset = () => {
      setStep(AppState.UPLOAD);
      setSourceData([]);
      setProcessedData([]);
  };

  return (
    <div className="h-full flex flex-col bg-slate-50 text-slate-900 overflow-hidden font-sans">
      <header className="bg-slate-900 text-white shadow-2xl z-50 sticky top-0 border-b border-white/5 flex-none">
        <div className="max-w-screen-2xl mx-auto px-8 py-5 flex items-center justify-between">
            <div className="flex items-center space-x-5">
                <div className="bg-emerald-500 p-2.5 rounded-xl shadow-lg shadow-emerald-500/20">
                    <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012-2v2M7 7h10" /></svg>
                </div>
                <div>
                    <h1 className="text-xl font-black tracking-tight text-white uppercase leading-none">Shopify Transformer</h1>
                    <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 block">Industrial Catalog Synthesis</span>
                </div>
            </div>

            <div className="flex items-center space-x-6">
                 {step !== AppState.UPLOAD && (
                     <button onClick={handleReset} className="text-xs font-bold text-slate-400 hover:text-white transition-all uppercase tracking-widest">
                        ← Restart
                     </button>
                 )}
                <div className="flex items-center space-x-2 bg-slate-800 px-4 py-2 rounded-full border border-slate-700">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Gemini 3 Pro • Deep Search</span>
                </div>
            </div>
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative flex flex-col min-h-0">
            {isProcessing && (
                <div className="absolute inset-0 z-[100] bg-slate-900/60 backdrop-blur-md flex flex-col items-center justify-center p-8">
                    <div className="w-full max-w-md bg-white p-12 rounded-[3rem] shadow-2xl text-center animate-in fade-in zoom-in duration-300">
                        <div className="w-24 h-24 bg-emerald-100 rounded-full mx-auto flex items-center justify-center mb-8 shadow-inner overflow-hidden relative">
                             <div className="absolute inset-0 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                             <svg className="w-10 h-10 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                        </div>
                        <h3 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tight">Marketplace Research</h3>
                        <p className="text-slate-500 mb-8 font-medium leading-relaxed">{progressMessage}</p>
                        <div className="flex items-center space-x-2 justify-center">
                            <div className="w-2 h-2 rounded-full bg-emerald-500 animate-bounce" style={{animationDelay: '0ms'}}></div>
                            <div className="w-2 h-2 rounded-full bg-emerald-500 animate-bounce" style={{animationDelay: '150ms'}}></div>
                            <div className="w-2 h-2 rounded-full bg-emerald-500 animate-bounce" style={{animationDelay: '300ms'}}></div>
                        </div>
                    </div>
                </div>
            )}

            {step === AppState.UPLOAD && (
                <div className="flex-1 overflow-y-auto px-8 py-12">
                     <div className="max-w-4xl mx-auto flex flex-col items-center">
                        <div className="text-center mb-16">
                            <h2 className="text-5xl font-black text-slate-900 mb-6 tracking-tight">Catalog to <span className="text-emerald-600">Storefront.</span></h2>
                            <p className="text-slate-500 text-xl font-medium max-w-2xl mx-auto leading-relaxed">Automated world-class asset synthesis for industrial inventories. Deep-linked high-resolution photos for every SKU.</p>
                        </div>
                        <div className="w-full shadow-2xl rounded-[2.5rem] bg-white border border-slate-100 p-2">
                            <FileUpload 
                                onFileSelect={handleFileSelect} 
                                onManualEntry={handleManualEntry}
                                isProcessing={isProcessing} 
                            />
                        </div>
                     </div>
                </div>
            )}

            {step === AppState.MAPPING && (
                 <div className="flex-1 p-8 overflow-hidden bg-slate-50">
                    <div className="h-full max-w-screen-2xl mx-auto shadow-2xl rounded-3xl overflow-hidden bg-white border border-slate-100">
                        <MappingStep 
                            sourceHeaders={sourceHeaders} 
                            sourceData={sourceData}
                            onConfirm={handleMappingConfirm}
                            logs={logs}
                            onBack={handleReset}
                        />
                    </div>
                </div>
            )}

            {step === AppState.PREVIEW && (
                <div className="flex-1 p-8 overflow-hidden bg-slate-50">
                    <div className="h-full max-w-screen-2xl mx-auto shadow-2xl rounded-3xl overflow-hidden bg-white border border-slate-100">
                        <PreviewStep data={processedData} onDataUpdate={setProcessedData} onReset={handleReset} />
                    </div>
                </div>
            )}
      </main>
    </div>
  );
};

