    - Sections: 'Product Overview', 'Key Performance Features', 'Detailed Technical Specifications', and 'What\'s in the Box'.

    TASK 3: ADVANCED IMAGE RECOVERY (FALLBACK SCRAPING)
    - You MUST find 10 high-resolution, PERMANENT direct image URLs.
    - STRATEGY: 
      1. First check official manufacturer media assets.
      2. FALLBACK: Scrape product pages for <img> tags. Look for 'src' or 'data-src' attributes that end in .jpg, .png, or .webp. 
      3. TARGET DIRECTORIES: Prioritize URLs containing '/media/', '/images/products/', '/assets/', or '/original/'.
      4. QUALITY CONTROL: Prioritize larger dimensions (1000px+). STRICTLY AVOID thumbnails, small icons, or 100x100 previews.
    - FORBIDDEN: DO NOT return gstatic.com, encrypted-tbn, search-thumbnail, or links containing 'logo'. URLs must lead to permanent static files.

    TASK 4: PRICING & DATA
    - Identify current MSRP in CAD.
    - Ensure title is professional (Brand + SKU + Product Name).

    Output format: STRICT VALID JSON ONLY
    {
      "title": "Authoritative Product Title",
      "price": "249.99",
      "body_html": "<div class='premium-listing'>...Structured HTML...</div>",
      "images": ["direct_high_res_url_1", "direct_high_res_url_2", ..., "direct_high_res_url_10"]
    }`;

    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview', 
        contents: prompt,
        config: { 
            tools: [{googleSearch: {}}],
            thinkingConfig: { thinkingBudget: 0 }
        }
    });

    try {
        const text = response.text || '';
        const jsonStr = text.match(/\{[\s\S]*\}/)?.[0] || '{}';
        const data = JSON.parse(jsonStr);

        const validImages = (data.images || []).map(cleanImageUrl).filter((u: string) => u);
        const handle = (data.title || `${brand}-${sku}`).toLowerCase().replace(/[^a-z0-9]+/g, '-');

        const mainRow: ProductRow = {
            'Handle': handle,
            'Title': data.title || `${brand} ${sku}`,
            'Body (HTML)': data.body_html || '',
            'Vendor': normalizeVendor(brand),
            'Option1 Name': 'Title',
            'Option1 Value': 'Default Title',
            'Variant SKU': sku,
            'Variant Price': data.price || '',
            'Image Src': validImages[0] || '',
            'Image Position': 1,
            'Status': 'draft'
        };

        const extraRows = Array.from(new Set(validImages.slice(1))).map((img: string, i: number) => ({
            'Handle': handle,
            'Image Src': img,
            'Image Position': i + 2,
            'Image Alt Text': mainRow['Title']
        }));

        return [mainRow, ...extraRows];
    } catch (e) {
        return [{
            'Handle': `${brand}-${sku}`.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
            'Title': `${brand} ${sku}`,
            'Vendor': normalizeVendor(brand),
            'Variant SKU': sku,
            'Status': 'draft'
        }];
    }
};

export const downloadCSV = (data: ProductRow[]) => {
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Products");
  XLSX.writeFile(wb, 'shopify_import.csv');
};

