                </div>
                <div>
                    <h1 className="text-xl font-black tracking-tight text-white uppercase leading-none">Shopify Transformer</h1>
                    <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 block">Industrial Catalog Synthesis</span>
