export const normalizeVendor = (raw: string): string => {
    if (!raw) return '';
    let v = String(raw).trim().toUpperCase();
    if (v.startsWith('MILWAUKEE')) return 'MILWAUKEE';
    return v;
};

export const cleanImageUrl = (url: string): string => {
  if (!url) return '';
  let clean = url.trim().replace(/['"]/g, '').replace(/ /g, '%20');

  if (clean.startsWith('//')) clean = 'https:' + clean;
  if (!clean.startsWith('http')) {
     if (clean.includes('/') && (clean.match(/\.(jpg|jpeg|png|webp|gif)/i) || clean.includes('cdn'))) {
        clean = 'https://' + clean;
     } else {
        return '';
     }
  }

  const lower = clean.toLowerCase();

  // Filter out non-permanent or low-quality thumbnails/proxies
  if (lower.includes('gstatic.com') || 
      lower.includes('encrypted-tbn') || 
      lower.includes('googleusercontent.com') || 
      lower.includes('search_thumbnail') ||
      lower.startsWith('data:image')) {
      return '';
  }

  // Allow high-res manufacturer CDNs even if they have common "small" patterns
  const isManufacturerCDN = lower.match(/(milwaukeetool|boschtools|dewalt|makitatools|metabo|ridgid|ryobitools|stihl|husqvarna|atlas-machinery|mcmaster|grainger|homedepotstatic|amazon-adsystem|images-amazon|media-amazon)/i);

  const thumbPatterns = ['/thumb/', '_thumb', '/small/', '/icon/', '/tiny/', '100x100', '50x50', 'icon-', 'SL100', 'SL50'];
  if (!isManufacturerCDN && thumbPatterns.some(p => lower.includes(p)) && !lower.includes('original') && !lower.includes('1000x1000') && !lower.includes('1500x1500')) {
    return '';
  }

  const junkPatterns = [
    'favicon', 'banner', 'spacer', 'pixel', 'loading', 'missing', 
    'placeholder', 'no-image', 'noimage', 'swatch', 'badge', 'facebook', 'twitter', 
    'instagram', 'youtube', 'linkedin', 'cart', 'header', 'footer', 'button'
  ];

  if (junkPatterns.some(p => lower.includes(p))) {
      // Check if it's a false positive junk match (e.g. 'button' in a product name within URL)
      // Only filter if it REALLY looks like a UI asset
      const isActuallyProduct = lower.includes('productimages') || lower.includes('media/') || lower.includes('images/') || lower.includes('assets/products/') || lower.includes('p-detail');
      if (!isActuallyProduct) return '';
  }

  // Relaxed CDN validation - if it looks like an image, trust it more
  const validCdn = lower.match(/(edgenet|widen|cloudinary|scene7|cdn|azureedge|cloudfront|amazon|shopify|bigcommerce|akamai|fastly|milwaukeetool|bosch|dewalt|mcmaster|grainger|homedepotstatic|atlas-machinery|ruralking|tractorsupply|lowes|walmart|mscdirect|fastenal|zoro|images-amazon|media-amazon|boschtools|dewalt.com|graingerstatic|mcmasterstatic|factorypure|globalindustrial|mscdirect|supplyhouse|rockler|woodcraft|tool|equipment|hardware)/i);
  const validExt = lower.match(/\.(jpg|jpeg|png|webp|bmp|tiff|avif)(\?|$)/i);

  if (!validCdn && !validExt) return '';

  return clean;
};

export const createProductFromSku = async (brand: string, sku: string, apiKey: string): Promise<ProductRow[]> => {
    const ai = new GoogleGenAI({ apiKey });

    const prompt = `Act as an elite world-class industrial product data architect and lead SEO strategist for a premier Canadian power tool dealership. 
    Your mission: Synthesize the absolute highest quality product data for: "${brand} ${sku}".

    1. CANADIAN MARKET INTELLIGENCE:
    - Research exact current pricing (MSRP) from top-tier Canadian competitors: Atlas Tools and Machinery (atlas-machinery.com), Federated Tool (federatedtool.com), BC Fasteners (bcfasteners.com), and Amazon.ca.
    - Resulting price MUST be in CAD (Canadian Dollars).

    2. DEEP INDUSTRIAL METADATA (MANDATORY):
    - Identify the official GTIN/UPC Barcode.
    - Identify exact Product Weight in Grams (convert from lbs if necessary).
    - Determine accurate Country of Origin (2-letter ISO code) and 10-digit HS Tariff Code (e.g., 8467.21.00.10 for drills).
    - Accurate Google Product Category.

    3. WORLD-CLASS CONTENT ARCHITECTURE (HTML):
    - Tone: Authoritative, Technical, Professional.
    - Structure the Product Page exactly like a mix of Acme Tools and the official brand page, but better.
    - SECTIONS REQUIRED:
        - **Product Overview**: 2 high-impact sentences describing the primary use case and core innovation.
        - **Performance Features**: A clean <ul> list with 6-8 distinct performance advantages (e.g., motor tech, ergonomics, durability).
        - **Technical Specifications**: A formatted HTML <table> containing clear keys and values for Power Source, Motor Type, RPM, Torque, Length, Weight, etc.
        - **What's Included**: A specific, comprehensive list of every item inside the box (Chargers, Batteries, Cases, Bits, etc.).
    - Style: Use semantic HTML (<h3>, <p>, <ul>, <li>, <table>). No messy inline CSS.

    4. SEO DOMINANCE:
    - SEO Meta Title: "Brand SKU Product Name | Primary Key Feature - Shop Online Canada"
    - SEO Meta Description: Professional, benefit-driven 155-160 character snippet.
    - Tags: Brand, Product Class, Series, Battery System, Voltage, Kit vs Bare Tool, etc.

    5. HIGH-RESOLUTION ASSET RECOVERY:
    - Provide up to 10 direct, high-resolution image URLs. 
    - PRIORITY: milwaukeetool.com/media/..., boschtools.com/assets/..., dewalt.com/media/...
    - MUST: Exclude all thumbnails and temporary search links.
    - IMPORTANT: Return ALL valid image URLs found in the 'images' array so we can build a recovery list.

    OUTPUT: Return ONLY valid JSON.
    {
      "title": "Clean Professional Product Name",
      "price_cad": "999.99",
      "body_html": "...",
      "barcode": "...",
      "weight_grams": "...",
      "tags": "...",
      "country_of_origin": "...",
      "hs_code": "...",
      "google_category": "...",
      "seo_title": "...",
      "seo_description": "...",
      "included_in_box": ["Item 1", "Item 2", ...],
      "images": ["url1", "url2", ...]
    }`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview', 
            contents: { parts: [{ text: prompt }] },
            config: { 
                tools: [{googleSearch: {}}],
                thinkingConfig: { thinkingBudget: 0 }
            }
        });

        const text = response.text || '';
        const jsonStr = text.match(/\{[\s\S]*\}/)?.[0] || '{}';
        const data = JSON.parse(jsonStr);

        const rawImages = (data.images || []);
        const validImages = rawImages.map(cleanImageUrl).filter((u: string) => u);
        const handle = (data.title || `${brand}-${sku}`).toLowerCase().replace(/[^a-z0-9]+/g, '-');

        // Filter out base64 strings from raw recovery list. 
        // INCREASED LENGTH LIMIT to 3000 to allow for long signed CDN URLs (common in industrial parts).
        const safeRawAssets = rawImages.filter((u: string) => u && !u.startsWith('data:image') && u.length < 3000);

        const mainRow: ProductRow = {
            'Handle': handle,
            'Title': data.title || `${brand} ${sku}`,
            'Body (HTML)': data.body_html || '',
            'Vendor': normalizeVendor(brand),
            'Tags': data.tags || '',
            'Variant SKU': sku,
            'Variant Price': data.price_cad || '',
            'Variant Barcode': data.barcode || '',
            'Variant Grams': data.weight_grams || '',
            'Variant Weight Unit': 'g',
            'Variant HS Code': data.hs_code || '',
            'Variant Country of Origin': data.country_of_origin || '',
            'SEO Title': data.seo_title || '',
            'SEO Description': data.seo_description || '',
            'Google Product Category': data.google_category || '',
            'Included In Box': (data.included_in_box || []).join(', '),
            'Image Src': validImages[0] || '',
            'Image Position': 1,
            'Status': 'draft',
            'Published': 'TRUE',
            'Option1 Name': 'Title',
            'Option1 Value': 'Default Title',
            'Variant Inventory Tracker': 'shopify',
            'Variant Inventory Policy': 'deny',
            'Variant Fulfillment Service': 'manual',
            'Variant Requires Shipping': 'TRUE',
            'Variant Taxable': 'TRUE',
            'Gift Card': 'FALSE',
            '_Raw_Assets': safeRawAssets.join(' | ') // Store cleaned raw links for recovery panel
        };

        const extraRows = Array.from(new Set(validImages.slice(1))).map((img: string, i: number) => ({
            'Handle': handle,
            'Image Src': img,
            'Image Position': i + 2,
            'Image Alt Text': mainRow['Title']
        }));

        return [mainRow, ...extraRows];
    } catch (e) {
        console.error("AI Research Error:", e);
        return [{
            'Handle': `${brand}-${sku}`.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
            'Title': `${brand} ${sku}`,
            'Vendor': normalizeVendor(brand),
            'Variant SKU': sku,
            'Status': 'draft'
        }];
    }
};

export const downloadCSV = (data: ProductRow[]) => {
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Products");
  XLSX.writeFile(wb, 'shopify_import_canada.csv');
};

export const parseExcel = async (file: File): Promise<{ headers: string[], data: ProductRow[], logs: string[] }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const data = e.target?.result;
            const workbook = XLSX.read(data, { type: 'binary' });
            const firstSheet = workbook.SheetNames[0];
            const json = XLSX.utils.sheet_to_json<ProductRow>(workbook.Sheets[firstSheet], { defval: "" });
            const headers = Object.keys(json[0] || {});
            resolve({ headers, data: json, logs: [`Imported ${json.length} rows from ${firstSheet}`] });
        };
        reader.readAsBinaryString(file);
    });
};

export const generateShopifyData = (sourceData: ProductRow[], mapping: Mapping): ProductRow[] => {
    return sourceData.map(row => {
        const newRow: ProductRow = {};
        Object.entries(mapping).forEach(([shopifyField, sourceHeader]) => {
            if (sourceHeader) newRow[shopifyField] = row[sourceHeader];
        });
        if (!newRow['Handle'] && newRow['Title']) newRow['Handle'] = String(newRow['Title']).toLowerCase().replace(/[^a-z0-9]+/g, '-');
        newRow['Status'] = 'draft';
        return newRow;
    });
};

