import React, { useState } from 'react';
import { FileUpload } from './components/FileUpload';
import { MappingStep } from './components/MappingStep';
import { PreviewStep } from './components/PreviewStep';
import { parseExcel, generateShopifyData, createProductFromSku } from './services/excelService';
import { AppState, Mapping, ProductRow } from './types';

const App: React.FC = () => {
  const [step, setStep] = useState<AppState>(AppState.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progressMessage, setProgressMessage] = useState('');
  const [sourceHeaders, setSourceHeaders] = useState<string[]>([]);
  const [sourceData, setSourceData] = useState<ProductRow[]>([]);
  const [processedData, setProcessedData] = useState<ProductRow[]>([]);
  const [logs, setLogs] = useState<string[]>([]);

  const handleFileSelect = async (file: File) => {
    setIsProcessing(true);
    setProgressMessage('Analyzing catalog architecture...');
    setTimeout(async () => {
        try {
            const { headers, data, logs: processingLogs } = await parseExcel(file);
            setSourceHeaders(headers);
            setSourceData(data);
            setLogs(processingLogs);
            setStep(AppState.MAPPING);
        } catch (error) {
            console.error(error);
            alert("Error parsing file.");
        } finally {
            setIsProcessing(false);
            setProgressMessage('');
        }
    }, 100);
  };

  const handleManualEntry = async (brand: string, skuInput: string) => {
      const apiKey = process.env.API_KEY;
      if (!apiKey) { alert("API Key environment variable is missing."); return; }

      setIsProcessing(true);
      const skus = skuInput.split(/[\n,]+/).map(s => s.trim()).filter(s => s);
      if (skus.length === 0) { setIsProcessing(false); return; }

      const allData: ProductRow[] = [];
      try {
          for (let i = 0; i < skus.length; i++) {
              const currentSku = skus[i];
              setProgressMessage(`Researching Market (${i + 1}/${skus.length}): ${brand} ${currentSku}...`);

              // Ensure we wait for the AI result
              try {
                  const rows = await createProductFromSku(brand, currentSku, apiKey);
                  if (rows && rows.length > 0) {
                      allData.push(...rows);
                  }
              } catch (err) {
                  console.error(`Research failed for SKU ${currentSku}:`, err);
                  allData.push({
                      'Handle': `${brand}-${currentSku}`.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
                      'Title': `${brand} ${currentSku}`,
                      'Vendor': brand,
                      'Variant SKU': currentSku,
                      'Status': 'draft'
                  });
              }

              // Breathing room for UI and API
              if (skus.length > 1 && i < skus.length - 1) {
                await new Promise(r => setTimeout(r, 800));
              }
          }

          if (allData.length === 0) {
            alert("Unable to generate product data. Please check your SKU and Brand.");
            return;
          }

          setProcessedData(allData);
          setStep(AppState.PREVIEW);
      } catch (error: any) { 
          alert(`Synthesis interrupted: ${error.message}`); 
      } finally { 
          setIsProcessing(false); 
          setProgressMessage('');
      }
  };

  const handleMappingConfirm = async (mapping: Mapping) => {
    const rawShopifyData = generateShopifyData(sourceData, mapping);
    const apiKey = process.env.API_KEY;

    if (apiKey) {
        setIsProcessing(true);
        setProgressMessage('Initiating Automated Deep Research...');

        const handlesToEnrich = Array.from(new Set(rawShopifyData.filter(r => !r['Image Src'] || r['Image Src'].includes('placehold.co') || !r['Body (HTML)']).map(r => r['Handle'])));
        let workingData = [...rawShopifyData];

        if (handlesToEnrich.length > 0) {
            const enrichmentBatch = handlesToEnrich.slice(0, 50); 
            for (let i = 0; i < enrichmentBatch.length; i++) {
                const handle = enrichmentBatch[i];
                const baseRow = workingData.find(r => r['Handle'] === handle && r['Title']);
                if (!baseRow) continue;

                setProgressMessage(`Asset Mining: ${baseRow['Title']} (${i + 1}/${enrichmentBatch.length})...`);

                try {
                    const brand = baseRow['Vendor'] || '';
                    const sku = baseRow['Variant SKU'] || '';
                    const rows = await createProductFromSku(brand, sku, apiKey);

                    if (rows.length > 0) {
                        const others = workingData.filter(r => r['Handle'] !== handle);
                        const enrichedMain = { 
                            ...baseRow, 
                            'Image Src': rows[0]['Image Src'] || baseRow['Image Src'],
                            'Body (HTML)': rows[0]['Body (HTML)'] || baseRow['Body (HTML)'],
                            'Variant Price': rows[0]['Variant Price'] || baseRow['Variant Price'],
                            'Title': rows[0]['Title'] || baseRow['Title']
                        };
                        const enrichedExtras = rows.slice(1);
                        workingData = [...others, enrichedMain, ...enrichedExtras];
                    }
                } catch (err) { console.error("Synthesis failed for " + handle, err); }

                await new Promise(r => setTimeout(r, 2000)); 
            }
        }
        setProcessedData(workingData);
        setIsProcessing(false);
    } else {
        setProcessedData(rawShopifyData);
    }

    setStep(AppState.PREVIEW);
  };

  const handleReset = () => {
      setStep(AppState.UPLOAD);
      setSourceData([]);
      setProcessedData([]);
  };

  return (
    <div className="h-full flex flex-col bg-slate-50 text-slate-900 overflow-hidden font-sans">
      <header className="bg-slate-900 text-white shadow-2xl z-50 sticky top-0 border-b border-white/5 flex-none">
        <div className="max-w-screen-2xl mx-auto px-8 py-5 flex items-center justify-between">
            <div className="flex items-center space-x-5">
                <div className="bg-emerald-500 p-2.5 rounded-xl shadow-lg shadow-emerald-500/20">
                    <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012-2v2M7 7h10" /></svg>
                </div>
                <div>
                    <h1 className="text-xl font-black tracking-tight text-white uppercase leading-none">Shopify Transformer</h1>
                    <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 block">Industrial Catalog Synthesis</span>
                </div>
            </div>

            <div className="flex items-center space-x-6">
                 {step !== AppState.UPLOAD && (
                     <button onClick={handleReset} className="text-xs font-bold text-slate-400 hover:text-white transition-all uppercase tracking-widest">
                        ← Restart
                     </button>
                 )}
                <div className="flex items-center space-x-2 bg-slate-800 px-4 py-2 rounded-full border border-slate-700">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Gemini 3 Pro • Deep Search</span>
                </div>
            </div>
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative flex flex-col min-h-0">
            {isProcessing && (
                <div className="absolute inset-0 z-[100] bg-slate-900/60 backdrop-blur-md flex flex-col items-center justify-center p-8">
                    <div className="w-full max-w-md bg-white p-12 rounded-[3rem] shadow-2xl text-center animate-in fade-in zoom-in duration-300">
                        <div className="w-24 h-24 bg-emerald-100 rounded-full mx-auto flex items-center justify-center mb-8 shadow-inner overflow-hidden relative">
