  'bullet_point5', 'bullet_point6', 'bullet_point7',
  'image_1', 'image_2', 'image_3', 'image_4', 'image_5', 'image_6', 'image_7', 'image_8',
  'quantity', 'price', 'cost', 'compare_at_price',
  'variation_value_1', 'variation_value_2', 'variation_value_3',
  'inventory_policy', 'barcode', 'requires_shipping', 'delivery_profile_id', 'taxable',
