export const downloadCSV = (data: ProductRow[]) => {
  // 1. Group data by Handle to merge images
  const groupedData: Record<string, ProductRow[]> = {};
  data.forEach(row => {
      const handle = row['Handle'];
      if (!handle) return;
      if (!groupedData[handle]) groupedData[handle] = [];
      groupedData[handle].push(row);
  });

  // 2. Transform to ListingMirror format
  const transformedRows: any[][] = [];

  Object.values(groupedData).forEach(group => {
      const main = group.find(r => r['Title']) || group[0];

      // Collect all valid images from all rows in this group
      const images: string[] = [];
      group.forEach(r => {
          if (r['Image Src'] && !r['Image Src'].includes('placehold.co')) {
              images.push(r['Image Src']);
          }
      });
      // De-duplicate images and limit to 8
      const uniqueImages = Array.from(new Set(images)).slice(0, 8); 
      while (uniqueImages.length < 8) uniqueImages.push(''); // Fill empty slots for fixed column count

      const weightUnit = main['Variant Weight Unit'] === 'g' ? 'Grams' : (main['Variant Weight Unit'] || 'Grams');

      const varName1 = '';
      const varValue1 = '';

      const rowData = [
          main['Variant SKU'] || '', // sku
          main['Title'] || '', // title
          main['Body (HTML)'] || '', // description
          main['Handle'] || '', // handle
          main['Vendor'] || '', // vendor
          main['Google Product Category'] || 'Hardware', // product_type
          '', // template_suffix
          'web', // published_scope
          main['Tags'] || '', // tags
          varName1, // variation_name_1 (Empty)
          '', // variation_name_2
          '', // variation_name_3
          '', // publish_date
          '', '', '', '', '', '', '', // bullet_points 1-7
          uniqueImages[0], // image_1
          uniqueImages[1], // image_2
          uniqueImages[2], // image_3
          uniqueImages[3], // image_4
          uniqueImages[4], // image_5
          uniqueImages[5], // image_6
          uniqueImages[6], // image_7
          uniqueImages[7], // image_8
          main['Variant Inventory Qty'] || '0', // quantity
          main['Variant Price'] || '', // price
          '', // cost
          '', // compare_at_price
          varValue1, // variation_value_1 (Empty)
          '', // variation_value_2
          '', // variation_value_3
          'Deny', // inventory_policy
          main['Variant Barcode'] || '', // barcode
          'T', // requires_shipping
          '', // delivery_profile_id
          'T', // taxable
          main['Variant Grams'] || '', // shipping_weight
          weightUnit, // shipping_weight_unit_of_measure
          '', // max_quantity
          main['Variant HS Code'] || '', // harmonized_system_code
          main['Variant Country of Origin'] || '' // country_code_of_origin
      ];
      transformedRows.push(rowData);
  });

  // 3. Construct Sheet 1 (AddListings)
  const row1 = new Array(LISTING_MIRROR_HEADERS.length).fill('');
  row1[1] = 'Shopify';

  const row2 = new Array(LISTING_MIRROR_HEADERS.length).fill('');
  row2[1] = 'Wise Line Tools';
  row2[9] = 'Variation Fields'; 

  const row3 = LISTING_MIRROR_HEADERS;

  const sheet1Data = [row1, row2, row3, ...transformedRows];
  const ws1 = XLSX.utils.aoa_to_sheet(sheet1Data);

  // Set default column width for better readability
  const wscols = LISTING_MIRROR_HEADERS.map(() => ({ wch: 20 }));
  ws1['!cols'] = wscols;

  // Apply Styling: Font Size 11 for all, Bold for Rows 1, 2, 3
  const range = XLSX.utils.decode_range(ws1['!ref'] || "A1:A1");
  for (let R = range.s.r; R <= range.e.r; ++R) {
      for (let C = range.s.c; C <= range.e.c; ++C) {
          const cellRef = XLSX.utils.encode_cell({ c: C, r: R });
          if (!ws1[cellRef]) continue;

          if (!ws1[cellRef].s) ws1[cellRef].s = {};
          if (!ws1[cellRef].s.font) ws1[cellRef].s.font = {};

          // Global: Font Size 11, Calibri
          ws1[cellRef].s.font.sz = 11;
          ws1[cellRef].s.font.name = "Calibri";

          // Header Rows: 0, 1, 2 (Indices) -> Bold
          if (R <= 2) {
              ws1[cellRef].s.font.bold = true;
          }

          // Yellow Highlights for Listing Mirror mandated fields in Header Row (Row Index 2)
          if (R === 2) {
              const headerVal = String(ws1[cellRef].v || '');
              if (['quantity', 'inventory_policy', 'requires_shipping', 'taxable'].includes(headerVal)) {
                  if (!ws1[cellRef].s.fill) ws1[cellRef].s.fill = {};
                  ws1[cellRef].s.fill.fgColor = { rgb: "FFFF00" };
              }
          }
      }
  }

  // 4. Construct Sheet 2 (Lookup)
  const lookupData = [
      ["AddListings", "16400", "", "", ""],
      ["inventory_policy", "Continue", "Deny", "", ""],
      ["requires_shipping", "T", "F", "", ""],
      ["taxable", "T", "F", "", ""],
      ["shipping_weight_unit_of_measure", "Grams", "KiloGrams", "Ounces", "Pounds"]
  ];
  const ws2 = XLSX.utils.aoa_to_sheet(lookupData);

  // Apply Styling to Lookup sheet
  const range2 = XLSX.utils.decode_range(ws2['!ref'] || "A1:A1");
  for (let R = range2.s.r; R <= range2.e.r; ++R) {
      for (let C = range2.s.c; C <= range2.e.c; ++C) {
          const cellRef = XLSX.utils.encode_cell({ c: C, r: R });
          if (!ws2[cellRef]) continue;
          if (!ws2[cellRef].s) ws2[cellRef].s = {};
          if (!ws2[cellRef].s.font) ws2[cellRef].s.font = {};
          ws2[cellRef].s.font.sz = 11;
          ws2[cellRef].s.font.name = "Calibri";
      }
  }

  // 5. Build Workbook
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws1, "AddListings");
  XLSX.utils.book_append_sheet(wb, ws2, "Lookup");

  // 6. Export with cellStyles option enabled
  XLSX.writeFile(wb, 'ListingMirror_Import.xlsx', { cellStyles: true });
};

export const parseExcel = async (file: File): Promise<{ headers: string[], data: ProductRow[], logs: string[] }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const data = e.target?.result;
            const workbook = XLSX.read(data, { type: 'binary' });
            const firstSheet = workbook.SheetNames[0];
            const json = XLSX.utils.sheet_to_json(workbook.Sheets[firstSheet], { defval: "" }) as ProductRow[];
            const headers = Object.keys(json[0] || {});
            resolve({ headers, data: json, logs: [`Imported ${json.length} rows from ${firstSheet}`] });
        };
        reader.readAsBinaryString(file);
    });
};

export const generateShopifyData = (sourceData: ProductRow[], mapping: Mapping): ProductRow[] => {
    return sourceData.map(row => {
        const newRow: ProductRow = {};
        Object.entries(mapping).forEach(([shopifyField, sourceHeader]) => {
            if (sourceHeader) newRow[shopifyField] = row[sourceHeader];
        });
        if (!newRow['Handle'] && newRow['Title']) {
            newRow['Handle'] = String(newRow['Title'])
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, '-')
                .replace(/^-+|-+$/g, '');
        }
        newRow['Status'] = 'draft';
        return newRow;
    });
};

