export const downloadCSV = (data: ProductRow[]) => {
  // 1. Group data by Handle to merge images
  const groupedData: Record<string, ProductRow[]> = {};
  data.forEach(row => {
      const handle = row['Handle'];
      if (!handle) return;
      if (!groupedData[handle]) groupedData[handle] = [];
      groupedData[handle].push(row);
  });

  // 2. Transform to ListingMirror format for Sheet 1
  const transformedRows: any[][] = [];

  Object.values(groupedData).forEach(group => {
      const main = group.find(r => r['Title']) || group[0];

      // Collect all valid images from all rows in this group
      const images: string[] = [];
      group.forEach(r => {
          if (r['Image Src'] && !r['Image Src'].includes('placehold.co')) {
              images.push(r['Image Src']);
          }
      });
      // De-duplicate images and limit to 8
      const uniqueImages = Array.from(new Set(images)).slice(0, 8); 
      while (uniqueImages.length < 8) uniqueImages.push(''); // Fill empty slots for fixed column count

      const weightUnit = main['Variant Weight Unit'] === 'g' ? 'Grams' : (main['Variant Weight Unit'] || 'Grams');

      const varName1 = '';
      const varValue1 = '';

      const rowData = [
          main['Variant SKU'] || '', // sku
          main['Title'] || '', // title
          main['Body (HTML)'] || '', // description
          main['Handle'] || '', // handle
          main['Vendor'] || '', // vendor
          main['Google Product Category'] || 'Hardware', // product_type
          '', // template_suffix
          'web', // published_scope
          main['Tags'] || '', // tags
          varName1, // variation_name_1 (Empty)
          '', // variation_name_2
          '', // variation_name_3
          '', // publish_date
          '', '', '', '', '', '', '', // bullet_points 1-7
          uniqueImages[0], // image_1
          uniqueImages[1], // image_2
          uniqueImages[2], // image_3
          uniqueImages[3], // image_4
          uniqueImages[4], // image_5
          uniqueImages[5], // image_6
          uniqueImages[6], // image_7
          uniqueImages[7], // image_8
          main['Variant Inventory Qty'] || '0', // quantity
          main['Variant Price'] || '', // price
          '', // cost
          '', // compare_at_price
          varValue1, // variation_value_1 (Empty)
          '', // variation_value_2
          '', // variation_value_3
          'Deny', // inventory_policy
          main['Variant Barcode'] || '', // barcode
          'T', // requires_shipping
          '', // delivery_profile_id
          'T', // taxable
          main['Variant Grams'] || '', // shipping_weight
          weightUnit, // shipping_weight_unit_of_measure
          '', // max_quantity
          main['Variant HS Code'] || '', // harmonized_system_code
          main['Variant Country of Origin'] || '' // country_code_of_origin
      ];
      transformedRows.push(rowData);
  });

  // 3. Construct Sheet 1 (AddProduct)
  const row1 = new Array(LISTING_MIRROR_HEADERS.length).fill('');
  row1[1] = 'Shopify';

  const row2 = new Array(LISTING_MIRROR_HEADERS.length).fill('');
  row2[1] = 'Wise Line Tools';
  row2[9] = 'Variation Fields'; 

  const row3 = LISTING_MIRROR_HEADERS;

  const sheet1Data = [row1, row2, row3, ...transformedRows];
  const ws1 = XLSX.utils.aoa_to_sheet(sheet1Data);

  // Set default column width for better readability
  const wscols = LISTING_MIRROR_HEADERS.map(() => ({ wch: 20 }));
  ws1['!cols'] = wscols;

  // Apply Styling to Sheet 1
  const range = XLSX.utils.decode_range(ws1['!ref'] || "A1:A1");
  for (let R = range.s.r; R <= range.e.r; ++R) {
      for (let C = range.s.c; C <= range.e.c; ++C) {
          const cellRef = XLSX.utils.encode_cell({ c: C, r: R });
          if (!ws1[cellRef]) continue;

          // Define a clean base style object
          const style: any = {
              font: { name: "Calibri", sz: 11 },
              alignment: { vertical: "center" }
          };

          // Logic for Header Rows (0, 1, 2)
          if (R <= 2) {
             style.font.bold = true;
             style.alignment.horizontal = "center";
          }

          // Specific Yellow Highlights (Row 2 only - headers row)
          if (R === 2) {
              const val = String(ws1[cellRef].v || ''); 
              // Matches: quantity, inventory_policy, requires_shipping, taxable
              if (['quantity', 'inventory_policy', 'requires_shipping', 'taxable'].includes(val)) {
                  style.fill = {
                      patternType: "solid",
                      fgColor: { rgb: "FFFF00" } // Standard Yellow
                  };
              }
          }

          ws1[cellRef].s = style;
      }
  }

  // 4. Construct Sheet 2 (Lookup)
  const ws2 = XLSX.utils.aoa_to_sheet(LOOKUP_DATA);
  const range2 = XLSX.utils.decode_range(ws2['!ref'] || "A1:A1");
  for (let R = range2.s.r; R <= range2.e.r; ++R) {
      for (let C = range2.s.c; C <= range2.e.c; ++C) {
          const cellRef = XLSX.utils.encode_cell({ c: C, r: R });
          if (!ws2[cellRef]) continue;
          if (!ws2[cellRef].s) ws2[cellRef].s = {};
          ws2[cellRef].s.font = { name: "Calibri", sz: 11 };
          if(R === 0) ws2[cellRef].s.font.bold = true; // First row bold
      }
  }

  // 5. Construct Sheet 3 (Actions)
  const ws3 = XLSX.utils.aoa_to_sheet(MARKETPLACE_MAPPING_DATA);
  const range3 = XLSX.utils.decode_range(ws3['!ref'] || "A1:A1");
  for (let R = range3.s.r; R <= range3.e.r; ++R) {
      for (let C = range3.s.c; C <= range3.e.c; ++C) {
          const cellRef = XLSX.utils.encode_cell({ c: C, r: R });
          if (!ws3[cellRef]) continue;
          if (!ws3[cellRef].s) ws3[cellRef].s = {};
          ws3[cellRef].s.font = { name: "Calibri", sz: 11 };
          if(R < 2) ws3[cellRef].s.font.bold = true; // Header rows bold
      }
  }

  // 6. Build Workbook
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws1, "AddProduct");
  XLSX.utils.book_append_sheet(wb, ws2, "Lookup");
  XLSX.utils.book_append_sheet(wb, ws3, "Actions");

  // 7. Export with cellStyles option enabled
  XLSX.writeFile(wb, 'ListingMirror_Import.xlsx', { cellStyles: true });
};

export const parseExcel = async (file: File): Promise<{ headers: string[], data: ProductRow[], logs: string[] }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const data = e.target?.result;
            const workbook = XLSX.read(data, { type: 'binary' });
            const firstSheet = workbook.SheetNames[0];
            const json = XLSX.utils.sheet_to_json(workbook.Sheets[firstSheet], { defval: "" }) as ProductRow[];
            const headers = Object.keys(json[0] || {});
            resolve({ headers, data: json, logs: [`Imported ${json.length} rows from ${firstSheet}`] });
        };
        reader.readAsBinaryString(file);
    });
};

export const generateShopifyData = (sourceData: ProductRow[], mapping: Mapping): ProductRow[] => {
    return sourceData.map(row => {
        const newRow: ProductRow = {};
        Object.entries(mapping).forEach(([shopifyField, sourceHeader]) => {
            if (sourceHeader) newRow[shopifyField] = row[sourceHeader];
        });
        if (!newRow['Handle'] && newRow['Title']) {
            newRow['Handle'] = String(newRow['Title'])
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, '-')
                .replace(/^-+|-+$/g, '');
        }
        newRow['Status'] = 'draft';
        return newRow;
    });
};

import * as XLSX_PKG from 'xlsx';
import { ProductRow, Mapping } from '../types';
import { GoogleGenAI } from "@google/genai";

// Handle ESM import variations for xlsx-js-style
// @ts-ignore
const XLSX = XLSX_PKG.default || XLSX_PKG;

// --- CONSTANTS ---
export const normalizeVendor = (raw: string): string => {
    if (!raw) return '';
    let v = String(raw).trim().toUpperCase();
    if (v.startsWith('MILWAUKEE')) return 'MILWAUKEE';
    return v;
};

export const cleanImageUrl = (url: any): string => {
  if (!url || typeof url !== 'string') return '';
  let clean = url.trim().replace(/['"]/g, '').replace(/ /g, '%20');

  if (clean.startsWith('//')) clean = 'https:' + clean;
  if (!clean.startsWith('http')) {
     if (clean.includes('/') && (clean.match(/\.(jpg|jpeg|png|webp|gif)/i) || clean.includes('cdn'))) {
        clean = 'https://' + clean;
     } else {
        return '';
     }
  }

  const lower = clean.toLowerCase();

  // Filter out non-permanent or low-quality thumbnails/proxies
  if (lower.includes('gstatic.com') || 
      lower.includes('encrypted-tbn') || 
      lower.includes('googleusercontent.com') || 
      lower.includes('search_thumbnail') ||
      lower.startsWith('data:image')) {
      return '';
  }

  // Allow high-res manufacturer CDNs even if they have common "small" patterns
  const isManufacturerCDN = lower.match(/(milwaukeetool|boschtools|dewalt|makitatools|metabo|ridgid|ryobitools|stihl|husqvarna|atlas-machinery|mcmaster|grainger|homedepotstatic|amazon-adsystem|images-amazon|media-amazon)/i);

  const thumbPatterns = ['/thumb/', '_thumb', '/small/', '/icon/', '/tiny/', '100x100', '50x50', 'icon-', 'SL100', 'SL50'];
  if (!isManufacturerCDN && thumbPatterns.some(p => lower.includes(p)) && !lower.includes('original') && !lower.includes('1000x1000') && !lower.includes('1500x1500')) {
    return '';
  }

  const junkPatterns = [
    'favicon', 'banner', 'spacer', 'pixel', 'loading', 'missing', 
    'placeholder', 'no-image', 'noimage', 'swatch', 'badge', 'facebook', 'twitter', 
    'instagram', 'youtube', 'linkedin', 'cart', 'header', 'footer', 'button'
  ];

  if (junkPatterns.some(p => lower.includes(p))) {
      // Check if it's a false positive junk match (e.g. 'button' in a product name within URL)
      // Only filter if it REALLY looks like a UI asset
      const isActuallyProduct = lower.includes('productimages') || lower.includes('media/') || lower.includes('images/') || lower.includes('assets/products/') || lower.includes('p-detail');
      if (!isActuallyProduct) return '';
  }

  // Relaxed CDN validation - if it looks like an image, trust it more
  const validCdn = lower.match(/(edgenet|widen|cloudinary|scene7|cdn|azureedge|cloudfront|amazon|shopify|bigcommerce|akamai|fastly|milwaukeetool|bosch|dewalt|mcmaster|grainger|homedepotstatic|atlas-machinery|ruralking|tractorsupply|lowes|walmart|mscdirect|fastenal|zoro|images-amazon|media-amazon|boschtools|dewalt.com|graingerstatic|mcmasterstatic|factorypure|globalindustrial|mscdirect|supplyhouse|rockler|woodcraft|tool|equipment|hardware)/i);
  const validExt = lower.match(/\.(jpg|jpeg|png|webp|bmp|tiff|avif)(\?|$)/i);

  if (!validCdn && !validExt) return '';

  return clean;
};

export const createProductFromSku = async (brand: string, sku: string, apiKey: string): Promise<ProductRow[]> => {
    // Retry configuration
    const MAX_RETRIES = 3;
    let attempt = 0;

    while (attempt < MAX_RETRIES) {
        attempt++;
        try {
            const ai = new GoogleGenAI({ apiKey });

            const prompt = `Act as an elite world-class industrial product data architect and lead SEO strategist for a premier Canadian power tool dealership. 
            Your mission: Synthesize the absolute highest quality product data for: "${brand} ${sku}".

            1. CANADIAN MARKET INTELLIGENCE:
            - Research exact current pricing (MSRP) from top-tier Canadian competitors: Atlas Tools and Machinery (atlas-machinery.com), Federated Tool (federatedtool.com), BC Fasteners (bcfasteners.com), and Amazon.ca.
            - Resulting price MUST be in CAD (Canadian Dollars).

            2. DEEP INDUSTRIAL METADATA (MANDATORY):
            - Identify the official GTIN/UPC Barcode.
            - Identify exact Product Weight in Grams (convert from lbs if necessary).
            - Determine accurate Country of Origin (2-letter ISO code) and 10-digit HS Tariff Code (e.g., 8467.21.00.10 for drills).
            - Accurate Google Product Category.

            3. WORLD-CLASS CONTENT ARCHITECTURE (HTML):
            - Tone: Authoritative, Technical, Professional.
            - Structure the Product Page exactly like a mix of Acme Tools and the official brand page, but better.
            - SECTIONS REQUIRED:
                - **Product Overview**: 2 high-impact sentences describing the primary use case and core innovation.
                - **Performance Features**: A clean <ul> list with 6-8 distinct performance advantages (e.g., motor tech, ergonomics, durability).
                - **Technical Specifications**: A formatted HTML <table> containing clear keys and values for Power Source, Motor Type, RPM, Torque, Length, Weight, etc.
                - **What's Included**: A specific, comprehensive list of every item inside the box (Chargers, Batteries, Cases, Bits, etc.).
            - Style: Use semantic HTML (<h3>, <p>, <ul>, <li>, <table>). No messy inline CSS.

            4. SEO DOMINANCE:
            - **Title Structure (CRITICAL)**: Must strictly follow this pattern: "[Brand] [SKU] [Product Name]". Example: "Milwaukee 2801-20 M18 Compact Brushless Drill". Do NOT put the SKU at the end.
            - SEO Meta Description: Professional, benefit-driven 155-160 character snippet.
            - Tags: Brand, Product Class, Series, Battery System, Voltage, Kit vs Bare Tool, etc.

            5. HIGH-RESOLUTION ASSET RECOVERY:
            - Provide the "product_page_url": The official landing page for this item on the manufacturer's site.
            - Provide "competitor_urls": A list of 2-3 product pages from major retailers (Home Depot, Atlas Machinery, Acme Tools, Federated Tool) where images might be found.
            - Provide up to 10 direct, high-resolution image URLs in "images".
            - PRIORITY: milwaukeetool.com/media/..., boschtools.com/assets/..., dewalt.com/media/...
            - MUST: Exclude all thumbnails and temporary search links.

            OUTPUT: Return ONLY valid JSON.
            {
              "title": "Brand SKU Product Name...",
              "price_cad": "999.99",
              "body_html": "...",
              "barcode": "...",
              "weight_grams": "...",
              "tags": "...",
              "country_of_origin": "...",
              "hs_code": "...",
              "google_category": "...",
              "seo_title": "...",
              "seo_description": "...",
              "included_in_box": ["Item 1", "Item 2", ...],
              "product_page_url": "https://official-site.com/product...",
              "competitor_urls": ["https://competitor1.com...", "https://competitor2.com..."],
              "images": ["url1", "url2", ...]
            }`;

            // Simplified call structure to ensure compatibility
            const response = await ai.models.generateContent({
                model: 'gemini-3-pro-preview', 
                contents: prompt,
                config: { 
                    tools: [{googleSearch: {}}],
                    // Removed thinkingConfig to rely on model defaults and prevent conflicts
                }
            });

            const text = response.text || '';
            if (!text) throw new Error("Received empty response from Gemini API");

            // Improved JSON extraction: find first { and last }
            const firstBrace = text.indexOf('{');
            const lastBrace = text.lastIndexOf('}');
            const jsonStr = (firstBrace !== -1 && lastBrace !== -1) 
                ? text.substring(firstBrace, lastBrace + 1) 
                : '{}';

            let data: any = {};
            try {
                data = JSON.parse(jsonStr);
            } catch (parseError) {
                console.warn("JSON Parse failed, attempting fallback regex match", parseError);
                 const match = text.match(/\{[\s\S]*\}/);
                 if (match) {
                     try { data = JSON.parse(match[0]); } catch(e) {}
                 }
            }

            const rawImages = (Array.isArray(data.images) ? data.images : []);
            const validImages = rawImages.map(cleanImageUrl).filter((u: string) => u);

            // Clean handle generation
            const handle = (data.title || `${brand}-${sku}`).toLowerCase()
                .replace(/[^a-z0-9]+/g, '-')
                .replace(/^-+|-+$/g, '');

            // Filter out base64 strings from raw recovery list. 
            // INCREASED LENGTH LIMIT to 3000 to allow for long signed CDN URLs (common in industrial parts).
            const safeRawAssets = rawImages.filter((u: any) => typeof u === 'string' && u && !u.startsWith('data:image') && u.length < 3000);

            // Sanitize numeric fields for CSV compatibility
            const cleanPrice = data.price_cad ? String(data.price_cad).replace(/[^0-9.]/g, '') : '';
            const cleanGrams = data.weight_grams ? String(data.weight_grams).replace(/[^0-9]/g, '') : '';

            const mainRow: ProductRow = {
                'Handle': handle,
                'Title': data.title || `${brand} ${sku}`,
                'Body (HTML)': data.body_html || '',
                'Vendor': normalizeVendor(brand),
                'Tags': data.tags || '',
                'Variant SKU': sku,
                'Variant Price': cleanPrice,
                'Variant Barcode': data.barcode || '',
                'Variant Grams': cleanGrams,
                'Variant Weight Unit': 'g',
                'Variant HS Code': data.hs_code || '',
                'Variant Country of Origin': data.country_of_origin || '',
                'SEO Title': data.seo_title || '',
                'SEO Description': data.seo_description || '',
                'Google Product Category': data.google_category || '',
                'Included In Box': (data.included_in_box || []).join(', '),
                'Image Src': validImages[0] || '',
                'Image Position': 1,
                'Status': 'draft',
                'Published': 'TRUE',
                'Option1 Name': 'Title',
                'Option1 Value': 'Default Title',
                'Variant Inventory Tracker': 'shopify',
                'Variant Inventory Policy': 'deny',
                'Variant Fulfillment Service': 'manual',
                'Variant Requires Shipping': 'TRUE',
                'Variant Taxable': 'TRUE',
                'Gift Card': 'FALSE',
                '_Raw_Assets': safeRawAssets.join(' | '),
                '_Product_Page': data.product_page_url || '',
                '_Competitor_Links': (data.competitor_urls || []).join(' | ')
            };

            const extraRows = Array.from(new Set(validImages.slice(1))).map((img: string, i: number) => ({
                'Handle': handle,
                'Image Src': img,
                'Image Position': i + 2,
                'Image Alt Text': mainRow['Title']
            }));

            return [mainRow, ...extraRows];

        } catch (e: any) {
            console.error(`AI Research Attempt ${attempt} failed:`, e);
            if (attempt === MAX_RETRIES) {
                // Return fallback on final failure
                return [{
                    'Handle': `${brand}-${sku}`.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''),
                    'Title': `${brand} ${sku}`,
                    'Vendor': normalizeVendor(brand),
                    'Variant SKU': sku,
                    'Status': 'draft'
                }];
            }
            // Exponential backoff: 2s, 4s, 8s
            await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000));
        }
    }
    return []; // Should not reach here due to return in catch block
};

