export const downloadCSV = (data: ProductRow[]) => {
  // 1. Group data by Handle to merge images
  const groupedData: Record<string, ProductRow[]> = {};
  data.forEach(row => {
      const handle = row['Handle'];
      if (!handle) return;
      if (!groupedData[handle]) groupedData[handle] = [];
      groupedData[handle].push(row);
  });

  // 2. Transform to AddListings Sheet format
  const transformedRows: any[][] = [];

  Object.values(groupedData).forEach(group => {
      const main = group.find(r => r['Title']) || group[0];

      // Collect all valid images from all rows in this group
      const images: string[] = [];
      group.forEach(r => {
          if (r['Image Src'] && !r['Image Src'].includes('placehold.co')) {
              images.push(r['Image Src']);
          }
      });
      // Deduplicate images
      const uniqueImages = Array.from(new Set(images));

      // Determine weight unit - normalize to template options (Grams, KiloGrams, Ounces, Pounds)
      // Our data usually has 'g' or 'Grams', so we default to 'Grams'
      const weightUnit = 'Grams'; 

      // Map data to the ADD_LISTINGS_HEADERS structure
      const rowData = ADD_LISTINGS_HEADERS.map(header => {
          // Handle Image Columns 1-8
          if (header.startsWith('image_')) {
              const imgIndex = parseInt(header.replace('image_', ''), 10) - 1;
              return uniqueImages[imgIndex] || '';
          }

          switch(header) {
              case 'sku': return main['Variant SKU'] || '';
              case 'title': return main['Title'] || '';
              case 'description': return main['Body (HTML)'] || '';
              case 'handle': return main['Handle'] || '';
              case 'vendor': return main['Vendor'] || '';
              case 'product_type': return main['Google Product Category'] || 'Hardware';
              case 'published_scope': return 'global';
              case 'tags': return main['Tags'] || '';
              case 'variation_name_1': return 'Title';
              case 'variation_value_1': return 'Default Title';
              case 'bullet_point1': return main['Included In Box'] || ''; // Mapping box contents to bullet 1
              case 'quantity': return main['Variant Inventory Qty'] || '0';
              case 'price': return main['Variant Price'] || '';
              case 'cost': return main['Variant Price'] || ''; // Fallback cost to price
              case 'inventory_policy': return 'Deny';
              case 'barcode': return main['Variant Barcode'] || '';
              case 'requires_shipping': return 'T';
              case 'taxable': return 'T';
              case 'shipping_weight': return main['Variant Grams'] || '';
              case 'shipping_weight_unit_of_measure': return weightUnit;
              case 'harmonized_system_code': return main['Variant HS Code'] || '';
              case 'country_code_of_origin': return main['Variant Country of Origin'] || '';
              // Optional/Empty fields in default generation
              case 'template_suffix':
              case 'variation_name_2':
              case 'variation_name_3':
              case 'publish_date':
              case 'bullet_point2':
              case 'bullet_point3':
              case 'bullet_point4':
              case 'bullet_point5':
              case 'bullet_point6':
              case 'bullet_point7':
              case 'compare_at_price':
              case 'variation_value_2':
              case 'variation_value_3':
              case 'delivery_profile_id':
              case 'max_quantity':
                  return '';
              default: return '';
          }
      });
      transformedRows.push(rowData);
  });

  // 3. Construct Sheet 1 (AddListings)
  const sheet1Data = [ADD_LISTINGS_HEADERS, ...transformedRows];
  const ws1 = XLSX.utils.aoa_to_sheet(sheet1Data);

  // Set default column width
  const wscols = ADD_LISTINGS_HEADERS.map(() => ({ wch: 18 }));
  ws1['!cols'] = wscols;

  // Apply Styling to Sheet 1
  const range = XLSX.utils.decode_range(ws1['!ref'] || "A1:A1");
  for (let R = range.s.r; R <= range.e.r; ++R) {
      for (let C = range.s.c; C <= range.e.c; ++C) {
          const cellRef = XLSX.utils.encode_cell({ c: C, r: R });
          if (!ws1[cellRef]) continue;

          const style: any = {
              font: { name: "Calibri", sz: 11 },
              alignment: { vertical: "center" }
          };

          // Header Row
          if (R === 0) {
             style.font.bold = true;
             style.alignment.horizontal = "center";
          }
          ws1[cellRef].s = style;
      }
  }

  // 4. Construct Sheet 2 (Lookup)
  const ws2 = XLSX.utils.aoa_to_sheet(LOOKUP_DATA);
  const range2 = XLSX.utils.decode_range(ws2['!ref'] || "A1:A1");
  for (let R = range2.s.r; R <= range2.e.r; ++R) {
      for (let C = range2.s.c; C <= range2.e.c; ++C) {
          const cellRef = XLSX.utils.encode_cell({ c: C, r: R });
          if (!ws2[cellRef]) continue;
          if (!ws2[cellRef].s) ws2[cellRef].s = {};
          ws2[cellRef].s.font = { name: "Calibri", sz: 11 };
          if(R === 0) ws2[cellRef].s.font.bold = true;
      }
  }

  // 5. Build Workbook
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws1, "AddListings");
  XLSX.utils.book_append_sheet(wb, ws2, "Lookup");

  // 6. Export
  XLSX.writeFile(wb, 'ListingMirror_Import.xlsx', { cellStyles: true });
};

