export const downloadCSV = (data: ProductRow[]) => {
  const groupedData: Record<string, ProductRow[]> = {};
  data.forEach(row => {
      const handle = row['Handle'];
      if (!handle) return;
      if (!groupedData[handle]) groupedData[handle] = [];
      groupedData[handle].push(row);
  });

  const transformedRows: any[][] = [];

  Object.values(groupedData).forEach(group => {
      const main = group.find(r => r['Title']) || group[0];

      // Collect all images
      const images: string[] = [];
      group.forEach(r => {
          if (r['Image Src'] && !r['Image Src'].includes('placehold.co')) {
              images.push(r['Image Src']);
          }
      });
      const uniqueImages = Array.from(new Set(images));

      // Row 1: The Main Product Row
      // Maps fields from 'main' row to SHOPIFY_HEADERS
      const row1Data = SHOPIFY_HEADERS.map(header => {
          if (header === 'Image Src') return uniqueImages[0] || '';
          if (header === 'Image Position') return uniqueImages.length > 0 ? 1 : '';

          // Specific Overrides for Main Row
          if (header === 'Option1 Name') return 'Title';
          if (header === 'Option1 Value') return 'Default Title';
          if (header === 'Published') return main['Published'] || 'true';
          if (header === 'Status') return 'active';

          // Fallback to data or empty
          return main[header] !== undefined ? main[header] : '';
      });
      transformedRows.push(row1Data);

      // Rows 2..N: Additional Images
      for (let i = 1; i < uniqueImages.length; i++) {
          const imgRowData = SHOPIFY_HEADERS.map(header => {
              if (header === 'Handle') return main['Handle'];
              if (header === 'Image Src') return uniqueImages[i];
              if (header === 'Image Position') return i + 1;
              return ''; // All other fields empty for image rows
          });
          transformedRows.push(imgRowData);
      }
  });

  const ws = XLSX.utils.aoa_to_sheet([SHOPIFY_HEADERS, ...transformedRows]);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Products");
  XLSX.writeFile(wb, 'Shopify_Import_Ready.csv', { bookType: 'csv' });
};

export const parseExcel = async (file: File): Promise<{ headers: string[], data: ProductRow[], logs: string[] }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const data = e.target?.result;
            const workbook = XLSX.read(data, { type: 'binary' });
            const firstSheet = workbook.SheetNames[0];
            const json = XLSX.utils.sheet_to_json(workbook.Sheets[firstSheet], { defval: "" }) as ProductRow[];
            const headers = Object.keys(json[0] || {});
            resolve({ headers, data: json, logs: [`Imported ${json.length} rows from ${firstSheet}`] });
        };
        reader.readAsBinaryString(file);
    });
};

export const generateShopifyData = (sourceData: ProductRow[], mapping: Mapping): ProductRow[] => {
    return sourceData.map(row => {
        const newRow: ProductRow = {};
        Object.entries(mapping).forEach(([shopifyField, sourceHeader]) => {
            if (sourceHeader) newRow[shopifyField] = row[sourceHeader];
        });

        // Auto-generate Handle if missing
        if (!newRow['Handle'] && newRow['Title']) {
            newRow['Handle'] = String(newRow['Title'])
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, '-')
                .replace(/^-+|-+$/g, '');
        }

        // Set Shopify defaults for mapped data
        newRow['Option1 Name'] = 'Title';
        newRow['Option1 Value'] = 'Default Title';
        newRow['Published'] = 'true';
        newRow['Status'] = 'active';
        newRow['Variant Inventory Tracker'] = 'shopify';
        newRow['Variant Inventory Policy'] = 'deny';
        newRow['Variant Fulfillment Service'] = 'manual';
        newRow['Variant Requires Shipping'] = 'true';
        newRow['Variant Taxable'] = 'true';
        newRow['Gift Card'] = 'false';

        return newRow;
    });
};

import React, { useState } from 'react';
import { FileUpload } from './components/FileUpload';
import { MappingStep } from './components/MappingStep';
import { PreviewStep } from './components/PreviewStep';
import { parseExcel, generateShopifyData, createProductFromSku } from './services/excelService';
import { AppState, Mapping, ProductRow } from './types';

const App: React.FC = () => {
  const [step, setStep] = useState<AppState>(AppState.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progressMessage, setProgressMessage] = useState('');
  const [sourceHeaders, setSourceHeaders] = useState<string[]>([]);
  const [sourceData, setSourceData] = useState<ProductRow[]>([]);
  const [processedData, setProcessedData] = useState<ProductRow[]>([]);
  const [logs, setLogs] = useState<string[]>([]);

  const handleFileSelect = async (file: File) => {
    setIsProcessing(true);
    setProgressMessage('Analyzing catalog architecture...');
    setTimeout(async () => {
        try {
            const { headers, data, logs: processingLogs } = await parseExcel(file);
            setSourceHeaders(headers);
            setSourceData(data);
            setLogs(processingLogs);
            setStep(AppState.MAPPING);
        } catch (error) {
            console.error(error);
            alert("Error parsing file.");
        } finally {
            setIsProcessing(false);
            setProgressMessage('');
        }
    }, 100);
  };

  const handleManualEntry = async (brand: string, skuInput: string) => {
      const apiKey = process.env.API_KEY;
      if (!apiKey) { alert("API Key environment variable is missing."); return; }

      setIsProcessing(true);
      const skus = skuInput.split(/[\n,]+/).map(s => s.trim()).filter(s => s);
      if (skus.length === 0) { setIsProcessing(false); return; }

      const allData: ProductRow[] = [];
      try {
          for (let i = 0; i < skus.length; i++) {
              const currentSku = skus[i];
              setProgressMessage(`Researching Market (${i + 1}/${skus.length}): ${brand} ${currentSku}...`);

              // Ensure we wait for the AI result
              try {
                  const rows = await createProductFromSku(brand, currentSku, apiKey);
                  if (rows && rows.length > 0) {
                      allData.push(...rows);
                  }
              } catch (err) {
                  console.error(`Research failed for SKU ${currentSku}:`, err);
                  allData.push({
                      'Handle': `${brand}-${currentSku}`.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
                      'Title': `${brand} ${currentSku}`,
                      'Vendor': brand,
                      'Variant SKU': currentSku,
                      'Status': 'draft'
                  });
              }

              // Breathing room for UI and API
              if (skus.length > 1 && i < skus.length - 1) {
                await new Promise(r => setTimeout(r, 800));
              }
          }

          if (allData.length === 0) {
            alert("Unable to generate product data. Please check your SKU and Brand.");
            return;
          }

          setProcessedData(allData);
          setStep(AppState.PREVIEW);
      } catch (error: any) { 
          alert(`Synthesis interrupted: ${error.message}`); 
      } finally { 
          setIsProcessing(false); 
          setProgressMessage('');
      }
  };

  const handleMappingConfirm = async (mapping: Mapping) => {
    const rawShopifyData = generateShopifyData(sourceData, mapping);
    const apiKey = process.env.API_KEY;

    if (apiKey) {
        setIsProcessing(true);
        setProgressMessage('Analyzing dataset for enrichment needs...');

        // Identify rows that are missing ANY key data point (Image, Description, Price, Weight, Barcode)
        // This ensures "fill in anything that's not available"
        const handlesToEnrich = Array.from(new Set(rawShopifyData.filter(r => 
            !r['Image Src'] || r['Image Src'].includes('placehold.co') || 
            !r['Body (HTML)'] || r['Body (HTML)'].length < 20 ||
            !r['Variant Grams'] || 
            !r['Variant Price'] ||
            !r['Variant Barcode']
        ).map(r => r['Handle'])));

        let workingData = [...rawShopifyData];

        if (handlesToEnrich.length > 0) {
            // Process in batches to avoid overwhelming the user (and the UI)
            const enrichmentBatch = handlesToEnrich.slice(0, 50); 

            for (let i = 0; i < enrichmentBatch.length; i++) {
                const handle = enrichmentBatch[i];
                const baseRow = workingData.find(r => r['Handle'] === handle && r['Title']);
                if (!baseRow) continue;

                setProgressMessage(`Enriching Data: ${baseRow['Title']} (${i + 1}/${enrichmentBatch.length})...`);

                try {
                    const brand = baseRow['Vendor'] || '';
                    const sku = baseRow['Variant SKU'] || '';

                    // Pass the existing row as context so AI can "fill in gaps"
                    const rows = await createProductFromSku(brand, sku, apiKey, baseRow);

                    if (rows.length > 0) {
                        const others = workingData.filter(r => r['Handle'] !== handle);
                        // The service now handles merging, so we just take the result
                        workingData = [...others, ...rows];
                    }
                } catch (err) { console.error("Synthesis failed for " + handle, err); }

                await new Promise(r => setTimeout(r, 1500)); 
            }
        }
        setProcessedData(workingData);
        setIsProcessing(false);
    } else {
        setProcessedData(rawShopifyData);
    }

    setStep(AppState.PREVIEW);
  };

  const handleReset = () => {
      setStep(AppState.UPLOAD);
      setSourceData([]);
