export const normalizeVendor = (raw: string): string => {
    if (!raw) return '';
    let v = String(raw).trim().toUpperCase();
    if (v.startsWith('MILWAUKEE')) return 'MILWAUKEE';
    return v;
};

export const cleanImageUrl = (url: any): string => {
  if (!url || typeof url !== 'string') return '';
  let clean = url.trim().replace(/['"]/g, '').replace(/ /g, '%20');

  if (clean.startsWith('//')) clean = 'https:' + clean;
  if (!clean.startsWith('http')) {
     if (clean.includes('/') && (clean.match(/\.(jpg|jpeg|png|webp|gif)/i) || clean.includes('cdn'))) {
        clean = 'https://' + clean;
     } else {
        return '';
     }
  }

  const lower = clean.toLowerCase();

  // Filter out non-permanent or low-quality thumbnails/proxies
  if (lower.includes('gstatic.com') || 
      lower.includes('encrypted-tbn') || 
      lower.includes('googleusercontent.com') || 
      lower.includes('search_thumbnail') ||
      lower.startsWith('data:image')) {
      return '';
  }

  // Allow high-res manufacturer CDNs even if they have common "small" patterns
  const isManufacturerCDN = lower.match(/(milwaukeetool|boschtools|dewalt|makitatools|metabo|ridgid|ryobitools|stihl|husqvarna|atlas-machinery|mcmaster|grainger|homedepotstatic|amazon-adsystem|images-amazon|media-amazon)/i);

  const thumbPatterns = ['/thumb/', '_thumb', '/small/', '/icon/', '/tiny/', '100x100', '50x50', 'icon-', 'SL100', 'SL50'];
  if (!isManufacturerCDN && thumbPatterns.some(p => lower.includes(p)) && !lower.includes('original') && !lower.includes('1000x1000') && !lower.includes('1500x1500')) {
    return '';
  }

  const junkPatterns = [
    'favicon', 'banner', 'spacer', 'pixel', 'loading', 'missing', 
    'placeholder', 'no-image', 'noimage', 'swatch', 'badge', 'facebook', 'twitter', 
    'instagram', 'youtube', 'linkedin', 'cart', 'header', 'footer', 'button'
  ];

  if (junkPatterns.some(p => lower.includes(p))) {
      const isActuallyProduct = lower.includes('productimages') || lower.includes('media/') || lower.includes('images/') || lower.includes('assets/products/') || lower.includes('p-detail');
      if (!isActuallyProduct) return '';
  }

  const validCdn = lower.match(/(edgenet|widen|cloudinary|scene7|cdn|azureedge|cloudfront|amazon|shopify|bigcommerce|akamai|fastly|milwaukeetool|bosch|dewalt|mcmaster|grainger|homedepotstatic|atlas-machinery|ruralking|tractorsupply|lowes|walmart|mscdirect|fastenal|zoro|images-amazon|media-amazon|boschtools|dewalt.com|graingerstatic|mcmasterstatic|factorypure|globalindustrial|mscdirect|supplyhouse|rockler|woodcraft|tool|equipment|hardware)/i);
  const validExt = lower.match(/\.(jpg|jpeg|png|webp|bmp|tiff|avif)(\?|$)/i);

  if (!validCdn && !validExt) return '';

  return clean;
};

export const createProductFromSku = async (brand: string, sku: string, apiKey: string, existingContext: ProductRow = {}): Promise<ProductRow[]> => {
    const MAX_RETRIES = 3;
    let attempt = 0;

    // Prepare context string for AI
    const hasContext = Object.keys(existingContext).length > 0;
    const contextStr = hasContext 
        ? `EXISTING DATA (Prioritize this if valid, but fill gaps and fix formatting): ${JSON.stringify({
            title: existingContext['Title'],
            description_text: existingContext['Body (HTML)']?.replace(/<[^>]*>?/gm, ''), // Pass raw text to check for keywords
            price: existingContext['Variant Price'],
            weight: existingContext['Variant Grams'],
            barcode: existingContext['Variant Barcode'],
            image: existingContext['Image Src']
        })}` 
        : 'NO EXISTING DATA.';

    while (attempt < MAX_RETRIES) {
        attempt++;
        try {
            const ai = new GoogleGenAI({ apiKey });

            const prompt = `Act as an elite world-class industrial product data architect and lead SEO strategist. 
            Your mission: Synthesize the absolute highest quality product data for: "${brand} ${sku}".

            ${contextStr}

            1. CANADIAN MARKET INTELLIGENCE:
            - If price is missing in EXISTING DATA, research exact current pricing (MSRP) from Canadian competitors.
            - Resulting price MUST be in CAD (numbers only).

            2. DEEP INDUSTRIAL METADATA:
            - Official GTIN/UPC Barcode (Verify EXISTING DATA if present).
            - Product Weight in Grams (Fill if missing).
            - Country of Origin (2-letter ISO).
            - HS Tariff Code.
            - Google Product Category (e.g. Hardware > Tools > ...).
            - Product Type (e.g. Cordless Drills, Miter Saws).

            3. CONTENT ARCHITECTURE (HTML):
            - Professional HTML Description.
            - If EXISTING DATA has a description, ENHANCE it into professional HTML with headers.
            - Sections: 
              1. Introductory paragraph (Start directly with the text. DO NOT use a heading like "Product Overview" or "Overview").
              2. Performance Features (<ul>).
              3. Technical Specifications (<table>).
              4. What's Included.

            4. SEO:
            - Title: "[Brand] [SKU] [Product Name]".
            - Tags: Comma separated.

            5. ASSETS:
            - Direct, high-res image URLs (no thumbnails).
            - If EXISTING DATA has an image, validate it. If it's a placeholder, find a real one.

            OUTPUT JSON ONLY:
            {
              "title": "...",
              "price_cad": "...",
              "body_html": "...",
              "barcode": "...",
              "weight_grams": "...",
              "tags": "...",
              "product_type": "...",
              "country_of_origin": "...",
              "hs_code": "...",
              "google_category": "...",
              "seo_title": "...",
              "seo_description": "...",
              "included_in_box": ["..."],
              "product_page_url": "...",
              "competitor_urls": ["..."],
              "images": ["url1", "..."]
            }`;

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview', 
                contents: prompt,
                config: { 
                    tools: [{googleSearch: {}}]
                }
            });

            const text = response.text || '';
            if (!text) throw new Error("Received empty response from Gemini API");

            const firstBrace = text.indexOf('{');
            const lastBrace = text.lastIndexOf('}');
            const jsonStr = (firstBrace !== -1 && lastBrace !== -1) 
                ? text.substring(firstBrace, lastBrace + 1) 
                : '{}';

            let data: any = {};
            try {
                data = JSON.parse(jsonStr);
            } catch (parseError) {
                 const match = text.match(/\{[\s\S]*\}/);
                 if (match) {
                     try { data = JSON.parse(match[0]); } catch(e) {}
                 }
            }

            // Merge existing valid image if present
            let rawImages = (Array.isArray(data.images) ? data.images : []);
            if (existingContext['Image Src'] && !existingContext['Image Src'].includes('placehold.co')) {
                rawImages = [existingContext['Image Src'], ...rawImages];
            }

            const validImages = rawImages.map(cleanImageUrl).filter((u: string) => u);
            // Dedupe
            const uniqueImages = Array.from(new Set(validImages));

            const handle = (data.title || existingContext['Title'] || `${brand}-${sku}`).toLowerCase()
                .replace(/[^a-z0-9]+/g, '-')
                .replace(/^-+|-+$/g, '');

            const safeRawAssets = rawImages.filter((u: any) => typeof u === 'string' && u && !u.startsWith('data:image') && u.length < 3000);

            // Use existing price if valid and AI didn't find one or if existing is preferred
            const aiPrice = data.price_cad ? String(data.price_cad).replace(/[^0-9.]/g, '') : '';
            const existingPrice = existingContext['Variant Price'] ? String(existingContext['Variant Price']).replace(/[^0-9.]/g, '') : '';
            const finalPrice = existingPrice && parseFloat(existingPrice) > 0 ? existingPrice : aiPrice;

            const aiGrams = data.weight_grams ? String(data.weight_grams).replace(/[^0-9]/g, '') : '';
            const existingGrams = existingContext['Variant Grams'] ? String(existingContext['Variant Grams']).replace(/[^0-9]/g, '') : '';
            const finalGrams = existingGrams && parseInt(existingGrams) > 0 ? existingGrams : aiGrams;

            const finalBarcode = (existingContext['Variant Barcode'] && String(existingContext['Variant Barcode']).length > 6) 
                ? existingContext['Variant Barcode'] 
                : (data.barcode ? `'${data.barcode}` : '');

            // Clean Body HTML to ensure "Product Overview" header is removed if AI generates it
            let cleanBody = data.body_html || existingContext['Body (HTML)'] || '';
            cleanBody = cleanBody
                .replace(/<h3>Product Overview<\/h3>/gi, '')
                .replace(/<h3>Overview<\/h3>/gi, '')
                .replace(/<h2>Product Overview<\/h2>/gi, '')
                .replace(/<h2>Overview<\/h2>/gi, '');

            // Construct standard Shopify row
            const mainRow: ProductRow = {
                'Handle': handle,
                'Title': data.title || existingContext['Title'] || `${brand} ${sku}`,
                'Body (HTML)': cleanBody,
                'Vendor': normalizeVendor(brand),
                'Product Category': data.google_category || existingContext['Product Category'] || 'Hardware > Tools',
                'Type': data.product_type || existingContext['Type'] || 'Hardware',
                'Tags': data.tags || existingContext['Tags'] || '',
                'Published': 'true',
                'Option1 Name': 'Title',
                'Option1 Value': 'Default Title',
                'Variant SKU': sku,
                'Variant Grams': finalGrams,
                'Variant Inventory Tracker': 'shopify',
                'Variant Inventory Policy': 'deny', 
                'Variant Fulfillment Service': 'manual',
                'Variant Price': finalPrice,
                'Variant Compare At Price': existingContext['Variant Compare At Price'] || '',
                'Variant Requires Shipping': 'true',
                'Variant Taxable': 'true',
                'Variant Barcode': finalBarcode,
                'Image Src': uniqueImages[0] || '',
                'Image Position': 1,
                'Image Alt Text': '',
                'Gift Card': 'false',
                'SEO Title': data.seo_title || existingContext['SEO Title'] || '',
                'SEO Description': data.seo_description || existingContext['SEO Description'] || '',
                'Google Shopping / Google Product Category': data.google_category || '',
                'Google Shopping / Condition': 'new',
                'Variant Weight Unit': 'g',
                'Status': 'active',
                '_Raw_Assets': safeRawAssets.join(' | '),
                '_Product_Page': data.product_page_url || '',
                '_Competitor_Links': (data.competitor_urls || []).join(' | '),
                'Included In Box': (data.included_in_box || []).join(', ')
            };

            const extraRows = uniqueImages.slice(1).map((img: string, i: number) => ({
                'Handle': handle,
                'Image Src': img,
                'Image Position': i + 2,
                'Image Alt Text': ''
            }));

            return [mainRow, ...extraRows];

        } catch (e: any) {
            console.error(`AI Research Attempt ${attempt} failed:`, e);
            if (attempt === MAX_RETRIES) {
                // Return original context if AI fails completely
                return [{
                    ...existingContext,
                    'Handle': `${brand}-${sku}`.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''),
                    'Title': existingContext['Title'] || `${brand} ${sku}`,
                    'Vendor': normalizeVendor(brand),
                    'Variant SKU': sku,
                    'Status': 'draft'
                }];
            }
            await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000));
        }
    }
    return [];
};

