                            </div>
                            <div className="p-4 bg-white border border-slate-200 rounded-2xl shadow-sm">
                                <div className="text-[8px] font-black text-slate-400 uppercase mb-1">Taxonomy & Tags</div>
                                <div className="text-[10px] font-bold text-slate-600 mt-1">{selectedProduct['Google Product Category'] || 'Hardware'}</div>
                                <div className="text-[9px] font-medium text-slate-400 mt-1.5">{selectedProduct['Tags']}</div>
                            </div>
                        </div>
                    </div>

                    {/* Industrial Description Viewer */}
                    <div className="space-y-4 pb-12">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block">Synthesized Product Copy</label>
