                            <div className="absolute top-0 right-0 p-4">
                                <div className="w-12 h-1 text-emerald-500 rounded-full"></div>
                            </div>
                            <div 
                                className="description-viewer prose prose-slate prose-sm max-w-none text-[13px] leading-relaxed text-slate-800" 
                                dangerouslySetInnerHTML={{ __html: selectedProduct['Body (HTML)'] || 'Research phase incomplete.' }} 
                            />
