        .description-viewer th { text-align: left; padding: 12px 16px; background: #e2e8f0; text-transform: uppercase; font-size: 9px; font-weight: 900; color: #475569; }
        .description-viewer td { text-align: left; padding: 12px 16px; border-bottom: 1px solid #e2e8f0; font-weight: 700; color: #334155; }
